async function loadHabeaResultsPanel() {
  var panel = document.getElementById('habeaResultsPanel');
  if (!panel) return;
  panel.innerHTML = '<div style="padding:24px;text-align:center;color:#8A94A6"><i class="ti ti-loader"></i> Ачааллаж байна...</div>';
  try {
    var hdb = getHabeaDb();
    if (!hdb) throw new Error('Firebase холбогдсонгүй');
    var snap = await hdb.collection('habea_exam_results').get();
    var rows = [];
    snap.forEach(function (d) {
      var x = d.data() || {};
      var ts = x.timestamp;
      var tsMs = ts ? (ts.seconds ? ts.seconds * 1000 : (typeof ts === 'number' ? ts : 0)) : 0;
      rows.push({ id: d.id, name: x.name || '—', dept: x.department || '—', pos: x.position || '—', pct: x.percent || 0, passed: !!x.passed, tsMs: tsMs });
    });
    rows.sort(function (a, b) { return b.tsMs - a.tsMs; });
    if (!rows.length) {
      panel.innerHTML = '<div class="empty-state" style="padding:24px"><i class="ti ti-clipboard-off"></i><div>Шалгалт байхгүй</div></div>';
      return;
    }
    function fmtHabeaTs(ms) {
      if (!ms) return '—';
      var d = new Date(ms);
      return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
    }
    panel.innerHTML = '<div class="tbl-wrap"><table><thead><tr><th>#</th><th>Нэр</th><th>Хэлтэс</th><th>Тушаал</th><th>%</th><th>Дүн</th><th>Огноо</th><th></th></tr></thead><tbody>' +
      rows.map(function (r, i) {
        return '<tr>' +
          '<td style="color:#8A94A6;font-size:12px;font-weight:700">' + (i + 1) + '</td>' +
          '<td style="font-weight:600">' + esc(r.name) + '</td>' +
          '<td>' + esc(r.dept) + '</td>' +
          '<td>' + esc(r.pos) + '</td>' +
          '<td style="font-weight:800;color:' + (r.passed ? 'var(--green)' : 'var(--red)') + '">' + r.pct + '%</td>' +
          '<td><span style="font-size:11px;font-weight:600;color:' + (r.passed ? 'var(--green)' : 'var(--red)') + '">' + (r.passed ? 'Тэнцсэн' : 'Тэнцээгүй') + '</span></td>' +
          '<td style="font-size:12px;color:#8A94A6">' + fmtHabeaTs(r.tsMs) + '</td>' +
          '<td><button class="btn btn-ghost btn-xs" style="color:var(--red)" onclick="deleteHabeaResult(\'' + r.id + '\')">Устгах</button></td>' +
          '</tr>';
      }).join('') +
      '</tbody></table></div>';
  } catch (e) {
    panel.innerHTML = '<div class="empty-state" style="padding:20px"><i class="ti ti-alert-circle"></i><div>' + esc(String(e.message || 'Алдаа')) + '</div></div>';
  }
}
async function deleteHabeaResult(id) {
  if (!confirm('Энэ шалгалтын бичлэгийг устгахдаа итгэлтэй байна уу?')) return;
  try {
    var hdb = getHabeaDb(); if (!hdb) throw new Error('db');
    await hdb.collection('habea_exam_results').doc(id).delete();
    toast('Устгагдлаа ✓', 'success');
    loadHabeaResultsPanel();
  } catch (e) { toast('Алдаа гарлаа', 'err'); }
}

/* ============ Бүлэг (гадны) сургалт нэмэх — Excel/CSV-ээр хамрагдалт ============ */
function loadSheetJS(cb) {
  if (typeof XLSX !== 'undefined') { cb(true); return; }
  var s = document.createElement('script');
  s.src = 'https://cdn.jsdelivr.net/npm/xlsx@0.18.5/dist/xlsx.full.min.js';
  s.onload = function () { cb(true); };
  s.onerror = function () { cb(false); };
  document.head.appendChild(s);
}
function parseSpreadsheet(file, cb) {
  var name = (file.name || '').toLowerCase();
  if (/\.csv$/.test(name) || file.type === 'text/csv') {
    var rd = new FileReader();
    rd.onload = function (ev) { try { cb(parseCSV(ev.target.result)); } catch (e) { cb(null); } };
    rd.onerror = function () { cb(null); };
    rd.readAsText(file, 'UTF-8'); return;
  }
  loadSheetJS(function (ok) {
    if (!ok) { cb(null, 'Excel уншигч ачаалж чадсангүй (интернэт шалгана уу). Файлаа CSV болгож оруулж болно.'); return; }
    var rd = new FileReader();
    rd.onload = function (ev) {
      try {
        var wb = XLSX.read(new Uint8Array(ev.target.result), { type: 'array' });
        var ws = wb.Sheets[wb.SheetNames[0]];
        var rows = XLSX.utils.sheet_to_json(ws, { header: 1, raw: false, defval: '' });
        cb(rows.map(function (r) { return (r || []).map(function (c) { return c == null ? '' : String(c); }); }));
      } catch (e) { cb(null, e.message); }
    };
    rd.onerror = function () { cb(null); };
    rd.readAsArrayBuffer(file);
  });
}
function etSameAttendee(a, b) {
  return (a.uid && b.uid && a.uid === b.uid) || (a.id && b.id && a.id === b.id) || _sameEmail(a.email, b.email) ||
    (a.name && b.name && String(a.name).toLowerCase() === String(b.name).toLowerCase());
}
function applyBatchTraining(rows, fallbackTitle) {
  var res = { trainings: 0, mergedTo: 0, enrolled: 0, unmatched: [] };
  if (!rows || !rows.length) return res;
  var header = (rows[0] || []).map(function (x) { return String(x).toLowerCase().trim(); });
  var hasHeader = header.some(function (h) { return /сургалт|training|курс|ажилтан|нэр|имэйл|email|код|code|name/.test(h); });
  var iTitle = -1, iEmp = -1;
  if (hasHeader) {
    header.forEach(function (h, i) {
      if (iTitle < 0 && /сургалт|training|курс/.test(h)) iTitle = i;
      else if (iEmp < 0 && /ажилтан|нэр|имэйл|email|код|code|name/.test(h)) iEmp = i;
    });
  }
  if (iEmp < 0) iEmp = (iTitle === 0 ? 1 : 0);
  var data = hasHeader ? rows.slice(1) : rows;
  var groups = {};
  data.forEach(function (r) {
    if (!r || !r.length) return;
    var title = (iTitle >= 0 ? String(r[iTitle] || '').trim() : '') || (fallbackTitle || '').trim() || 'Гадны сургалт';
    var key = String(r[iEmp] != null ? r[iEmp] : '').trim();
    if (!key) return;
    (groups[title] = groups[title] || []).push(key);
  });
  Object.keys(groups).forEach(function (title) {
    var attendees = [];
    groups[title].forEach(function (k) {
      var emp = matchVideoEmp(k);
      if (emp) {
        var a = { id: emp.id || '', uid: emp.uid || '', email: emp.email || '', name: emp.name };
        if (!attendees.some(function (x) { return etSameAttendee(x, a); })) attendees.push(a);
      } else res.unmatched.push(k);
    });
    var existing = (DB.externalTrainings || []).filter(function (t) { return String(t.title).toLowerCase() === title.toLowerCase(); })[0];
    if (existing) {
      attendees.forEach(function (a) { if (!existing.attendees.some(function (x) { return etSameAttendee(x, a); })) existing.attendees.push(a); });
      res.mergedTo++;
    } else {
      DB.externalTrainings.push({ id: nextId('ET', DB.externalTrainings), title: title, date: todayISO(), attendees: attendees });
      res.trainings++;
    }
    res.enrolled += attendees.length;
  });
  if (res.trainings || res.mergedTo) { saveDB(); renderEmployees(); renderKpiPage(); renderDashboard(); }
  return res;
}
function actionBatchTraining() {
  if (!isAdmin()) { toast('Зөвхөн ХАБЭА ажилтан энэ үйлдэл хийнэ', 'warn'); return; }
  var node = elc('div', 'modal-info');
  var existing = DB.externalTrainings || [];
  node.innerHTML =
    '<p style="font-size:14px;line-height:1.5">Гадны (бүлэг) сургалтад хамрагдсан ажилтнуудыг <strong>Excel/CSV</strong>-ээр оруулна. Файл доторх ажилтнууд тухайн сургалтад автоматаар хамрагдсан болж, KPI-ийн сургалтын оноо нь нэмэгдэнэ.</p>' +
    '<div class="rf-field" style="margin-top:10px"><label>Сургалтын нэр (файлд багана байхгүй бол)</label><input type="text" id="btTitle" class="rf-input" placeholder="ж: Галын аюулгүй байдлын сургалт"></div>' +
    '<label class="rf-photo" id="btLbl" style="margin-top:6px"><input type="file" accept=".csv,.xlsx,.xls" id="btFile" hidden><i class="ti ti-file-spreadsheet"></i><span>Excel/CSV файл сонгох</span></label>' +
    '<div class="rf-hint" style="margin-top:10px"><i class="ti ti-info-circle"></i> Багана: <strong>ажилтан</strong> (нэр/имэйл/код). Олон сургалт бол <strong>сургалт, ажилтан</strong> гэсэн 2 баганатай байж болно.</div>' +
    '<button class="btn btn-secondary btn-sm" id="btTpl" style="margin-top:4px"><i class="ti ti-download"></i> Загвар татах</button>' +
    (existing.length ? '<div style="margin-top:14px;border-top:1px solid #EEF1F4;padding-top:10px"><div style="font-size:12px;color:#8A94A6;margin-bottom:6px">Нэмэгдсэн сургалтууд (' + existing.length + ')</div>' +
      existing.slice(0, 10).map(function (t) { return '<div style="display:flex;justify-content:space-between;font-size:13px;padding:3px 0"><span>' + esc(t.title) + '</span><span style="color:#8A94A6">' + (t.attendees || []).length + ' ажилтан</span></div>'; }).join('') + '</div>' : '');
  node.addEventListener('click', function (ev) {
    if (ev.target.closest('#btTpl')) {
      var tpl = '﻿сургалт,ажилтан\nГалын аюулгүй байдлын сургалт,EMP-002\nГалын аюулгүй байдлын сургалт,tuya@mn\nӨндөрт ажиллах сургалт,EMP-004\n';
      download('buleg-surgalt-zagvar.csv', tpl, 'text/csv;charset=utf-8');
    }
  });
  $('#btFile', node).addEventListener('change', function () {
    var f = this.files && this.files[0]; if (!f) return;
    var lbl = $('#btLbl span', node); if (lbl) lbl.textContent = f.name + ' — боловсруулж байна…';
    parseSpreadsheet(f, function (rows, err) {
      if (!rows) { toast(err || 'Файл уншиж чадсангүй', 'error'); if (lbl) lbl.textContent = 'Excel/CSV файл сонгох'; return; }
      var res = applyBatchTraining(rows, $('#btTitle', node).value);
      closeModal();
      infoModal('Бүлэг сургалт нэмэгдлээ', '<div style="font-size:14px;line-height:1.7">' +
        '<div>📚 Шинэ сургалт: <strong>' + res.trainings + '</strong>' + (res.mergedTo ? ' · нэмж нэгтгэсэн: ' + res.mergedTo : '') + '</div>' +
        '<div>✅ Хамрагдсан гэж тэмдэглэсэн: <strong>' + res.enrolled + '</strong> ажилтан</div>' +
        '<div>⚠️ Тохирохгүй (ажилтан олдоогүй): <strong>' + res.unmatched.length + '</strong>' + (res.unmatched.length ? ' <span style="color:#94A3B8;font-size:12px">(' + esc(res.unmatched.slice(0, 8).join(', ')) + (res.unmatched.length > 8 ? '…' : '') + ')</span>' : '') + '</div>' +
        '<div style="margin-top:8px;color:#64748B;font-size:13px">Эдгээр ажилтны KPI-ийн сургалтын оноо автоматаар шинэчлэгдлээ.</div></div>');
    });
  });
  buildModal('Бүлэг сургалт нэмэх (Excel/CSV)', node, { width: '470px' });
}

/* ============ Графикууд ============ */
var charts = { radar: null, trend: null };

/* Сүүлийн 12 сарын ЖИНХЭНЭ хандлага — бодит бичлэгээс тооцно (хиймэл дата биш) */
function monthlyTrendData() {
  var now = new Date();
  var labels = [], keys = [];
  var MN = ['1-р', '2-р', '3-р', '4-р', '5-р', '6-р', '7-р', '8-р', '9-р', '10-р', '11-р', '12-р'];
  for (var i = 11; i >= 0; i--) {
    var d = new Date(now.getFullYear(), now.getMonth() - i, 1);
    labels.push(MN[d.getMonth()] + ' сар');
    keys.push(d.getFullYear() + '-' + (d.getMonth() + 1));
  }
  function mk(iso) { if (!iso) return null; var d = new Date(iso); return isNaN(d.getTime()) ? null : d.getFullYear() + '-' + (d.getMonth() + 1); }
  function zeros() { return keys.map(function () { return 0; }); }
  var training = zeros(), risk = zeros(), incident = zeros();
  function bump(arr, iso) { var idx = keys.indexOf(mk(iso)); if (idx > -1) arr[idx]++; }

  // Эрсдэл = аюул/near-miss мэдээлэл + эрсдэлийн бүртгэл
  (DB.reports || []).forEach(function (r) { bump(risk, r.createdAt); });
  (DB.hazards || []).forEach(function (h) { bump(risk, h.createdAt); });
  // Осол
  (DB.incidents || []).forEach(function (n) { bump(incident, n.date || n.createdAt); });
  // Сургалт = модулийн шалгалт өгсөн + LMS видео сургалт тэнцсэн
  Object.keys(DB.empProgress || {}).forEach(function (k) {
    var p = DB.empProgress[k]; if (p && p.examTakenAt) bump(training, p.examTakenAt);
  });
  if (LMS.loaded) {
    Object.keys(LMS.progByUser || {}).forEach(function (uid) {
      var m = LMS.progByUser[uid];
      Object.keys(m).forEach(function (tid) {
        var p = m[tid];
        if (p && p.status === 'passed') bump(training, p.passedAt || p.completedAt || p.updatedAt || p.lastViewedAt);
      });
    });
  }
  return { labels: labels, training: training, risk: risk, incident: incident };
}

/* Дашбоардын үндсэн график — хүснэгтийн БҮХ үзүүлэлтийн одоогийн дундаж дүн (0-100) */
function empIntTrainingPct(e) {
  var keys = Object.keys(TRAINING_MODULES).filter(function (k) { return isModTrainingVisible(e, k); });
  if (!keys.length) return null;
  var done = keys.filter(function (k) { return getEmpProg(e.id, k).trainingCompleted; }).length;
  return Math.round(done / keys.length * 100);
}
function empExtTrainingPct(e) {
  var ext = DB.extTrainings || [];
  if (!ext.length) return null;
  var att = ext.filter(function (t) { return getExtAtt(t.id, e.id).status === 'attended'; }).length;
  return Math.round(att / ext.length * 100);
}
function empSafetyScore(e) {
  var vals = [deptPpe(e.dept), deptFirstAid(e.dept)].filter(function (v) { return v != null; });
  return vals.length ? Math.round(avg(vals)) : null;
}
var DASH_CATS = [
  { label: 'Дотоод сургалт', rgb: '29,78,216',  fn: empIntTrainingPct, desc: 'Дотоод 5 модулийн дуусгасан хувь' },
  { label: 'Гадны сургалт',  rgb: '22,101,52',  fn: empExtTrainingPct, desc: 'Гадны сургалтад хамрагдсан хувь' },
  { label: 'Видео сургалт',  rgb: '194,65,12',  fn: kpiVideo,          desc: 'Оногдсон видео сургалтаас тэнцсэн хувь' },
  { label: 'Аюул/NM',        rgb: '162,28,175', fn: empBonusScore,     desc: 'Аюул/near-miss мэдээллийн бонус оноо' },
  { label: 'ХХХ·Тусламж',    rgb: '8,145,178',  fn: empSafetyScore,    desc: 'Албаны ХХХ мөрдөлт + анхны тусламж' },
  { label: 'Даалгавар',      rgb: '22,163,74',  fn: kpiTask,           desc: 'Оногдсон даалгаврын биелэлт' }
];
var DASH_CAT_DEPT = ''; // '' = бүх алба; интерактив шүүлт
function _dashEmps() {
  var list = DB.employees || [];
  return DASH_CAT_DEPT ? list.filter(function (e) { return e.dept === DASH_CAT_DEPT; }) : list;
}
function _avgOf(emps, fn) {
  var vals = emps.map(fn).filter(function (v) { return v != null; });
  return vals.length ? Math.round(avg(vals)) : 0;
}
function kpiCategoryBars() {
  var emps = _dashEmps();
  return DASH_CATS.map(function (c) { return { label: c.label, rgb: c.rgb, v: _avgOf(emps, c.fn) }; });
}

/* Багана дээр дарахад — тухайн үзүүлэлтийн алба тус бүрийн задаргаа + анхаарал шаардлагатай ажилтнууд */
function openCategoryDrilldown(idx) {
  var cat = DASH_CATS[idx]; if (!cat) return;
  var depts = deptList().map(function (d) {
    var em = (DB.employees || []).filter(function (e) { return e.dept === d; });
    return { d: d, v: _avgOf(em, cat.fn), n: em.length };
  }).sort(function (a, b) { return b.v - a.v; });
  var deptMax = Math.max(1, depts.reduce(function (a, x) { return Math.max(a, x.v); }, 0));

  var lowEmps = _dashEmps().map(function (e) { return { e: e, v: cat.fn(e) }; })
    .filter(function (x) { return x.v != null; })
    .sort(function (a, b) { return a.v - b.v; }).slice(0, 8);

  function col(v) { return v >= 85 ? '#16A34A' : v >= 60 ? '#D97706' : '#DC2626'; }
  var deptRows = depts.map(function (r) {
    return '<div style="display:flex;align-items:center;gap:10px;padding:6px 0">' +
      '<div style="width:130px;font-size:12.5px;font-weight:600;color:#1E293B;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="' + esc(r.d) + '">' + esc(r.d) + '</div>' +
      '<div style="flex:1;height:16px;background:#F1F5F9;border-radius:8px;overflow:hidden"><div style="height:100%;width:' + Math.round(r.v / deptMax * 100) + '%;background:' + col(r.v) + ';border-radius:8px;transition:width .4s"></div></div>' +
      '<div style="width:40px;text-align:right;font-weight:700;font-size:13px;color:' + col(r.v) + '">' + r.v + '</div></div>';
  }).join('') || '<div style="color:#94A3B8;font-size:13px;padding:8px">Алба бүртгэгдээгүй</div>';

  var empRows = lowEmps.length ? lowEmps.map(function (x) {
    return '<div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid #F1F5F9">' +
      '<div class="avatar avatar-sm" style="width:28px;height:28px;font-size:11px">' + esc(x.e.initials || '') + '</div>' +
      '<div style="flex:1;min-width:0"><div style="font-size:13px;font-weight:600;color:#1E293B">' + esc(x.e.name) + '</div>' +
      '<div style="font-size:11px;color:#94A3B8">' + esc(x.e.dept || '') + '</div></div>' +
      '<span style="font-weight:700;font-size:13px;color:' + col(x.v) + '">' + x.v + '</span></div>';
  }).join('') : '<div style="color:#94A3B8;font-size:13px;padding:8px">Дата алга</div>';

  var node = elc('div');
  node.innerHTML =
    '<div style="font-size:12.5px;color:#64748B;margin-bottom:14px">' + esc(cat.desc) +
    (DASH_CAT_DEPT ? ' · <b>' + esc(DASH_CAT_DEPT) + '</b>' : '') + '</div>' +
    '<div style="font-size:12px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">Алба тус бүрээр</div>' +
    deptRows +
    '<div style="font-size:12px;font-weight:700;color:#475569;text-transform:uppercase;letter-spacing:.5px;margin:18px 0 4px">Анхаарал шаардлагатай ажилтнууд</div>' +
    empRows;
  buildModal(cat.label + ' — дэлгэрэнгүй', node, { width: '620px' });
}

function renderCharts() {
  if (typeof Chart === 'undefined') {
    $$('#kpiRadar, #trendChart').forEach(function (c) {
      if (c && !c.dataset.fb) {
        c.dataset.fb = '1';
        var d = elc('div', 'chart-fallback', '<i class="ti ti-chart-dots"></i> График ачаалж чадсангүй');
        c.parentNode.insertBefore(d, c.nextSibling);
      }
    });
    return;
  }
  var radarEl = $('#kpiRadar');
  if (radarEl) {
    if (charts.radar) charts.radar.destroy();
    var cat = categoryAverages();
    var cur = [cat.bosgo, cat.davtan, cat.video, cat.task, cat.bonus];
    var prev = cur.map(function (v) { return Math.max(0, v - 3 - Math.round(Math.random() * 2)); });
    charts.radar = new Chart(radarEl.getContext('2d'), {
      type: 'radar',
      data: {
        labels: [['Босго'], ['Давтан'], ['Видео'], ['Даалгавар'], ['Бонус']],
        datasets: [
          { label: 'Энэ сар', data: cur, backgroundColor: 'rgba(4,120,87,0.15)', borderColor: 'rgba(4,120,87,1)',
            borderWidth: 2, pointBackgroundColor: 'rgba(4,120,87,1)', pointRadius: 4, pointHoverRadius: 6 },
          { label: 'Өмнөх сар', data: prev, backgroundColor: 'rgba(217,119,6,0.08)', borderColor: 'rgba(217,119,6,0.6)',
            borderWidth: 1.5, borderDash: [4, 4], pointBackgroundColor: 'rgba(217,119,6,1)', pointRadius: 3 }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { position: 'bottom', labels: { font: { family: 'Manrope', size: 12 }, padding: 14, usePointStyle: true } } },
        scales: { r: { min: 0, max: 100, ticks: { stepSize: 25, display: false },
          grid: { color: 'rgba(26,24,21,0.06)' }, angleLines: { color: 'rgba(26,24,21,0.08)' },
          pointLabels: { font: { family: 'Manrope', size: 11, weight: '600' }, color: '#1A1815' } } }
      }
    });
  }
  // Алба сонгох dropdown — интерактив шүүлт
  var deptSel = $('#dashCatDept');
  if (deptSel) {
    if (!deptSel._wired) {
      deptSel._wired = true;
      deptSel.addEventListener('change', function () { DASH_CAT_DEPT = this.value; renderCharts(); });
    }
    var opts = '<option value="">Бүх алба</option>' + deptList().map(function (d) {
      return '<option value="' + esc(d) + '"' + (d === DASH_CAT_DEPT ? ' selected' : '') + '>' + esc(d) + '</option>';
    }).join('');
    if (deptSel.innerHTML !== opts) deptSel.innerHTML = opts;
    deptSel.value = DASH_CAT_DEPT;
  }

  var trendEl = $('#trendChart');
  if (trendEl) {
    if (charts.trend) charts.trend.destroy();
    var cats = kpiCategoryBars();
    charts.trend = new Chart(trendEl.getContext('2d'), {
      type: 'bar',
      data: {
        labels: cats.map(function (c) { return c.label; }),
        datasets: [{
          label: 'Дундаж дүн',
          data: cats.map(function (c) { return c.v; }),
          backgroundColor: function (ctx) {
            var rgb = cats[ctx.dataIndex].rgb, ch = ctx.chart, area = ch.chartArea;
            if (!area) return 'rgba(' + rgb + ',0.9)';
            var g = ch.ctx.createLinearGradient(area.left, 0, area.right, 0);
            g.addColorStop(0, 'rgba(' + rgb + ',0.75)'); g.addColorStop(1, 'rgba(' + rgb + ',1)');
            return g;
          },
          hoverBackgroundColor: cats.map(function (c) { return 'rgba(' + c.rgb + ',1)'; }),
          borderRadius: 8, borderSkipped: false, maxBarThickness: 34, categoryPercentage: 0.72, barPercentage: 0.9
        }]
      },
      options: {
        indexAxis: 'y',
        responsive: true, maintainAspectRatio: false,
        layout: { padding: { right: 12 } },
        onClick: function (evt, els) { if (els && els.length) openCategoryDrilldown(els[0].index); },
        onHover: function (evt, els) { evt.native.target.style.cursor = (els && els.length) ? 'pointer' : 'default'; },
        plugins: {
          legend: { display: false },
          tooltip: {
            backgroundColor: '#1A1815', padding: 12, cornerRadius: 10, displayColors: false,
            titleFont: { family: 'Manrope', size: 13, weight: '600' }, bodyFont: { family: 'Manrope', size: 13 },
            callbacks: { label: function (c) { return 'Дундаж: ' + c.parsed.x + ' / 100 · дэлгэрэнгүйг үзэхээр дарна уу'; } }
          }
        },
        scales: {
          x: { beginAtZero: true, max: 100, grid: { color: 'rgba(26,24,21,0.05)', drawTicks: false }, border: { display: false },
            ticks: { font: { family: 'Manrope', size: 11 }, color: '#908A80', stepSize: 25, padding: 6, callback: function (v) { return v + '%'; } } },
          y: { grid: { display: false }, border: { display: false },
            ticks: { font: { family: 'Manrope', size: 12.5, weight: '600' }, color: '#1A1815', padding: 6 } }
        }
      }
    });
  }
}

/* ============ Бүгдийг дахин зурах ============ */
/* ============ Видео сургалт (MiSkill) — тусдаа цэс ============ */
/* ============ MiSkill дата оноо тооцоолол ============ */
function miskillScore(r) {
  var tPct = r.trainReq > 0 ? Math.min(1, r.trainDone / r.trainReq) : (r.trainDone > 0 ? 1 : 0);
  var ePct = r.examReq > 0 ? Math.min(1, r.examDone / r.examReq) : (r.examDone > 0 ? 1 : 0);
  return Math.round((tPct * 70 + ePct * 30) * 100);
}
function miskillFindMyRow() {
  var me = myEmp();
  var stats = DB.miskillStats || [];
  if (!me) return null;
  return stats.find(function (r) {
    return r.empId === me.id || _sameEmail(r.empEmail, me.email) || r.empName === me.name;
  }) || null;
}
function msPct(done, req) { return req > 0 ? Math.min(100, Math.round(done / req * 100)) : (done > 0 ? 100 : 0); }
function msColor(pct) { return pct >= 90 ? '#16A34A' : pct >= 60 ? '#D97706' : '#DC2626'; }
function msBg(pct) { return pct >= 90 ? '#D1FAE5' : pct >= 60 ? '#FEF3C7' : '#FEE2E2'; }
function msLabel(pct) { return pct >= 90 ? 'Маш сайн' : pct >= 60 ? 'Хангалттай' : 'Анхаарал шаардлагатай'; }

function msProgressRing(pct, color, size) {
  size = size || 80;
  var r = (size - 10) / 2, circ = 2 * Math.PI * r;
  var dash = circ * Math.min(pct, 100) / 100;
  return '<svg width="' + size + '" height="' + size + '" viewBox="0 0 ' + size + ' ' + size + '">' +
    '<circle cx="' + (size/2) + '" cy="' + (size/2) + '" r="' + r + '" fill="none" stroke="#E2E8F0" stroke-width="8"/>' +
    '<circle cx="' + (size/2) + '" cy="' + (size/2) + '" r="' + r + '" fill="none" stroke="' + color + '" stroke-width="8" stroke-dasharray="' + dash + ' ' + circ + '" stroke-dashoffset="' + (circ * 0.25) + '" stroke-linecap="round" transform="rotate(-90 ' + (size/2) + ' ' + (size/2) + ')"/>' +
    '<text x="50%" y="50%" dominant-baseline="middle" text-anchor="middle" fill="' + color + '" font-size="' + Math.round(size*0.22) + '" font-weight="700">' + pct + '%</text>' +
    '</svg>';
}

function renderVideoTracking() {
  var sec = pageEl('video-track'); if (!sec) return;
  sec.style.padding = '0';
  var admin = isAdmin(), dh = isDeptHead();

  if (admin || dh) {
    renderVtAdmin(sec);
  } else {
    renderVtEmployee(sec);
  }
}

function renderVtAdmin(sec) {
  var dh = isDeptHead();
  var stats = DB.miskillStats || [];
  var emps = dh ? (DB.employees || []).filter(function (e) { return SESSION && e.dept === SESSION.dept; }) : (DB.employees || []);
  var rows = stats.filter(function (r) {
    if (isDeptHead() && SESSION && SESSION.dept) {
      var e = emps.find(function (e) { return e.id === r.empId || _sameEmail(e.email, r.empEmail) || e.name === r.empName; });
      return !!e;
    }
    return true;
  }).sort(function (a, b) { return miskillScore(b) - miskillScore(a); });

  var weekLabel = rows.length && rows[0].weekStart ? rows[0].weekStart + ' — долоо хоног' : '';
  var adminUrl = '/admin.html?tab=lms';
  var html =
    // Sub-tab header
    '<div style="padding:22px 28px 0 28px">' +
    '<div style="display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;margin-bottom:14px">' +
    '<div><h1 style="font-size:22px;font-weight:700;color:#1E293B;margin:0">Видео сургалт (MiSkill)</h1>' +
    '<p style="font-size:13px;color:#64748B;margin:2px 0 0">Сургалт/шалгалт нэмж удирдана — ажилтнууд MiSkill цэсэндээ үзэж, шалгалтаа өгнө</p></div></div>' +
    '<div style="display:flex;gap:6px;border-bottom:2px solid #E2E8F0;margin-bottom:0">' +
    '<button id="vtSubLms" style="padding:9px 18px;border:none;background:none;font-family:inherit;font-size:13px;font-weight:700;color:#1D4ED8;cursor:pointer;border-bottom:2px solid #1D4ED8;margin-bottom:-2px"><i class="ti ti-book-2"></i> Сургалт (удирдлага)</button>' +
    '<button id="vtSubMiskill" style="padding:9px 18px;border:none;background:none;font-family:inherit;font-size:13px;font-weight:700;color:#64748B;cursor:pointer;border-bottom:2px solid transparent;margin-bottom:-2px"><i class="ti ti-chart-bar"></i> Гүйцэтгэлийн тайлан</button>' +
    '</div></div>' +
    // MiSkill/Гүйцэтгэл panel (default hidden — Сургалт default)
    '<div id="vtPanelMiskill" style="display:none">' +
    '<div style="padding:16px 28px 0">' +
    '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">' +
    '<button class="btn btn-secondary btn-sm" id="vtTpl"><i class="ti ti-download"></i> Загвар татах</button>' +
    '<button class="btn btn-primary" id="vtImport"><i class="ti ti-upload"></i> CSV байршуулах</button>' +
    '</div>' +
    (weekLabel ? '<div style="background:#EFF6FF;border-radius:8px;padding:6px 12px;display:inline-flex;align-items:center;gap:6px;font-size:12px;color:#1D4ED8;margin-bottom:8px"><i class="ti ti-calendar-week"></i> Тайлангийн долоо хоног: <strong>' + esc(rows[0].weekStart) + '</strong></div>' : '') +
    '</div>';

  if (!rows.length) {
    html += '<div style="padding:24px">' + emptyBox('MiSkill датагүй байна. CSV байршуулна уу.') + '</div>';
  } else {
    var totalEmps = rows.length;
    var fine = rows.filter(function (r) { return miskillScore(r) >= 70; }).length;
    var avgScore = Math.round(rows.reduce(function (s, r) { return s + miskillScore(r); }, 0) / totalEmps);
    var avgTP = Math.round(rows.reduce(function (s, r) { return s + msPct(r.trainDone, r.trainReq); }, 0) / totalEmps);
    var avgEP = Math.round(rows.reduce(function (s, r) { return s + msPct(r.examDone, r.examReq); }, 0) / totalEmps);

    html += '<div style="padding:0 28px;display:flex;gap:12px;flex-wrap:wrap;margin-bottom:14px">' +
      statCard('Нийт ажилтан', totalEmps, 'ti-users', '#3730A3') +
      statCard('Норм биелүүлсэн', fine, 'ti-circle-check', '#16A34A') +
      statCard('Дундаж оноо', avgScore, 'ti-chart-radar', '#D97706') +
      statCard('Сургалт биелэлт', avgTP + '%', 'ti-player-play', '#0891B2') +
      '</div>';

    html += '<div style="padding:0 28px 28px"><div class="card" style="padding:0;overflow:hidden">' +
      '<table class="data-table" style="width:100%">' +
      '<thead><tr><th style="width:36px">#</th><th>Ажилтан</th><th>Алба</th>' +
      '<th style="text-align:center">Сургалт</th><th style="text-align:center">Шалгалт</th>' +
      '<th style="text-align:center">Нийт оноо</th><th>Байдал</th><th style="text-align:center">7 хоног</th></tr></thead><tbody>' +
      rows.map(function (r, i) {
        var sc = miskillScore(r), tp = msPct(r.trainDone, r.trainReq), ep = msPct(r.examDone, r.examReq);
        var weekSum = (r.weekDays || []).reduce(function (s, d) { return s + (d.train || 0) + (d.exam || 0); }, 0);
        var empObj = (DB.employees || []).find(function (e) { return e.id === r.empId || e.name === r.empName; });
        var dept = empObj ? empObj.dept : (r.dept || '—');
        var pos = empObj ? (empObj.pos || '') : '';
        var medal = i === 0 ? '🥇' : i === 1 ? '🥈' : i === 2 ? '🥉' : '';
        return '<tr>' +
          '<td style="text-align:center;color:#94A3B8;font-size:12px">' + medal + (medal ? '' : (i + 1)) + '</td>' +
          '<td><div style="font-weight:600;font-size:13px">' + esc(r.empName || r.empId) + '</div>' +
          (pos ? '<div style="font-size:11px;color:#8A94A6">' + esc(pos) + '</div>' : '') + '</td>' +
          '<td style="font-size:13px;color:#64748B">' + esc(dept) + '</td>' +
          '<td style="text-align:center">' +
          '<div style="font-size:12px;color:#1E293B;font-weight:600">' + r.trainDone + '/' + r.trainReq + '</div>' +
          '<div style="height:4px;background:#E2E8F0;border-radius:4px;margin-top:3px;overflow:hidden"><div style="height:100%;width:' + tp + '%;background:' + msColor(tp) + ';border-radius:4px"></div></div></td>' +
          '<td style="text-align:center">' +
          '<div style="font-size:12px;color:#1E293B;font-weight:600">' + r.examDone + '/' + r.examReq + '</div>' +
          '<div style="height:4px;background:#E2E8F0;border-radius:4px;margin-top:3px;overflow:hidden"><div style="height:100%;width:' + ep + '%;background:' + msColor(ep) + ';border-radius:4px"></div></div></td>' +
          '<td style="text-align:center"><span class="score-pill ' + scoreClass(sc) + '">' + sc + '</span></td>' +
          '<td><span style="background:' + msBg(sc) + ';color:' + msColor(sc) + ';font-size:11px;font-weight:600;padding:3px 9px;border-radius:20px">' + msLabel(sc) + '</span></td>' +
          '<td style="text-align:center;font-size:13px;font-weight:600;color:' + (weekSum > 0 ? '#1D4ED8' : '#CBD5E1') + '">' + (weekSum > 0 ? weekSum : '—') + '</td>' +
          '</tr>';
      }).join('') + '</tbody></table></div></div>';
  }

  // Close Гүйцэтгэл panel + add LMS iframe panel (Сургалт — default харагдана)
  html += '</div>' +
    '<div id="vtPanelLms" style="height:calc(100vh - 200px)">' +
    '<iframe src="' + adminUrl + '" style="width:100%;height:100%;border:none;border-radius:0" allow="same-origin"></iframe>' +
    '</div>';

  sec.innerHTML = html;
  if (!sec._vtWired) {
    sec._vtWired = true;
    sec.addEventListener('click', function (ev) {
      if (ev.target.closest('#vtImport')) importMiskillCSV();
      if (ev.target.closest('#vtTpl')) downloadMiskillTemplate();
      // Sub-tab switching
      if (ev.target.closest('#vtSubMiskill')) {
        document.getElementById('vtPanelMiskill').style.display = '';
        document.getElementById('vtPanelLms').style.display = 'none';
        ev.target.closest('#vtSubMiskill').style.color = '#1D4ED8';
        ev.target.closest('#vtSubMiskill').style.borderBottomColor = '#1D4ED8';
        var lmsBtn = document.getElementById('vtSubLms');
        if (lmsBtn) { lmsBtn.style.color = '#64748B'; lmsBtn.style.borderBottomColor = 'transparent'; }
      }
      if (ev.target.closest('#vtSubLms')) {
        document.getElementById('vtPanelMiskill').style.display = 'none';
        document.getElementById('vtPanelLms').style.display = '';
        ev.target.closest('#vtSubLms').style.color = '#1D4ED8';
        ev.target.closest('#vtSubLms').style.borderBottomColor = '#1D4ED8';
        var msBtn = document.getElementById('vtSubMiskill');
        if (msBtn) { msBtn.style.color = '#64748B'; msBtn.style.borderBottomColor = 'transparent'; }
      }
    });
  }
}

function renderVtEmployee(sec) {
  // Ажилтны MiSkill цэс = админаас нэмсэн сургалтууд (Сургалтын самбар). Үзэж, шалгалтаа өгнө.
  sec.style.padding = '0';
  var eurl = '/employee.html?embed=1';
  // Гарчиг ХАРУУЛАХГҮЙ — дээд баарт аль хэдийн "Видео сургалт (MiSkill)" гэж бичигдсэн,
  // давхардуулбал утсан дээр орон зай дэмий эзэлнэ.
  sec.innerHTML =
    '<div style="height:calc(100vh - 64px);min-height:520px">' +
    '<iframe src="' + eurl + '" style="width:100%;height:100%;border:none;display:block" allow="fullscreen"></iframe>' +
    '</div>';
  return;
  /* eslint-disable */
  var row = miskillFindMyRow();
  var me = myEmp();
  var name = (me && me.name) || (SESSION && SESSION.email) || 'Ажилтан';
  var allStats = DB.miskillStats || [];
  var html = '<div style="background:linear-gradient(135deg,#1D4ED8 0%,#3730A3 100%);padding:22px 24px 36px;color:#fff;position:relative;overflow:hidden">' +
    '<div style="position:absolute;right:-20px;top:-20px;width:140px;height:140px;background:rgba(255,255,255,.06);border-radius:50%"></div>' +
    '<div style="position:absolute;right:30px;bottom:-30px;width:90px;height:90px;background:rgba(255,255,255,.06);border-radius:50%"></div>' +
    '<div style="position:relative"><div style="font-size:12px;opacity:.7;letter-spacing:.5px;text-transform:uppercase;margin-bottom:4px">Видео сургалт (MiSkill)</div>' +
    '<div style="font-size:22px;font-weight:700;margin-bottom:2px">' + esc(name) + '</div>' +
    '<div style="font-size:13px;opacity:.7">' + ((me && me.dept) || '') + (me && me.pos ? ' · ' + me.pos : '') + '</div></div></div>';

  if (!row) {
    html += '<div style="margin-top:-16px;padding:0 20px 24px"><div class="card" style="padding:28px;text-align:center">' +
      '<i class="ti ti-cloud-off" style="font-size:40px;color:#CBD5E1;display:block;margin-bottom:10px"></i>' +
      '<div style="font-weight:600;color:#475569;margin-bottom:4px">Мэдээлэл байхгүй</div>' +
      '<div style="font-size:13px;color:#94A3B8">Таны MiSkill сургалтын тайлан ХАБЭА ажилтанд байршуулаагүй байна.</div></div></div>';
    sec.innerHTML = html;
    return;
  }

  var tp = msPct(row.trainDone, row.trainReq);
  var ep = msPct(row.examDone, row.examReq);
  var sc = miskillScore(row);
  var allSorted = allStats.slice().sort(function (a, b) { return miskillScore(b) - miskillScore(a); });
  var rank = allSorted.findIndex(function (r) { return r.empId === row.empId || r.empName === row.empName; }) + 1;
  var total = allSorted.length;
  var medal = rank === 1 ? '🥇' : rank === 2 ? '🥈' : rank === 3 ? '🥉' : '';
  var rankColor = rank <= 3 ? '#D97706' : rank <= Math.ceil(total * 0.25) ? '#16A34A' : rank <= Math.ceil(total * 0.5) ? '#0891B2' : '#64748B';

  var MON_NAMES = ['Даваа', 'Мягмар', 'Лхагва', 'Пүрэв', 'Баасан'];
  var weekDays = row.weekDays || [{train:0,exam:0},{train:0,exam:0},{train:0,exam:0},{train:0,exam:0},{train:0,exam:0}];
  var maxDayVal = Math.max(1, weekDays.reduce(function (mx, d) { return Math.max(mx, (d.train||0) + (d.exam||0)); }, 0));

  function weekDateStr(start, offset) {
    if (!start) return '';
    try { var d = new Date(start); d.setDate(d.getDate() + offset); return (d.getMonth()+1) + '/' + d.getDate(); } catch(e) { return ''; }
  }

  html += '<div style="margin-top:-16px;padding:0 16px 24px">';

  // Нийт биелэлт хэсэг
  html += '<div class="card" style="padding:20px;margin-bottom:12px">' +
    '<div style="font-size:12px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.6px;margin-bottom:14px"><i class="ti ti-chart-pie-2"></i> Нийт биелэлт (бүх цаг хугацаа)</div>' +
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:16px">' +
    // Сургалт
    '<div style="text-align:center">' +
    msProgressRing(tp, msColor(tp), 90) +
    '<div style="font-weight:700;color:#1E293B;margin:6px 0 2px;font-size:15px">' + row.trainDone + ' / ' + row.trainReq + '</div>' +
    '<div style="font-size:11px;color:#64748B">Сургалт дууссан</div>' +
    '<div style="margin-top:6px;display:inline-block;padding:2px 10px;border-radius:12px;font-size:11px;font-weight:600;background:' + msBg(tp) + ';color:' + msColor(tp) + '">' + msLabel(tp) + '</div></div>' +
    // Шалгалт
    '<div style="text-align:center">' +
    msProgressRing(ep, msColor(ep), 90) +
    '<div style="font-weight:700;color:#1E293B;margin:6px 0 2px;font-size:15px">' + row.examDone + ' / ' + row.examReq + '</div>' +
    '<div style="font-size:11px;color:#64748B">Шалгалт дууссан</div>' +
    '<div style="margin-top:6px;display:inline-block;padding:2px 10px;border-radius:12px;font-size:11px;font-weight:600;background:' + msBg(ep) + ';color:' + msColor(ep) + '">' + msLabel(ep) + '</div></div>' +
    '</div>' +
    // Нийт оноо
    '<div style="margin-top:14px;padding:10px 14px;background:#F8FAFC;border-radius:10px;display:flex;align-items:center;gap:10px">' +
    '<div style="font-size:11px;color:#64748B;flex:1">Нийт MiSkill оноо (сургалт 70% + шалгалт 30%)</div>' +
    '<span class="score-pill ' + scoreClass(sc) + '" style="font-size:16px;padding:4px 14px">' + sc + '</span></div>' +
    '</div>';

  // Өнгөрсөн долоо хоногийн breakdown
  html += '<div class="card" style="padding:20px;margin-bottom:12px">' +
    '<div style="font-size:12px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.6px;margin-bottom:14px">' +
    '<i class="ti ti-calendar-week"></i> Өнгөрсөн долоо хоног' + (row.weekStart ? ' <span style="font-weight:400;color:#94A3B8;font-size:11px">(' + row.weekStart + ')</span>' : '') + '</div>' +
    '<div style="display:grid;grid-template-columns:repeat(5,1fr);gap:8px">' +
    weekDays.slice(0, 5).map(function (d, i) {
      var dayTotal = (d.train || 0) + (d.exam || 0);
      var barH = dayTotal > 0 ? Math.max(16, Math.round(dayTotal / maxDayVal * 60)) : 0;
      var dateStr = weekDateStr(row.weekStart, i);
      var hasTrain = (d.train || 0) > 0, hasExam = (d.exam || 0) > 0;
      return '<div style="text-align:center">' +
        '<div style="font-size:10px;font-weight:700;color:#475569">' + MON_NAMES[i] + '</div>' +
        '<div style="font-size:10px;color:#94A3B8;margin-bottom:6px">' + dateStr + '</div>' +
        '<div style="min-height:70px;display:flex;flex-direction:column;justify-content:flex-end;align-items:center;gap:2px">' +
        (hasTrain ? '<div style="width:28px;background:#3B82F6;border-radius:4px 4px 0 0;height:' + Math.max(8, Math.round((d.train||0)/maxDayVal*60)) + 'px;position:relative" title="Сургалт: ' + (d.train||0) + '">' +
          '<div style="position:absolute;top:-16px;width:100%;text-align:center;font-size:10px;font-weight:700;color:#1D4ED8">' + d.train + '</div></div>' : '<div style="width:28px;height:8px;background:#F1F5F9;border-radius:4px"></div>') +
        (hasExam ? '<div style="width:28px;background:#10B981;border-radius:0 0 4px 4px;height:' + Math.max(8, Math.round((d.exam||0)/maxDayVal*60)) + 'px;position:relative" title="Шалгалт: ' + (d.exam||0) + '">' +
          '</div>' : '<div style="width:28px;height:8px;background:#F1F5F9;border-radius:4px"></div>') +
        '</div>' +
        '<div style="margin-top:6px;font-size:11px;color:' + (dayTotal > 0 ? '#1E293B' : '#CBD5E1') + ';font-weight:' + (dayTotal > 0 ? '600' : '400') + '">' + (dayTotal > 0 ? dayTotal : '—') + '</div>' +
        '</div>';
    }).join('') + '</div>' +
    '<div style="margin-top:12px;display:flex;gap:14px;font-size:11px;color:#64748B">' +
    '<span><span style="display:inline-block;width:10px;height:10px;background:#3B82F6;border-radius:2px;margin-right:4px"></span>Сургалт</span>' +
    '<span><span style="display:inline-block;width:10px;height:10px;background:#10B981;border-radius:2px;margin-right:4px"></span>Шалгалт</span>' +
    '<span style="margin-left:auto;color:#94A3B8">7 хоногийн нийт: <strong style="color:#1E293B">' + weekDays.reduce(function (s, d) { return s + (d.train||0) + (d.exam||0); }, 0) + '</strong></span>' +
    '</div></div>';

  // Байр эзлэлт
  html += '<div class="card" style="padding:20px;background:linear-gradient(135deg,' + (rank <= 3 ? '#FEF3C7,#FDE68A' : rank <= Math.ceil(total*0.25) ? '#D1FAE5,#A7F3D0' : '#EFF6FF,#DBEAFE') + ')">' +
    '<div style="font-size:12px;font-weight:700;color:#64748B;text-transform:uppercase;letter-spacing:.6px;margin-bottom:12px"><i class="ti ti-trophy"></i> Байр эзлэлт (MiSkill оноогоор)</div>' +
    '<div style="display:flex;align-items:center;gap:16px">' +
    '<div style="font-size:52px;line-height:1">' + (medal || '🎯') + '</div>' +
    '<div style="flex:1">' +
    '<div style="font-size:32px;font-weight:800;color:' + rankColor + ';line-height:1">' + rank + '<span style="font-size:16px;font-weight:500;color:#94A3B8">-р байр</span></div>' +
    '<div style="font-size:13px;color:#475569;margin-top:3px">Нийт <strong>' + total + '</strong> ажилтнаас</div>' +
    '<div style="margin-top:8px;height:6px;background:rgba(0,0,0,.08);border-radius:6px;overflow:hidden">' +
    '<div style="height:100%;width:' + Math.round((1 - (rank-1)/Math.max(1,total-1)) * 100) + '%;background:' + rankColor + ';border-radius:6px"></div></div>' +
    '<div style="font-size:11px;color:#64748B;margin-top:3px">Дээд ' + Math.round(rank/total*100) + '% дотор</div>' +
    '</div>' +
    '<div style="text-align:center;padding:12px 16px;background:rgba(255,255,255,.7);border-radius:12px">' +
    '<div style="font-size:11px;color:#64748B;margin-bottom:2px">Миний оноо</div>' +
    '<div style="font-size:28px;font-weight:800;color:' + rankColor + '">' + sc + '</div>' +
    '<div style="font-size:11px;color:#94A3B8">/ 100</div></div>' +
    '</div></div>';

  html += '</div>';
  sec.innerHTML = html;
}

function downloadMiskillTemplate() {
  var header = 'empid,empname,train_req,train_done,exam_req,exam_done,week_start,mon_train,mon_exam,tue_train,tue_exam,wed_train,wed_exam,thu_train,thu_exam,fri_train,fri_exam';
  var rows = [
    'EMP-001,Болд Баатар,20,15,10,8,2026-06-09,3,1,2,0,3,2,2,1,1,0',
    'EMP-002,Сарнай Ганбаатар,20,18,10,9,2026-06-09,4,2,3,1,4,2,3,1,2,1',
    'EMP-003,Энхбат Лхагва,20,10,10,5,2026-06-09,2,0,1,0,2,1,1,0,0,0'
  ];
  download('miskill-zagvar.csv', '﻿' + header + '\n' + rows.join('\n'), 'text/csv;charset=utf-8');
}

function importMiskillCSV() {
  var node = elc('div', 'modal-info');
  node.innerHTML = '<div style="font-size:13.5px;line-height:1.6;color:#475569;margin-bottom:14px">' +
    '<p style="margin:0 0 8px">MiSkill платформоос татсан <strong>CSV файл</strong> байршуулна. Баганууд:</p>' +
    '<div style="background:#F8FAFC;border-radius:8px;padding:10px 12px;font-family:monospace;font-size:12px;color:#1D4ED8;border:1px solid #E2E8F0">' +
    'empid, empname, train_req, train_done, exam_req, exam_done, week_start,<br>' +
    'mon_train, mon_exam, tue_train, tue_exam, wed_train, wed_exam,<br>' +
    'thu_train, thu_exam, fri_train, fri_exam</div></div>' +
    '<label class="rf-photo" id="msLbl" style="margin-bottom:10px"><input type="file" accept=".csv,text/csv" id="msCsv" hidden><i class="ti ti-file-spreadsheet"></i><span>CSV файл сонгох</span></label>' +
    '<button class="btn btn-secondary btn-sm" id="msTpl"><i class="ti ti-download"></i> Загвар татах</button>';

  node.addEventListener('click', function (ev) {
    if (ev.target.closest('#msTpl')) { downloadMiskillTemplate(); return; }
  });

  node.querySelector('#msCsv').addEventListener('change', function () {
    var f = this.files && this.files[0]; if (!f) return;
    var rd = new FileReader();
    rd.onload = function (ev) {
      try {
        var parsed = parseCSV(ev.target.result);
        if (!parsed.length) { toast('Файл хоосон байна', 'warn'); return; }
        var imported = 0, skipped = 0;
        DB.miskillStats = DB.miskillStats || [];
        parsed.forEach(function (row) {
          var empid = (row['empid'] || row['EmployeeID'] || row[Object.keys(row)[0]] || '').trim();
          var empname = (row['empname'] || row['EmployeeName'] || row[Object.keys(row)[1]] || '').trim();
          if (!empid && !empname) { skipped++; return; }
          var r = {
            empId: empid, empName: empname,
            trainReq: num(row['train_req'] || row['TrainRequired'] || 0),
            trainDone: num(row['train_done'] || row['TrainDone'] || 0),
            examReq: num(row['exam_req'] || row['ExamRequired'] || 0),
            examDone: num(row['exam_done'] || row['ExamDone'] || 0),
            weekStart: (row['week_start'] || row['WeekStart'] || '').trim(),
            weekDays: [
              { train: num(row['mon_train']||0), exam: num(row['mon_exam']||0) },
              { train: num(row['tue_train']||0), exam: num(row['tue_exam']||0) },
              { train: num(row['wed_train']||0), exam: num(row['wed_exam']||0) },
              { train: num(row['thu_train']||0), exam: num(row['thu_exam']||0) },
              { train: num(row['fri_train']||0), exam: num(row['fri_exam']||0) }
            ],
            updatedAt: todayISO()
          };
          var idx = DB.miskillStats.findIndex(function (x) { return x.empId === empid || x.empName === empname; });
          if (idx >= 0) { DB.miskillStats[idx] = r; } else { DB.miskillStats.push(r); }
          imported++;
        });
        saveDB();
        closeModal();
        renderVideoTracking();
        infoModal('MiSkill импортын дүн', '<div style="font-size:14px;line-height:1.8">' +
          '<div>✅ Шинэчлэгдсэн/нэмэгдсэн: <strong>' + imported + '</strong> ажилтан</div>' +
          (skipped ? '<div>⚠️ Алгассан мөр: <strong>' + skipped + '</strong></div>' : '') +
          '<div style="margin-top:8px;font-size:13px;color:#64748B">Ажилтнуудад шинэ тайлан нь автоматаар харагдана.</div></div>');
      } catch (e) { toast('Файл уншихад алдаа: ' + e.message, 'error'); }
    };
    rd.readAsText(f, 'UTF-8');
  });
  buildModal('MiSkill CSV байршуулах', node, { width: '480px' });
}

/* ============ Даалгавар ============ */
/* ══════════════════════════════════════════════════════════════════════
   ДААЛГАВРЫН БИЕ — эрсдэлээс үүссэн бол ТОДОРХОЙ товьёог харуулна:
   «Та ямар аюулыг, юу хийж, хэзээ хүртэл бууруулах вэ».
   ⚠ Эрсдэл ачаалагдаагүй бол анхны тайлбарыг ХЭВЭЭР харуулна (юу ч алдагдахгүй).
   ══════════════════════════════════════════════════════════════════════ */
function taskRiskOf(x) {
  if (!x || !x.riskId) return null;
  return (DB.risks || []).filter(function (r) { return String(r.id) === String(x.riskId); })[0] || null;
}
function taskBodyHTML(x) {
  var r = taskRiskOf(x);
  if (!r) {
    return x.desc ? '<div style="font-size:13px;color:#64748B;margin-top:3px;white-space:pre-wrap">' + esc(x.desc) + '</div>' : '';
  }
  var L = riskLevel(r), sc = riskScore(r);
  var after = riskScoreAfter(r);
  var line = function (ic, t, v) {
    if (!v) return '';
    return '<div style="display:flex;gap:8px;margin-top:5px">' +
      '<span style="flex:0 0 16px;font-size:12px;line-height:1.5">' + ic + '</span>' +
      '<span style="flex:1;min-width:0;font-size:12.5px;color:#475569;line-height:1.55">' +
      '<b style="color:#334155">' + t + ':</b> ' + esc(String(v)) + '</span></div>';
  };
  return '<div style="margin-top:9px;border:1.5px solid ' + L.bd + ';border-radius:11px;overflow:hidden">' +
    /* Аль аюулыг бууруулах вэ */
    '<div style="background:' + L.bg + ';padding:10px 12px;display:flex;align-items:center;gap:10px">' +
    '<span style="flex:0 0 auto;background:' + L.color + ';color:#fff;border-radius:7px;padding:3px 8px;font-size:11px;font-weight:800">' +
    L.code + ' · ' + sc + '</span>' +
    '<span style="flex:1;min-width:0;font-size:13px;font-weight:700;color:#1E293B;line-height:1.4">' +
    esc(r.hazard || '') + '</span></div>' +
    '<div style="padding:9px 12px 11px;background:#fff">' +
    '<div style="font-size:11px;font-weight:800;color:#94A3B8;letter-spacing:.3px">ТА ЭНЭ АЮУЛЫГ БУУРУУЛНА</div>' +
    line('⚙️', 'Ажиллагаа', r.process) +
    line('📍', 'Байршил', r.location) +
    line('❓', 'Шалтгаан', r.cause) +
    line('🛡️', 'Авах арга хэмжээ', r.actions) +
    line('👤', 'Хяналт тавих', r.responsible) +
    line('📅', 'Хугацаа', x.dueDate || r.due) +
    (after > 0 && sc > after
      ? '<div style="margin-top:8px;background:#F0FDF4;border:1px solid #BBF7D0;border-radius:8px;padding:7px 10px;font-size:12px;color:#15803D">' +
        '🎯 Зорилт: эрсдлийг <b>' + sc + '</b> → <b>' + after + '</b> болгож бууруулах' +
        ' (<b>' + Math.round((1 - after / sc) * 100) + '%</b>)</div>'
      : '') +
    '<button class="btn btn-sm" data-risk-open="' + esc(r.id) + '" style="margin-top:9px;background:#F1F5F9;color:#475569;border-color:#E2E8F0">' +
    '<i class="ti ti-info-circle"></i> Эрсдэлийн дэлгэрэнгүй</button>' +
    '</div></div>';
}

/* ══════════════════════════════════════════════════════════════════════
   «АРГА ХЭМЖЭЭНИЙ БИЕЛЭЛТ» ЦЭС
   Эрсдэл болгоныг ухаж ороход хэцүү тул надад оногдсон БҮХ арга хэмжээг
   нэг дор жагсаана: хугацаа хэтэрсэн нь эхэнд, дараа нь хугацаатай.
   ══════════════════════════════════════════════════════════════════════ */
/* ⭐ ДҮРЭМ, АРГА ХЭМЖЭЭГ ЗӨВХӨН АЖЛЫН БАЙРНЫ эрсдлээс гаргана.
   ⚠ Ажилтны ажлын байрны үнэлгээ хийгдээгүй бол `riskSeenBy` нь АЛБАНЫ
   бүх эрсдлийг буцаадаг (танилцуулах зорилгоор). Тэрнээс дүрэм гаргавал
   Бэлтгэгчид ХИМИЙН БОДИСЫН дүрэм оногдох гэх мэт БУРУУ зүйл болно. */
function riskMineStrict(emp) {
  var s = { rows: [], scope: 'none' };
  try { s = riskSeenBy(emp); } catch (e) {}
  return (s.scope === 'pos' || s.scope === 'section') ? (s.rows || []) : [];
}
/* Ажлын байрны үнэлгээ хийгдсэн үү */
function riskHasOwn(emp) {
  try { var s = riskSeenBy(emp); return s.scope === 'pos' || s.scope === 'section'; }
  catch (e) { return false; }
}

function meaMineList(emp) {
  if (!emp) return [];
  var seen = riskMineStrict(emp);
  var store = MEA_VIEW.store;
  var out = [], seenKey = {};
  /* ⭐ ЗӨВХӨН надад оногдсон ХЭРЭГЖҮҮЛЭХ ажлууд (зан үйлийн дүрэм энд орохгүй) */
  seen.forEach(function (r) {
    var dept = riskCanonDept(r.dept) || r.dept || '';
    var due = riskMeasureDue(r), left = meaDaysLeft(due);
    riskMeasures(r).forEach(function (m) {
      if (m.role === 'self') return;
      var owners = meaOwnersOf(r, m.role, m.text);
      if (!owners.some(function (o) { return o.uid === emp.uid; })) return;
      var key = meaKeyOf(dept, m.text);
      if (seenKey[key]) return;
      seenKey[key] = 1;
      var rec = store ? meaDone(store, key) : null;
      out.push({ risk: r, mi: m.i, key: key, text: m.text, due: due, left: left, rec: rec,
        lvl: riskLevel(r), score: riskScore(r) });
    });
  });
  out.sort(function (a, b) {
    if (!!a.rec !== !!b.rec) return a.rec ? 1 : -1;          // хийгээгүй нь эхэнд
    if (a.left !== b.left) return (a.left || 0) - (b.left || 0); // яаралтай нь эхэнд
    return b.score - a.score;
  });
  return out;
}
function meaMineStats(emp) {
  var l = meaMineList(emp);
  return {
    total: l.length,
    done: l.filter(function (x) { return x.rec; }).length,
    late: l.filter(function (x) { return !x.rec && x.left != null && x.left < 0; }).length,
    soon: l.filter(function (x) { return !x.rec && x.left != null && x.left >= 0 && x.left <= 3; }).length
  };
}

/* Ажилтны МӨРДӨХ ДҮРЭМ (зан үйлийн арга хэмжээ) — баримт шаардахгүй */
function meaMyRules(emp) {
  if (!emp) return [];
  var out = [], seen = {};
  riskMineStrict(emp).forEach(function (r) {
    riskMeasures(r).forEach(function (m) {
      if (m.role !== 'self') return;
      var k = meaKeyOf(riskCanonDept(r.dept) || r.dept, m.text);
      if (seen[k]) return;
      seen[k] = 1;
      out.push({ risk: r, text: m.text, lvl: riskLevel(r), score: riskScore(r) });
    });
  });
  return out.sort(function (a, b) { return b.score - a.score; });
}

/* ══ АДМИН/ХАРИУЦАГЧИЙН «Арга хэмжээ» хуудас ══════════════════════════ */
function renderMeasureAdminPage(sec, embed) {
  if (!sec) return;
  var scoped = isDeptHead() && SESSION && SESSION.dept ? SESSION.dept : '';
  sec.innerHTML =
    (embed ? '' :
      '<div class="page-header"><div><h1>Арга хэмжээний биелэлт</h1>' +
      '<p class="page-subtitle">Эрсдэл бүрээс гарсан <b>хэрэгжүүлэх</b> арга хэмжээний гүйцэтгэл. ' +
      'Зан үйлийн дүрэм нь гарын үсгээр баталгаажих тул энд орохгүй.' +
      (scoped ? ' · ' + esc(scoped) : '') + '</p></div></div>') +
    meaAdminHTML() +
    '<div class="card" style="padding:16px 18px;margin-top:14px">' +
    '<div style="font-size:13px;font-weight:800;color:#334155;margin-bottom:4px">Хэрхэн ажилладаг</div>' +
    '<div style="font-size:12.5px;color:#64748B;line-height:1.7">' +
    '① Эрсдлийн «Авах арга хэмжээ» нүдийг үйл ажиллагаа бүрээр задалдаг<br>' +
    '② Агуулгаас нь хамааруулж хариуцагчийг тодорхойлдог (ХАБЭА · ИТА · ХН · албаны дарга)<br>' +
    '③ Хариуцагч зураг/файл хавсаргаж баримтжуулмагц <b>биелсэнд тооцно</b><br>' +
    '④ «Хэн хяналт тавих» баганынхан <b>хянагч</b> — хангалтгүй бол буцаана<br>' +
    '⑤ Буруу оногдсоныг эрсдлийн дэлгэрэнгүйгээс <b>👤 товчоор</b> зөв хүнд шилжүүлнэ</div></div>';

  if (!sec._meaAdmWired) {
    sec._meaAdmWired = true;
    sec.addEventListener('click', function (ev) {
      var mw = ev.target.closest('[data-mea-who]');
      if (mw) { meaWhoModal(mw.getAttribute('data-mea-who')); return; }
      var mx = ev.target.closest('[data-mea-xl]');
      if (mx) { meaExport(mx.getAttribute('data-mea-xl')); return; }
      var ms = ev.target.closest('[data-mea-scan]');
      if (ms) {
        var mo = ms.innerHTML; ms.disabled = true;
        meaAdminScan(function (i, n) { ms.innerHTML = '<i class="ti ti-loader-2"></i> ' + i + '/' + n; })
          .then(function () { meaRedraw(); })
          .catch(function (e) {
            ms.disabled = false; ms.innerHTML = mo;
            toast('Шалгаж чадсангүй: ' + ((e && e.message) || e), 'error');
          });
      }
    });
  }
}

/* ⭐ Арга хэмжээний хуудсыг ЭРСДЭЛИЙН ҮНЭЛГЭЭ цэсний таб дотор зурна.
   Дата ачаалагдмагц аль хуудсыг дахин зурахыг энэ заана (renderHazards). */
var MEA_RERENDER = null;
function meaRedraw() {
  if (typeof MEA_RERENDER === 'function') { MEA_RERENDER(); return; }
  try { renderHazards(); } catch (e) {}
}

/* Ажилтны «Арга хэмжээний биелэлт» — embed=true бол гарчиггүйгээр таб дотор */
function renderMeasurePage(sec, embed) {
  if (!sec) return;
  var me = null; try { me = myEmp(); } catch (e) {}
  if (!me) {
    sec.innerHTML = '<div class="empty-state" style="padding:40px"><i class="ti ti-user-question"></i>' +
      '<div>Таны бүртгэл олдсонгүй.</div></div>';
    return;
  }
  var dept = riskCanonDept(me.dept) || me.dept || '';
  /* Бичлэгүүд ирээгүй бол татаад дахин зурна */
  if ((!MEA_VIEW.store || MEA_VIEW.dept !== dept) && renderMeasurePage._for !== dept) {
    renderMeasurePage._for = dept;             /* нэг албанд НЭГ УДАА */
    meaLoad(dept).then(function (st) {
      MEA_VIEW.store = st || { rows: [] }; MEA_VIEW.dept = dept;
      meaRedraw();
    }).catch(function (e) {
      MEA_VIEW.store = MEA_VIEW.store || { rows: [] }; MEA_VIEW.dept = dept;
      console.error('[measures]', e);
    });
  }
  var list = meaMineList(me), st = meaMineStats(me);
  var pct = st.total ? Math.round(st.done * 100 / st.total) : 0;

  var card = function (n, label, color) {
    return '<div style="flex:1;min-width:110px;background:' + color + '0D;border:1.5px solid ' + color +
      '2E;border-radius:14px;padding:12px 14px">' +
      '<div style="font-size:26px;font-weight:900;color:' + color + ';line-height:1;font-family:\'Bricolage Grotesque\',sans-serif">' + n + '</div>' +
      '<div style="font-size:11.5px;font-weight:700;color:' + color + ';margin-top:3px">' + label + '</div></div>';
  };

  var rows = list.map(function (x) {
    var late = !x.rec && x.left != null && x.left < 0;
    var tone = x.rec ? '#059669' : (late ? '#DC2626' : (x.left <= 3 ? '#D97706' : '#64748B'));
    return '<div style="display:flex;gap:12px;align-items:flex-start;padding:13px;border:1px solid ' +
      (late ? '#FECACA' : '#F1F5F9') + ';border-radius:13px;margin-bottom:9px;background:' +
      (x.rec ? '#F8FAFC' : (late ? '#FEF2F2' : '#fff')) + '">' +
      '<span style="flex:0 0 24px;height:24px;border-radius:50%;display:inline-flex;align-items:center;justify-content:center;' +
      'font-size:12px;font-weight:900;color:#fff;background:' + (x.rec ? '#059669' : (late ? '#DC2626' : '#CBD5E1')) + '">' +
      (x.rec ? '✓' : '!') + '</span>' +
      '<span style="flex:1;min-width:0">' +
      '<span style="display:block;font-size:13.5px;font-weight:600;color:#1E293B;line-height:1.5">' + esc(x.text) + '</span>' +
      '<span style="display:block;font-size:11.5px;color:#94A3B8;margin-top:3px">' +
      '<b style="color:' + x.lvl.color + '">' + x.lvl.code + '</b> · ' + esc(String(x.risk.hazard || '').slice(0, 70)) + '</span>' +
      '<span style="display:block;font-size:11.5px;color:' + tone + ';margin-top:4px;font-weight:600">' +
      (x.rec ? '✓ ' + ackDateMn(x.rec.at) + '-нд баримтжуулсан'
             : (late ? '⚠ ' + Math.abs(x.left) + ' хоногоор хэтэрсэн (' + x.due + ')'
                     : '⏳ ' + x.due + ' хүртэл · ' + x.left + ' хоног')) + '</span></span>' +
      (x.rec ? '' : '<button class="btn btn-sm btn-primary" data-mea-open="' + esc(x.risk.id) + '|' + x.mi + '" style="flex-shrink:0">' +
        '<i class="ti ti-camera-plus"></i> Бүртгэх</button>') +
      '</div>';
  }).join('') || '<div class="empty-state" style="padding:26px"><i class="ti ti-checkbox"></i>' +
    '<div>Танд хэрэгжүүлэх арга хэмжээ оногдоогүй байна</div>' +
    '<div style="font-size:12.5px;color:#94A3B8;margin-top:6px;line-height:1.6">' +
    'Хашлага тавих, сургалт зохион байгуулах зэрэг ажлыг албаны хариуцагч, ХАБЭА, ' +
    'инженер техникийн алба хариуцна. Танаас доорх <b>мөрдөх дүрмийг</b> хүлээж байна.</div></div>';

  /* ⚠ Ажлын байрны үнэлгээ хийгдээгүй бол АЛБАНЫ эрсдлээс дүрэм
     гаргахгүй (өмнө нь Бэлтгэгчид химийн бодисын дүрэм оногддог байв).
     Шалтгааныг нь ажилтанд ТОДОРХОЙ хэлнэ. */
  var ownOk = true;
  try { ownOk = riskHasOwn(me); } catch (er) {}
  var noOwnHTML = ownOk ? '' :
    '<div class="card" style="padding:16px 18px;margin-bottom:13px;border:1.5px solid #FDE68A;background:#FFFBEB">' +
    '<div style="font-size:14px;font-weight:800;color:#92400E;margin-bottom:5px">' +
    '⚠ Таны ажлын байрны эрсдэлийн үнэлгээ хийгдээгүй байна</div>' +
    '<div style="font-size:12.5px;color:#8A6D3B;line-height:1.75">' +
    '<b>' + esc(me.pos || me.role || '—') + '</b> ажлын байрны үнэлгээ хийгдтэл танд ' +
    '<b>мөрдөх дүрэм оногдохгүй</b>.<br>' +
    'Өмнө нь албаны бусад ажлын байрны дүрэм (жишээ нь химийн бодистой ажиллах) ' +
    'танд буруугаар харагдаж байсныг зассан.<br>' +
    'Эрсдэлийн үнэлгээ цэсэнд албаны эрсдлүүдийг <b>танилцуулах зорилгоор</b> харуулсаар байна.</div></div>';

  /* ── 📌 МӨРДӨХ ДҮРЭМ — баримт шаардахгүй, гарын үсгээр баталгаажна ── */
  var rules = meaMyRules(me);
  var rulesHTML = rules.length
    ? '<div class="card" style="padding:16px 18px;margin-bottom:13px">' +
      '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:4px">' +
      '<div style="font-size:14px;font-weight:800;color:#334155">📌 Миний мөрдөх дүрэм</div>' +
      '<div style="background:#EEF2FF;color:#3730A3;border-radius:20px;padding:2px 10px;font-size:12px;font-weight:800">' +
      rules.length + '</div></div>' +
      '<div style="font-size:12.5px;color:#8A94A6;margin-bottom:11px;line-height:1.6">' +
      'Эдгээрийг ажлын явцад <b>өөрөө байнга мөрдөнө</b>. Зураг хавсаргах шаардлагагүй — ' +
      'эрсдэлтэй танилцаж <b>гарын үсэг зурснаараа</b> хүлээн зөвшөөрсөнд тооцогдоно.</div>' +
      '<div class="emp-todo-grid">' +
      rules.slice(0, 40).map(function (x) {
        return '<div style="display:flex;gap:10px;align-items:flex-start;padding:11px 12px;border:1px solid #F1F5F9;' +
          'border-radius:12px;background:#F8FAFC">' +
          '<span style="flex-shrink:0;font-size:10.5px;font-weight:800;color:' + x.lvl.color +
          ';background:' + x.lvl.bg + ';border-radius:6px;padding:2px 6px">' + x.lvl.code + '</span>' +
          '<span style="flex:1;min-width:0;font-size:12.5px;color:#1E293B;line-height:1.5">' + esc(x.text) + '</span>' +
          '</div>';
      }).join('') + '</div>' +
      (rules.length > 40 ? '<div style="font-size:12px;color:#94A3B8;margin-top:8px">+' + (rules.length - 40) +
        ' дүрэм — эрсдэлийн үнэлгээ цэсээс бүрэн үзнэ үү</div>' : '') +
      '</div>'
    : '';

  sec.innerHTML =
    (embed ? '' :
      '<div class="page-header"><div><h1>Арга хэмжээний биелэлт</h1>' +
      '<p class="page-subtitle">Эрсдэл бүрээс гарсан арга хэмжээг нэг бүрчлэн гүйцэтгэж, ' +
      '<b>баримтаар</b> баталгаажуулна</p></div></div>') +
    pushCardHTML() +
    noOwnHTML +
    (st.late
      ? '<div style="background:#FEF2F2;border:1.5px solid #FECACA;border-radius:14px;padding:14px 16px;margin-bottom:13px;' +
        'color:#B91C1C;font-size:13px;line-height:1.6"><b>⚠ Хугацаа хэтэрсэн ' + st.late + ' арга хэмжээ байна.</b><br>' +
        'Эдгээрийг гүйцэтгэж баримтаа хавсаргах хүртэл өдөр бүр энд сануулна.</div>'
      : '') +
    '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:13px">' +
    card(st.total, 'нийт арга хэмжээ', '#4F46E5') +
    card(st.done, 'баримтжуулсан', '#059669') +
    card(st.total - st.done, 'хүлээгдэж буй', '#D97706') +
    card(st.late, 'хугацаа хэтэрсэн', '#DC2626') +
    '</div>' +
    '<div class="card" style="padding:16px 18px;margin-bottom:13px">' +
    '<div style="display:flex;align-items:center;gap:11px;margin-bottom:11px">' +
    '<div style="font-size:13px;font-weight:800;color:#334155">Явц</div>' +
    '<div style="flex:1;height:9px;background:#F1F5F9;border-radius:99px;overflow:hidden">' +
    '<div style="height:100%;width:' + pct + '%;background:linear-gradient(90deg,#6366F1,#059669)"></div></div>' +
    '<div style="font-size:13px;font-weight:900;color:' + (pct === 100 ? '#059669' : '#64748B') + '">' + pct + '%</div></div>' +
    rows + '</div>' +
    rulesHTML;

  /* ⚠ taskBadge нь «Даалгавар» цэсний тоолуур — арга хэмжээгээр дарж
     бичихгүй. Арга хэмжээний хугацаа хэтэрснийг эрсдэлийн цэсний тугаар
     (riskTabsHTML) ба нүүр хуудсаар сануулна. */

  if (!sec._meaPageWired) {
    sec._meaPageWired = true;
    sec.addEventListener('click', function (ev) {
      var b = ev.target.closest('[data-mea-open]');
      if (!b) return;
      var p = String(b.getAttribute('data-mea-open')).split('|');
      var r = (DB.risks || []).filter(function (x) { return String(x.id) === p[0]; })[0];
      if (r) riskMeasureDoModal(r, parseInt(p[1], 10));
    });
  }
  try { pushWireOnce(); pushSyncState(); } catch (er) {}
}

/* ══════════════════════════════════════════════════════════════════════
   🔔 PUSH САНУУЛГА — вэб сайт ХААЛТТАЙ байхад ч сануулна
   ----------------------------------------------------------------------
   Ажилтан «Сануулга авах» дараад л зөвшөөрөл өгнө (браузер шаарддаг).
   Дараа нь:
     • хөтөч тухайн төхөөрөмжийн бүртгэлийг (subscription) буцаана
     • түүнийг R2 дээрх push/subs.json-д ӨӨРИЙН uid-аар хадгална
     • мөн хугацаа хэтэрсэн/хүлээгдэж буй арга хэмжээний ТООГ хамт бичнэ
     • өдөрт нэг удаа Vercel-ийн cron (/api/push-daily) тэр тоог хараад
       зөвхөн ХИЙХ ЮМ БАЙГАА хүнд сануулга илгээнэ
   ⚠ Файлд НЭР, И-МЭЙЛ хадгалахгүй — зөвхөн uid, тоо, төхөөрөмжийн хаяг.
   ⚠ iPhone дээр эхлээд «Утсанд суулгах» хийсэн байх ёстой (Apple-ийн шаардлага).
   ══════════════════════════════════════════════════════════════════════ */
var PUSH_PUB = 'BCNLcjRpD6ljHwlqpTTNKoyO10b4Rr_ITWO1lY7Vr7G7r7e-jhg2lGYJkCIp-0nK1xMdALYMyQpEYXJl4OhGGeQ';
var PUSH_SUBS_FILE = 'push/subs.json';
var PUSH_LS = 'kpi_push_v1';

function pushSupported() {
  try {
    return ('serviceWorker' in navigator) && ('PushManager' in window) && ('Notification' in window);
  } catch (e) { return false; }
}
function pushStandalone() {
  try {
    return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) ||
      navigator.standalone === true;
  } catch (e) { return false; }
}
/* iPhone/iPad дээр Safari нь СУУЛГААГҮЙ вэб сайтад push огт зөвшөөрдөггүй */
function pushNeedsInstall() {
  var ua = navigator.userAgent || '';
  return /iPad|iPhone|iPod/.test(ua) && !pushStandalone();
}
function pushPerm() { try { return Notification.permission; } catch (e) { return 'default'; } }
function pushLocal() { try { return JSON.parse(localStorage.getItem(PUSH_LS) || '{}') || {}; } catch (e) { return {}; } }
function pushLocalSet(o) { try { localStorage.setItem(PUSH_LS, JSON.stringify(o || {})); } catch (e) {} }

function pushB64ToU8(s) {
  var pad = new Array(((4 - s.length % 4) % 4) + 1).join('=');
  var raw = atob((s + pad).replace(/-/g, '+').replace(/_/g, '/'));
  var u = new Uint8Array(raw.length);
  for (var i = 0; i < raw.length; i++) u[i] = raw.charCodeAt(i);
  return u;
}

/* Одоогийн сануулах шаардлага — арга хэмжээ + танилцалт */
function pushStats() {
  var me = null; try { me = myEmp(); } catch (e) {}
  if (!me || !me.uid) return null;
  var st = { total: 0, done: 0, late: 0 };
  try { st = meaMineStats(me); } catch (e) {}
  var out = { uid: me.uid, late: st.late || 0, pending: Math.max(0, (st.total || 0) - (st.done || 0) - (st.late || 0)) };
  /* Батлах хүлээгдэж буй хүсэлт — хугацаа хэтэрсэн нь «late» дээр нэмэгдэнэ */
  try {
    if (REQ_OK) {
      var wq = reqWaitingFor(me.uid);
      out.reqN = wq.length;
      out.late += wq.filter(function (r) { return reqOverdue(r) > 0; }).length;
      out.pending += wq.filter(function (r) { return reqOverdue(r) <= 0; }).length;
    } else {
      var prev0 = pushLocal();
      if (prev0.reqN != null) out.reqN = prev0.reqN;
    }
  } catch (e) {}
  /* Танилцалт — ACK_ME нь эрсдлийн хуудсанд ачаалагддаг тул байвал л авна */
  try {
    if (ACK_ME && ACK_ME.ready && !ACK_ME.none) {
      out.ackDue = (!ACK_ME.row && ACK_ME.gate && ACK_ME.gate.ok) ? 1 : 0;
    } else {
      var prev = pushLocal();
      if (prev.ackDue != null) out.ackDue = prev.ackDue;
    }
  } catch (e) {}
  return out;
}

/* subs.json-ыг уншиж → өөрчлөөд → бичээд → ЭРГЭЖ ШАЛГАНА.
   Хэд хэдэн хүн зэрэг бүртгүүлэхэд бичлэг алдагдахаас сэргийлнэ. */
async function pushSubsMerge(mutate, verifyUid) {
  for (var attempt = 0; attempt < 3; attempt++) {
    var cur = null;
    try { cur = await riskR2GetJson(PUSH_SUBS_FILE); } catch (e) { cur = null; }
    var list = (cur && Array.isArray(cur.list)) ? cur.list : [];
    var next = mutate(list.slice());
    if (next === null) return true;                     // өөрчлөх зүйлгүй
    await riskR2PutJson(PUSH_SUBS_FILE, { updatedAt: new Date().toISOString(), list: next });
    await new Promise(function (r) { setTimeout(r, 350 + Math.floor(Math.random() * 450)); });
    var back = null;
    try { back = await riskR2GetJson(PUSH_SUBS_FILE); } catch (e) {}
    var rows = (back && Array.isArray(back.list)) ? back.list : [];
    var found = rows.filter(function (x) { return x && x.uid === verifyUid; }).length > 0;
    if (verifyUid === null || found) return true;        // хүссэн бичлэг байрандаа
  }
  return false;
}

/* Сануулга ЭХЛҮҮЛЭХ (ажилтан товч дарсны дараа) */
async function pushEnable() {
  if (!pushSupported()) throw new Error('Таны хөтөч сануулгыг дэмжихгүй байна');
  if (pushNeedsInstall()) throw new Error('iPhone дээр сануулга авахын тулд эхлээд «Утсанд суулгах» товчоор нүүр дэлгэцэд нэмнэ үү');
  var s = pushStats();
  if (!s) throw new Error('Таны ажилтны бүртгэл олдсонгүй');

  var perm = await Notification.requestPermission();
  if (perm !== 'granted') {
    throw new Error(perm === 'denied'
      ? 'Сануулга хориглогдсон байна. Хөтчийн хаягийн хажуух 🔒 дарж «Сануулга (Notifications)»-ыг Зөвшөөрөх болгоно уу'
      : 'Зөвшөөрөл өгөгдсөнгүй');
  }
  var reg = await navigator.serviceWorker.ready;
  var sub = await reg.pushManager.getSubscription();
  if (sub) {
    /* Сервер түлхүүр солигдсон бол хуучин бүртгэл ажиллахгүй — шинэчилнэ */
    var same = false;
    try {
      var cur = new Uint8Array(sub.options.applicationServerKey || []);
      var want = pushB64ToU8(PUSH_PUB);
      same = cur.length === want.length;
      for (var i = 0; same && i < want.length; i++) if (cur[i] !== want[i]) same = false;
    } catch (e) { same = false; }
    if (!same) { try { await sub.unsubscribe(); } catch (e) {} sub = null; }
  }
  if (!sub) {
    sub = await reg.pushManager.subscribe({
      userVisibleOnly: true, applicationServerKey: pushB64ToU8(PUSH_PUB)
    });
  }
  var j = sub.toJSON();
  var rec = {
    uid: s.uid, endpoint: j.endpoint, keys: j.keys,
    late: s.late, pending: s.pending, ackDue: s.ackDue || 0, reqN: s.reqN || 0,
    at: new Date().toISOString()
  };
  var ok = await pushSubsMerge(function (list) {
    return list.filter(function (x) {
      return x && x.uid !== rec.uid && x.endpoint !== rec.endpoint;
    }).concat([rec]);
  }, rec.uid);
  if (!ok) throw new Error('Бүртгэлийг хадгалж чадсангүй — дахин оролдоно уу');
  pushLocalSet({ on: 1, uid: s.uid, ep: rec.endpoint, late: s.late, pending: s.pending,
    ackDue: s.ackDue || 0, reqN: s.reqN || 0, syncedAt: Date.now() });
  return true;
}

/* Сануулга ХААХ */
async function pushDisable() {
  var loc = pushLocal();
  try {
    var reg = await navigator.serviceWorker.ready;
    var sub = await reg.pushManager.getSubscription();
    if (sub) await sub.unsubscribe();
  } catch (e) {}
  var uid = loc.uid || (function () { try { return (myEmp() || {}).uid; } catch (e) { return ''; } })();
  try {
    await pushSubsMerge(function (list) {
      return list.filter(function (x) { return x && x.uid !== uid; });
    }, null);
  } catch (e) {}
  pushLocalSet({ on: 0 });
  return true;
}

/* Тоо өөрчлөгдсөн бол R2 дээрх бичлэгээ шинэчилнэ (зөвхөн ӨӨРЧЛӨГДӨХӨД).
   Мөн бичлэг ямар нэг шалтгаанаар алга болсон бол өөрөө нөхнө. */
function pushSyncState() {
  if (!pushSupported()) return;
  var loc = pushLocal();
  if (!loc.on || pushPerm() !== 'granted') return;
  var s = pushStats();
  if (!s || s.uid !== loc.uid) return;
  var stale = !loc.syncedAt || (Date.now() - loc.syncedAt) > 3 * 24 * 3600 * 1000;
  var changed = (s.late !== loc.late) || (s.pending !== loc.pending) ||
    ((s.ackDue || 0) !== (loc.ackDue || 0)) || ((s.reqN || 0) !== (loc.reqN || 0));
  if (!changed && !stale) return;
  if (pushSyncState._busy) return;
  pushSyncState._busy = true;
  (async function () {
    try {
      var reg = await navigator.serviceWorker.ready;
      var sub = await reg.pushManager.getSubscription();
      if (!sub) { pushLocalSet({ on: 0 }); return; }      // хэрэглэгч хөтчөөс хаасан
      var j = sub.toJSON();
      var rec = { uid: s.uid, endpoint: j.endpoint, keys: j.keys,
        late: s.late, pending: s.pending, ackDue: s.ackDue || 0, reqN: s.reqN || 0,
        at: new Date().toISOString() };
      await pushSubsMerge(function (list) {
        var mine = list.filter(function (x) { return x && x.uid === rec.uid; })[0];
        if (mine && !changed && mine.endpoint === rec.endpoint) return null;   // бүх зүйл байрандаа
        return list.filter(function (x) {
          return x && x.uid !== rec.uid && x.endpoint !== rec.endpoint;
        }).concat([rec]);
      }, rec.uid);
      pushLocalSet({ on: 1, uid: s.uid, ep: rec.endpoint, late: s.late, pending: s.pending,
        ackDue: s.ackDue || 0, reqN: s.reqN || 0, syncedAt: Date.now() });
    } catch (e) { console.warn('[push] sync', e && e.message); }
    finally { pushSyncState._busy = false; }
  })();
}

/* Туршилтын сануулга — сервер яг одоо надад л илгээнэ */
async function pushTest() {
  if (typeof fauth === 'undefined' || !fauth || !fauth.currentUser) throw new Error('Нэвтрээгүй байна');
  var idToken = await fauth.currentUser.getIdToken();
  var r = await fetch('/api/push-daily/', {
    method: 'POST', headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ idToken: idToken, test: 1 })
  });
  var j = null; try { j = await r.json(); } catch (e) {}
  if (!r.ok || !j || !j.ok) throw new Error((j && j.error) || ('Сервер ' + r.status));
  if (!j.sent) throw new Error(j.why || 'Илгээх бүртгэл олдсонгүй — «Сануулга авах»-ыг дахин дарна уу');
  return j;
}

/* Нүүр хуудас / арга хэмжээний хуудсанд гарах карт */
function pushCardHTML() {
  if (!pushSupported()) return '';
  var s = null; try { s = pushStats(); } catch (e) {}
  if (!s) return '';
  var loc = pushLocal(), perm = pushPerm();
  var on = (perm === 'granted' && !!loc.on);
  var need = (s.late || s.pending || s.ackDue) ? true : false;

  if (on) {
    return '<div id="pushCard" class="card" style="padding:13px 16px;margin-bottom:13px;display:flex;' +
      'align-items:center;gap:12px;flex-wrap:wrap;border:1.5px solid #D1FAE5;background:#F0FDF4">' +
      '<i class="ti ti-bell-check" style="font-size:22px;color:#059669;flex-shrink:0"></i>' +
      '<div style="flex:1;min-width:190px;font-size:12.5px;color:#065F46;line-height:1.6">' +
      '<b>Сануулга ажиллаж байна.</b> Сайт хаалттай байсан ч хугацаа хэтэрсэн арга хэмжээг ' +
      'энэ төхөөрөмж дээр сануулна.</div>' +
      '<button class="btn btn-sm btn-secondary" data-push-test="1" style="flex-shrink:0">' +
      '<i class="ti ti-send"></i> Туршиж үзэх</button>' +
      '<button class="btn btn-sm" data-push-off="1" style="flex-shrink:0;background:#fff;color:#64748B;border:1px solid #E2E8F0">' +
      'Хаах</button></div>';
  }
  if (perm === 'denied') {
    return '<div id="pushCard" class="card" style="padding:13px 16px;margin-bottom:13px;display:flex;' +
      'align-items:center;gap:12px;flex-wrap:wrap;border:1.5px solid #FDE68A;background:#FFFBEB">' +
      '<i class="ti ti-bell-off" style="font-size:22px;color:#B45309;flex-shrink:0"></i>' +
      '<div style="flex:1;min-width:190px;font-size:12.5px;color:#92400E;line-height:1.6">' +
      '<b>Сануулга хориглогдсон байна.</b> Хөтчийн хаягийн зүүн талын <b>🔒</b> дарж ' +
      '«Сануулга (Notifications)»-ыг <b>Зөвшөөрөх</b> болгоод хуудсаа шинэчилнэ үү.</div></div>';
  }
  if (pushNeedsInstall()) {
    return '<div id="pushCard" class="card" style="padding:13px 16px;margin-bottom:13px;display:flex;' +
      'align-items:center;gap:12px;flex-wrap:wrap;border:1.5px solid #E2E8F0">' +
      '<i class="ti ti-device-mobile" style="font-size:22px;color:#4F46E5;flex-shrink:0"></i>' +
      '<div style="flex:1;min-width:190px;font-size:12.5px;color:#475569;line-height:1.6">' +
      '<b>iPhone дээр сануулга авах бол</b> доод талын <b>Хуваалцах ⤴</b> → ' +
      '<b>«Нүүр дэлгэцэд нэмэх»</b> хийж аппаа суулгаад дараа нь энэ хуудсыг аппаас нээнэ үү.</div></div>';
  }
  return '<div id="pushCard" class="card" style="padding:13px 16px;margin-bottom:13px;display:flex;' +
    'align-items:center;gap:12px;flex-wrap:wrap;border:1.5px solid ' + (need ? '#FECACA' : '#E2E8F0') +
    ';background:' + (need ? '#FEF2F2' : '#fff') + '">' +
    '<i class="ti ti-bell-ringing" style="font-size:22px;color:' + (need ? '#DC2626' : '#4F46E5') + ';flex-shrink:0"></i>' +
    '<div style="flex:1;min-width:190px;font-size:12.5px;color:' + (need ? '#B91C1C' : '#475569') + ';line-height:1.6">' +
    (need
      ? '<b>Мартахгүйн тулд сануулга авна уу.</b> Сайт хаалттай, утас халаасанд байсан ч ' +
        'хугацаа нь дуусах гэж байгаа арга хэмжээг таньд сануулна.'
      : '<b>Сануулга авах.</b> Шинэ арга хэмжээ оногдох, хугацаа нь дуусах гэж байвал ' +
        'сайт хаалттай байсан ч танд мэдэгдэнэ.') +
    '</div>' +
    '<button class="btn btn-sm btn-primary" data-push-on="1" style="flex-shrink:0">' +
    '<i class="ti ti-bell"></i> Сануулга авах</button></div>';
}

/* Картыг дахин зурна (хуудсыг бүхэлд шинэчлэхгүйгээр) */
function pushCardRefresh() {
  var el = document.getElementById('pushCard');
  if (!el) return;
  var h = pushCardHTML();
  if (h) el.outerHTML = h; else el.remove();
}

function pushWireOnce() {
  if (pushWireOnce._done) return;
  pushWireOnce._done = true;
  document.addEventListener('click', function (ev) {
    var on = ev.target.closest && ev.target.closest('[data-push-on]');
    var off = ev.target.closest && ev.target.closest('[data-push-off]');
    var ts = ev.target.closest && ev.target.closest('[data-push-test]');
    if (!on && !off && !ts) return;
    var btn = on || off || ts, old = btn.innerHTML;
    btn.disabled = true; btn.innerHTML = '<i class="ti ti-loader-2"></i> ...';
    var job = on ? pushEnable() : (off ? pushDisable() : pushTest());
    job.then(function () {
      if (on) toast('Сануулга ажиллаж эхэллээ ✓', 'success');
      else if (off) toast('Сануулга хаагдлаа', 'info');
      else toast('Туршилтын сануулга илгээгдлээ — хэдэн секундын дараа гарч ирнэ', 'success');
      pushCardRefresh();
    }).catch(function (e) {
      btn.disabled = false; btn.innerHTML = old;
      toast((e && e.message) || 'Алдаа гарлаа', 'error');
    });
  });
}


/* ══════════════════════════════════════════════════════════════════════
   🦺 АЖЛЫН ХУВЦАС, ХАМГААЛАХ ХЭРЭГСЭЛ (ХХХ) — ТУСДАА ЯЛГАНА
   ----------------------------------------------------------------------
   Эрсдэлийн үнэлгээний «Авах арга хэмжээ»-ний дотор ХХХ-тэй холбоотой
   заалт 203 удаа таарсан. Тэдгээр нь бусад арга хэмжээнээс ӨӨР шинжтэй:
     · зарим нь ХУДАЛДАН АВАХ шаардлагатай (мөнгө, батлалт, хугацаа)
     · зарим нь ажилтан ӨӨРӨӨ өмсөх дүрэм
   Тиймээс дэлгэрэнгүйд тусад нь гаргаж, авах ёстойг нь шууд ХҮСЭЛТ
   болгож илгээх боломжтой болголоо.

   ⚠ Кирилл дээр \b ажиллахгүй тул «ШИЛжүүлэх», «ажлын БҮС», «газарДУУЛГА»,
     «ПАЙЗ ЗҮҮх», «ШИЛ сав» зэрэг ХУДАЛ таарцыг тусгайлан хасна.
   ══════════════════════════════════════════════════════════════════════ */
var PPE_ITEMS = [
  { k: 'Гар — бээлий, ханцуйвч',   re: /бээлий|ханцуйвч|гар хамгаалах/i },
  { k: 'Нүд — хамгаалалтын шил',   re: /нүдний шил|хамгаалалтын шил|хамгаалалттай шил|нүдэвч/i },
  { k: 'Амьсгал — маск, респиратор', re: /маск|ffp2|респиратор|амьсгал хамгаалах/i },
  { k: 'Нүүр — баг, бамбай',       re: /нүүр хамгаалах|нүүрний баг|бамбай/i },
  { k: 'Сонсгол — чихэвч',         re: /чихэвч|сонсгол хамгаалах|чихний бөглөө/i },
  { k: 'Толгой — каск, дуулга',    re: /каск|шлем|толгой хамгаалах|хамгаалалтын малгай/i },
  { k: 'Хөл — хамгаалалтын гутал', re: /safety гутал|хамгаалалтын гутал|ажлын гутал|гутлаа|хальтардаггүй улт|углааш/i },
  { k: 'Бие — ажлын хувцас',       re: /ажлын хувцас|хамгаалах хувцас|иж бүрэн хувцас|улирлын онцлогт тохирсон|улиралд тохирсон хувцас|хувцасаа|хувцасыг|халаад|хормогч/i },
  { k: 'Гэрэл ойлгогч хантааз',    re: /хантааз/i },
  { k: 'Ерөнхий ХХХ',              re: /ххх|нэг бүрийн хамгаалах|хамгаалах хэрэгсэл|хамгаалах хэрэгслэ|хамгаалах хэрэгсли|хамгаалалтын нэг удаагийн/i }
];
var PPE_FALSE = [
  /газардуулга/i, /пайз/i, /унтраах товчийг дараад/i, /усны хамгаалалттай болгох/i,
  /хөдөлмөрийн гэрээнд өөрчлөлт/i, /ажлын бүс(?:эд| рүү| ру)/i,
  /ачааг (?:шилжүүлэхийн|газраас)/i, /тохойн байрлал/i, /дэлгэцийн хамгаалалт/i,
  /хамгаалалтыг авахгүй байх, зүсэлтэд/i, /хурц ирмэгтэй булан тохой/i, /чийгшилийг/i,
  /нүдээ аньж/i, /шил сав/i, /шилжүүлэгч зам|тэргий?н өндөр|тэргэнц/i,
  /хэвийг бэхлэх бүслүүр/i, /хаалт хашилт/i
];
/* Худалдан авах / олгох шинжтэй үү (ханг-, олго-, худалдан ав-…) */
var PPE_BUY = /ханг|олго|худалдан ав|авч ашиглуул|сонгож|сонгон авах|судал|шинээр|тэй болох|нөөц|сайжруул/i;
var PPE_NOTBUY = /өөрийн хальтардаггүй|углааш|сонгон өмсөх/i;

/* Энэ арга хэмжээ ХХХ-тэй холбоотой юу? → төрлүүдийн жагсаалт (хоосон бол үгүй) */
function meaPPEKinds(text) {
  var t = String(text || '');
  if (!t) return [];
  for (var i = 0; i < PPE_FALSE.length; i++) if (PPE_FALSE[i].test(t)) return [];
  var out = [];
  PPE_ITEMS.forEach(function (it) { if (it.re.test(t)) out.push(it.k); });
  if (out.length > 1) out = out.filter(function (k) { return k !== 'Ерөнхий ХХХ'; });
  return out;
}
function meaIsPPE(text) { return meaPPEKinds(text).length > 0; }
function meaPPEBuy(text) {
  var t = String(text || '');
  return PPE_BUY.test(t) && !PPE_NOTBUY.test(t);
}

/* Тухайн эрсдлийн ХХХ-ийн заалтууд */
function riskPPEList(r) {
  var out = [];
  try {
    riskMeasures(r).forEach(function (m) {
      var kinds = meaPPEKinds(m.text);
      if (!kinds.length) return;
      out.push({ i: m.i, text: m.text, kinds: kinds, buy: meaPPEBuy(m.text) });
    });
  } catch (e) {}
  return out;
}

/* Дэлгэрэнгүй доторх «🦺 Ажлын хувцас, хамгаалах хэрэгсэл» блок */
function riskPPEBlockHTML(r) {
  var list = riskPPEList(r);
  if (!list.length) return '';
  var buy = list.filter(function (x) { return x.buy; });
  var wear = list.filter(function (x) { return !x.buy; });
  var canReq = false;
  try { canReq = reqCanCreate(); } catch (e) {}

  var row = function (x, isBuy) {
    return '<div style="display:flex;gap:10px;align-items:flex-start;padding:11px 12px;border:1px solid ' +
      (isBuy ? '#FDE68A' : '#F1F5F9') + ';border-radius:11px;margin-bottom:8px;background:' +
      (isBuy ? '#FFFBEB' : '#F8FAFC') + '">' +
      '<span style="flex:0 0 auto;font-size:16px;line-height:1.3">' + (isBuy ? '🛒' : '🦺') + '</span>' +
      '<span style="flex:1;min-width:0">' +
      '<span style="display:block;font-size:13px;color:#1E293B;line-height:1.55">' + esc(x.text) + '</span>' +
      '<span style="display:block;font-size:11px;color:#94A3B8;margin-top:4px">' +
      x.kinds.map(function (k) {
        return '<span style="display:inline-block;background:#EEF2FF;color:#4338CA;border-radius:5px;' +
          'padding:1px 7px;margin-right:4px;font-weight:700">' + esc(k) + '</span>';
      }).join('') + '</span></span>' +
      (function () {
        if (!isBuy) return '';
        /* Энэ заалтад хүсэлт аль хэдийн гарсан бол дахин гаргуулахгүй — явцыг нь харуулна */
        var ex = null; try { ex = riskReqForMeasure(r, x.text); } catch (e) {}
        if (ex) {
          var S2 = REQ_ST[ex.status] || REQ_ST.running;
          var ov2 = reqOverdue(ex);
          return '<button data-req-open="' + esc(ex.id) + '" style="flex-shrink:0;cursor:pointer;font-family:inherit;' +
            'background:' + S2.bg + ';border:1.5px solid ' + S2.c + '3D;color:' + S2.c + ';border-radius:9px;' +
            'padding:6px 11px;font-size:11.5px;font-weight:800;text-align:left;line-height:1.4">' +
            S2.t + '<span style="display:block;font-weight:600;font-size:10.5px;opacity:.85">' +
            (ov2 > 0 ? '⚠ ' + ov2 + ' өдөр хэтэрсэн' : riskReqWhere(ex)) + '</span></button>';
        }
        if (!canReq) return '';
        return '<button class="btn btn-sm btn-primary" data-ppe-req="' + esc(r.id) + '|' + x.i + '" style="flex-shrink:0">' +
          '<i class="ti ti-send"></i> Хүсэлт гаргах</button>';
      })() + '</div>';
  };

  var H = '';
  if (buy.length) {
    H += '<div style="font-size:11.5px;font-weight:800;color:#B45309;letter-spacing:.3px;margin:2px 0 7px">' +
      '🛒 ХУДАЛДАН АВАХ / ОЛГОХ ЁСТОЙ (' + buy.length + ')</div>' +
      buy.map(function (x) { return row(x, true); }).join('') +
      (canReq
        ? '<div style="font-size:11.5px;color:#94A3B8;line-height:1.55;margin:-2px 0 11px">' +
          '«Хүсэлт гаргах» дарвал маршрут (ХАБЭА → Санхүү → Хангамж) урьдчилан бөглөгдөж, ' +
          'хугацаа хэтэрвэл тухайн шатны хүний KPI-аас хасагдана.</div>'
        : '<div style="font-size:11.5px;color:#94A3B8;margin:-2px 0 11px">Хүсэлтийг менежер, албаны хариуцагч гаргана.</div>');
  }
  if (wear.length) {
    H += '<div style="font-size:11.5px;font-weight:800;color:#334155;letter-spacing:.3px;margin:2px 0 7px">' +
      '🦺 АЖИЛТАН ӨМСӨХ / ХЭРЭГЛЭХ (' + wear.length + ')</div>' +
      wear.map(function (x) { return row(x, false); }).join('');
  }
  /* ⭐ Гаргасан хүсэлтүүд — хаана яваа нь эндээс харагдана */
  H += riskReqLogHTML(r);
  return H;
}

/* Энэ эрсдэлээс гарсан ХҮСЭЛТҮҮД (бүгдэд харагдана) */
function riskReqsOf(r) {
  if (!REQ_OK || !r) return [];
  var rid = String(r.id);
  return (REQ_ROWS || []).filter(function (x) { return x && String(x.riskId || '') === rid; })
    .sort(function (a, b) { return String(b.at).localeCompare(String(a.at)); });
}
/* Тухайн АРГА ХЭМЖЭЭНИЙ төлөө хүсэлт гаргасан эсэх */
function riskReqForMeasure(r, mtext) {
  var t = String(mtext || '').replace(/\s+/g, ' ').trim().toLowerCase();
  return riskReqsOf(r).filter(function (x) {
    return String(x.measure || '').replace(/\s+/g, ' ').trim().toLowerCase() === t;
  })[0] || null;
}
/* Хүсэлтийн одоогийн байдал — нэг мөрөөр */
function riskReqWhere(x) {
  if (x.status === 'done') return 'Бүрэн батлагдсан';
  if (x.status === 'cancelled') return 'Цуцалсан';
  var st = (x.steps || [])[x.step || 0];
  if (!st) return '';
  if (x.status === 'returned') return esc(st.name || '') + ' буцаасан';
  var ov = reqOverdue(x);
  return esc(st.name || st.dept || '') + ' дээр' +
    (ov > 0 ? ' · ⚠ ' + ov + ' өдөр хэтэрсэн' : ' · ' + reqDaysAtStep(x) + ' өдөр болсон');
}
/* 📨 ЭНЭ ЭРСДЭЛД ГАРГАСАН ХҮСЭЛТ — «Таны авсан арга хэмжээ»-тэй ижил хэв */
function riskReqLogHTML(r) {
  var list = riskReqsOf(r);
  if (!list.length) return '';
  return '<div style="margin-top:14px;padding-top:12px;border-top:1px solid #F1F5F9">' +
    '<div style="font-size:12.5px;font-weight:900;color:#334155;letter-spacing:.3px;margin-bottom:8px">' +
    '📨 ЭНЭ ЭРСДЭЛД ГАРГАСАН ХҮСЭЛТ (' + list.length + ')</div>' +
    list.map(function (x) {
      var S = REQ_ST[x.status] || REQ_ST.running;
      var ov = reqOverdue(x);
      return '<div data-req-open="' + esc(x.id) + '" style="background:#fff;border:1px solid ' +
        (ov > 0 ? '#FECACA' : '#E2E8F0') + ';border-left:3px solid ' + (ov > 0 ? '#DC2626' : S.c) +
        ';border-radius:12px;padding:11px 13px;margin-bottom:8px;cursor:pointer">' +
        '<div style="display:flex;gap:10px;align-items:baseline;flex-wrap:wrap">' +
        '<span style="flex:1;min-width:140px;font-size:13px;font-weight:700;color:#1E293B;line-height:1.5">' +
        esc(x.title || '') + '</span>' +
        '<span style="background:' + S.bg + ';color:' + S.c + ';border-radius:6px;padding:2px 9px;' +
        'font-size:11px;font-weight:800;flex-shrink:0">' + S.t + '</span></div>' +
        '<div style="font-size:11.5px;color:' + (ov > 0 ? '#B91C1C' : '#94A3B8') + ';margin-top:5px">' +
        '👤 ' + esc(x.byName || '') + ' · ' + ackDateMn(x.at) + ' · ' + riskReqWhere(x) + '</div>' +
        '<div style="display:flex;gap:5px;flex-wrap:wrap;margin-top:7px">' +
        (x.steps || []).map(function (st, i) { return reqStepChip(x, st, i); }).join('') + '</div>' +
        '</div>';
    }).join('') + '</div>';
}

/* «Хүсэлт гаргах» товч → урьдчилан бөглөсөн хүсэлтийн цонх */
function ppeOpenRequest(riskId, mi) {
  var r = (DB.risks || []).filter(function (x) { return String(x.id) === String(riskId); })[0];
  if (!r) { toast('Эрсдэл олдсонгүй', 'error'); return; }
  var m = riskMeasures(r).filter(function (x) { return x.i === mi; })[0];
  if (!m) { toast('Арга хэмжээ олдсонгүй', 'error'); return; }
  var kinds = meaPPEKinds(m.text);
  var L = riskLevel(r);
  reqNewModal({
    title: kinds.length ? kinds[0].split('—').pop().trim() : 'Хамгаалах хэрэгсэл',
    items: '',
    forWho: (r.position || (r.positions || []).join(', ') || ''),
    reason: 'Эрсдэлийн үнэлгээгээр шаардсан. Эрсдэлийн зэрэг: ' + L.code + ' · ' + L.name +
      ' (' + riskScore(r) + '). Алба: ' + (riskCanonDept(r.dept) || r.dept || ''),
    riskId: String(r.id), riskHazard: r.hazard || '', measure: m.text
  });
}


/* ══════════════════════════════════════════════════════════════════════
   ХХХ-ИЙН ХҮСЭЛТ — ОЛОН ШАТТ БАТЛАЛТ
   ----------------------------------------------------------------------
   Асуудал: ажлын хувцас, хамгаалах хэрэгсэл авахад менежер → эрүүл ахуйч →
   санхүү → эрүүл ахуйч → хангамж → ... гэсэн 7 дамжлагаар явж, хаана
   гацсан нь ХЭНД Ч ХАРАГДДАГГҮЙ тул сар сараар хойшилдог.

   Шийдэл:
     ① Хүсэлт гаргагч МАРШРУТАА ӨӨРӨӨ сонгоно (алба + албан тушаалтан),
        шат бүрийн хугацааг өөрөө тавина (доод тал 2 ажлын өдөр)
     ② Хүсэлт бүр ХЭН дээр ХЭДЭН ӨДӨР байгаа нь самбар дээр ил харагдана
     ③ Хугацаа хэтэрвэл push сануулга + KPI-ийн «Босго оноо»-ноос
        хоногт 1 оноо (дээд тал 10) хасагдана
     ④ Батлагч нэг удаа хугацаа сунгах эрхтэй — үндэслэлтэй бол шийтгэлгүй
   ══════════════════════════════════════════════════════════════════════ */
var REQ_FILE = 'requests/_all.json';
var REQ_ROWS = null, REQ_OK = false;
var REQ_MIN_DAYS = 2;            // нэг шатны доод хугацаа (ажлын өдөр)
var REQ_PEN_MAX = 10;            // KPI-аас хасах дээд оноо

async function reqLoad(force) {
  if (REQ_OK && !force) return REQ_ROWS;
  try {
    var j = await riskR2GetJson(REQ_FILE);
    REQ_ROWS = (j && Array.isArray(j.list)) ? j.list : [];
    REQ_OK = true;
  } catch (e) { REQ_ROWS = REQ_ROWS || []; }
  return REQ_ROWS;
}

/* Уншиж → өөрчилж → бичээд → ЭРГЭЖ ШАЛГАНА (зэрэг ажиллахад алдагдахгүй) */
async function reqSaveMerge(mutate, verifyId) {
  for (var k = 0; k < 3; k++) {
    var cur = [];
    try { var j = await riskR2GetJson(REQ_FILE); cur = (j && Array.isArray(j.list)) ? j.list : []; } catch (e) {}
    var next = mutate(cur.slice());
    if (!next) return true;
    await riskR2PutJson(REQ_FILE, { updatedAt: new Date().toISOString(), list: next });
    await new Promise(function (r) { setTimeout(r, 350 + Math.floor(Math.random() * 400)); });
    var back = [];
    try { var j2 = await riskR2GetJson(REQ_FILE); back = (j2 && Array.isArray(j2.list)) ? j2.list : []; } catch (e) {}
    REQ_ROWS = back; REQ_OK = true;
    if (!verifyId) return true;
    if (back.some(function (x) { return x && x.id === verifyId; })) return true;
  }
  return false;
}

/* ── Ажлын өдрөөр тооцох (Бямба, Ням орохгүй) ── */
function reqAddWorkDays(fromMs, days) {
  var d = new Date(fromMs), n = Math.max(1, parseInt(days, 10) || 1);
  while (n > 0) { d.setDate(d.getDate() + 1); var w = d.getDay(); if (w !== 0 && w !== 6) n--; }
  d.setHours(18, 0, 0, 0);
  return d.toISOString();
}
function reqWorkDaysSince(iso) {
  if (!iso) return 0;
  var a = new Date(iso), b = new Date();
  if (isNaN(a) || b <= a) return 0;
  var d = new Date(a), n = 0;
  while (d < b) { d.setDate(d.getDate() + 1); var w = d.getDay(); if (w !== 0 && w !== 6) n++; }
  return n;
}

/* ⚠ ХАБЭА/админ хэрэглэгч ажилтны бүртгэлд байхгүй байж болно.
   Тэр үед сешнээс нь биеийг нөхөж, хүсэлт гаргах боломжийг хаахгүй. */
function reqMe() {
  var me = null; try { me = myEmp(); } catch (e) {}
  if (me && me.uid) return me;
  try {
    if (SESSION && (isAdmin() || isDeptHead())) {
      var uid = SESSION.uid || '';
      try { if (!uid && typeof fauth !== 'undefined' && fauth && fauth.currentUser) uid = fauth.currentUser.uid; } catch (e2) {}
      if (!uid && SESSION.email) uid = 'u:' + String(SESSION.email).toLowerCase();
      return { uid: uid, name: SESSION.name || SESSION.email || 'ХАБЭА-н алба',
        pos: SESSION.pos || 'ХАБЭА-н алба', dept: SESSION.dept || '' };
    }
  } catch (e) {}
  return null;
}

function reqStep(r) { return (r && r.steps) ? (r.steps[r.step || 0] || null) : null; }
function reqOverdue(r) {
  if (!r || r.status !== 'running') return 0;
  var s = reqStep(r);
  return (s && s.dueAt) ? reqWorkDaysSince(s.dueAt) : 0;
}
function reqPenalty(r) { return Math.min(REQ_PEN_MAX, reqOverdue(r)); }
function reqDaysAtStep(r) {
  var s = reqStep(r);
  if (!s || !s.startAt) return 0;
  return reqWorkDaysSince(s.startAt);
}

function reqWaitingFor(uid) {
  return (REQ_ROWS || []).filter(function (r) {
    if (r.status !== 'running') return false;
    var s = reqStep(r); return s && s.uid === uid;
  });
}
function reqMine(uid) { return (REQ_ROWS || []).filter(function (r) { return r.byUid === uid; }); }
function reqCanCreate() {
  if (isAdmin() || isDeptHead()) return true;
  try { return ackRoleOf(myEmp()) !== 'emp'; } catch (e) { return false; }
}
/* Тухайн шатыг би шийдэх ёстой юу */
function reqIsMyStep(r) {
  var me = reqMe(), s = reqStep(r);
  return !!(me && s && r.status === 'running' && s.uid === me.uid);
}
/* Хүсэлтийг зогсоох/цуцлах эрх — гаргасан хүн, ХАБЭА, админ */
function reqCanCancel(r) {
  var me = reqMe();
  return isAdmin() || (me && r.byUid === me.uid);
}

var REQ_ST = {
  running:   { t: 'Явагдаж байна', c: '#2563EB', bg: '#EFF6FF' },
  returned:  { t: 'Буцаагдсан',    c: '#DC2626', bg: '#FEF2F2' },
  done:      { t: 'Бүрэн батлагдсан', c: '#059669', bg: '#F0FDF4' },
  cancelled: { t: 'Цуцалсан',      c: '#64748B', bg: '#F8FAFC' }
};

/* ══ ҮЙЛДЛҮҮД ══ */
async function reqCreate(data) {
  var me = reqMe();
  if (!me) throw new Error('Таны бүртгэл олдсонгүй');
  var id = 'REQ-' + new Date().getFullYear() + '-' + Date.now().toString(36).toUpperCase();
  var now = new Date().toISOString();
  var steps = (data.steps || []).map(function (s, i) {
    return {
      i: i, dept: s.dept || '', uid: s.uid, name: s.name || '', pos: s.pos || '',
      days: Math.max(REQ_MIN_DAYS, parseInt(s.days, 10) || REQ_MIN_DAYS),
      status: 'wait', at: '', note: '', dueAt: '', startAt: '', ext: 0
    };
  });
  if (!steps.length) throw new Error('Дор хаяж нэг батлах шат сонгоно уу');
  steps[0].status = 'pending';
  steps[0].startAt = now;
  steps[0].dueAt = reqAddWorkDays(Date.now(), steps[0].days);

  var rec = {
    id: id, at: now,
    byUid: me.uid, byName: me.name || '', byPos: me.pos || me.role || '',
    byDept: riskCanonDept(me.dept) || me.dept || '',
    title: data.title || '', items: data.items || '', forWho: data.forWho || '',
    reason: data.reason || '', sum: parseFloat(data.sum) || 0,
    riskId: data.riskId || '', riskHazard: data.riskHazard || '', measure: data.measure || '',
    steps: steps, step: 0, status: 'running',
    log: [{ at: now, uid: me.uid, name: me.name || '', what: 'Хүсэлт гаргав' }]
  };
  var ok = await reqSaveMerge(function (list) { return list.concat([rec]); }, id);
  if (!ok) throw new Error('Хадгалж чадсангүй — дахин оролдоно уу');
  return rec;
}

async function reqAct(id, kind, note, extDays) {
  var me = reqMe();
  if (!me) throw new Error('Таны бүртгэл олдсонгүй');
  var done = false;
  var ok = await reqSaveMerge(function (list) {
    var r = list.filter(function (x) { return x && x.id === id; })[0];
    if (!r) return null;
    var s = r.steps[r.step];
    if (!s) return null;
    var now = new Date().toISOString();
    r.log = r.log || [];

    if (kind === 'ok') {
      if (s.uid !== me.uid && !isAdmin()) return null;
      s.status = 'ok'; s.at = now; s.note = note || '';
      s.lateDays = reqWorkDaysSince(s.dueAt);
      r.log.push({ at: now, uid: me.uid, name: me.name || '', what: 'Баталлаа', note: note || '' });
      if (r.step >= r.steps.length - 1) { r.status = 'done'; r.doneAt = now; }
      else {
        r.step++;
        var n = r.steps[r.step];
        n.status = 'pending'; n.startAt = now; n.dueAt = reqAddWorkDays(Date.now(), n.days);
      }
    } else if (kind === 'back') {
      if (s.uid !== me.uid && !isAdmin()) return null;
      s.status = 'back'; s.at = now; s.note = note || '';
      r.status = 'returned';
      r.log.push({ at: now, uid: me.uid, name: me.name || '', what: 'Буцаав', note: note || '' });
    } else if (kind === 'ext') {
      if (s.uid !== me.uid && !isAdmin()) return null;
      if (s.ext) return null;                       // нэг л удаа сунгана
      var d = Math.max(1, parseInt(extDays, 10) || 1);
      s.ext = d; s.extNote = note || '';
      s.dueAt = reqAddWorkDays(Date.now(), d);
      r.log.push({ at: now, uid: me.uid, name: me.name || '',
        what: 'Хугацааг ' + d + ' ажлын өдрөөр сунгав', note: note || '' });
    } else if (kind === 'cancel') {
      r.status = 'cancelled';
      r.log.push({ at: now, uid: me.uid, name: me.name || '', what: 'Цуцлав', note: note || '' });
    } else if (kind === 'resend') {
      if (r.byUid !== me.uid && !isAdmin()) return null;
      s.status = 'pending'; s.at = ''; s.note = ''; s.startAt = now;
      s.dueAt = reqAddWorkDays(Date.now(), s.days);
      r.status = 'running';
      r.log.push({ at: now, uid: me.uid, name: me.name || '', what: 'Засаад дахин илгээв', note: note || '' });
    } else return null;
    done = true;
    return list;
  }, id);
  if (!ok || !done) throw new Error('Хадгалж чадсангүй — хуудсаа шинэчлээд дахин оролдоно уу');
  return true;
}

/* ══ KPI — хугацаа хэтэрсэн шатны эзэнд зөрчил бүртгэнэ ══
   ⚠ Зөрчил нь «Босго оноо»-ноос хасагдана (DB.violations). Хоногт 1 оноо,
   дээд тал 10. Шат дуусмагц оноо ЗОГСОНО (устгахгүй — түүх үлдэнэ).
   Админ буруу гэж үзвэл Зөрчлийн бүртгэлээс устгаж болно. */
function reqSyncViolations() {
  if (!isAdmin() && !isDeptHead()) return 0;
  DB.violations = DB.violations || [];
  var changed = 0;
  (REQ_ROWS || []).forEach(function (r) {
    var over = reqOverdue(r);
    if (over <= 0) return;
    var s = reqStep(r);
    if (!s || !s.uid) return;
    var emp = (DB.employees || []).filter(function (e) { return e.uid === s.uid; })[0];
    if (!emp) return;
    var vid = 'VL-REQ-' + r.id + '-' + r.step;
    var pts = Math.min(REQ_PEN_MAX, over);
    var desc = 'ХХХ-ийн хүсэлт «' + (r.title || r.id) + '» — ' + over +
      ' ажлын өдөр хугацаа хэтэрсэн (шат ' + (r.step + 1) + ')';
    var ex = DB.violations.filter(function (v) { return v.id === vid; })[0];
    if (ex) {
      if (ex.points !== pts || ex.desc !== desc) { ex.points = pts; ex.desc = desc; changed++; }
    } else {
      DB.violations.push({
        id: vid, empId: emp.id, date: todayISO(), desc: desc, points: pts,
        by: 'систем (автомат)', createdAt: new Date().toISOString(), reqId: r.id
      });
      changed++;
    }
  });
  if (changed) { try { saveDB(); } catch (e) {} }
  return changed;
}

/* ══ ХАРАГДАЦ ══ */
function reqPersonOptions(dept) {
  var list = (DB.employees || []).filter(function (e) {
    if (!e.uid) return false;
    if (!dept) return true;
    return riskSameDept(dept, e.dept);
  });
  return list.sort(function (a, b) { return String(a.name || '').localeCompare(String(b.name || '')); });
}
/* Урьдчилан санал болгох маршрут: ХАБЭА → Санхүү → Хангамж */
function reqDefaultRoute() {
  var sys = [];
  try { sys = deptList() || []; } catch (e) {}
  var find = function (re) { return sys.filter(function (d) { return re.test(d); })[0] || ''; };
  return [
    { dept: find(/хөдөлмөрийн аюулгүй|хабэа/i), days: 2 },
    { dept: find(/санхүү/i), days: 3 },
    { dept: find(/хангамж/i), days: 14 }
  ].filter(function (s) { return s.dept; });
}

function reqStepChip(r, s, idx) {
  var cur = (r.step === idx && r.status === 'running');
  var col = s.status === 'ok' ? '#059669' : s.status === 'back' ? '#DC2626'
    : cur ? (reqOverdue(r) > 0 ? '#DC2626' : '#2563EB') : '#CBD5E1';
  var ic = s.status === 'ok' ? '✓' : s.status === 'back' ? '↩' : (idx + 1);
  return '<span style="display:inline-flex;align-items:center;gap:6px;padding:3px 9px;border-radius:20px;' +
    'background:' + col + '14;border:1px solid ' + col + '3D;font-size:11.5px;font-weight:700;color:' + col + '">' +
    '<span style="width:15px;height:15px;border-radius:50%;background:' + col + ';color:#fff;display:inline-flex;' +
    'align-items:center;justify-content:center;font-size:9.5px;font-weight:900">' + ic + '</span>' +
    esc(String(s.name || s.dept || '').split(' ').slice(0, 2).join(' ')) + '</span>';
}

function reqRowHTML(r, showWho) {
  var S = REQ_ST[r.status] || REQ_ST.running;
  var over = reqOverdue(r), s = reqStep(r);
  var at = reqDaysAtStep(r);
  return '<div data-req-open="' + esc(r.id) + '" style="border:1px solid ' + (over > 0 ? '#FECACA' : '#E2E8F0') +
    ';border-left:4px solid ' + (over > 0 ? '#DC2626' : S.c) + ';border-radius:12px;padding:12px 14px;' +
    'margin-bottom:9px;cursor:pointer;background:' + (over > 0 ? '#FEF2F2' : '#fff') + '">' +
    '<div style="display:flex;align-items:flex-start;gap:12px;flex-wrap:wrap">' +
    '<div style="flex:1;min-width:220px">' +
    '<div style="font-size:14px;font-weight:800;color:#0F172A;line-height:1.4">' + esc(r.title || '—') + '</div>' +
    '<div style="font-size:11.5px;color:#94A3B8;margin-top:3px">' +
    esc(r.id) + ' · ' + ackDateMn(r.at) + ' · ' + esc(r.byName || '') +
    (r.byDept ? ' (' + esc(r.byDept) + ')' : '') +
    (r.sum ? ' · <b style="color:#334155">' + Number(r.sum).toLocaleString() + '₮</b>' : '') + '</div>' +
    '</div>' +
    '<div style="flex-shrink:0;text-align:right">' +
    '<span style="background:' + S.bg + ';color:' + S.c + ';border-radius:7px;padding:3px 10px;font-size:11.5px;font-weight:800">' +
    S.t + '</span>' +
    (r.status === 'running' && s
      ? '<div style="font-size:11.5px;margin-top:5px;color:' + (over > 0 ? '#B91C1C' : '#64748B') + ';font-weight:' + (over > 0 ? '800' : '600') + '">' +
        (over > 0 ? '⚠ ' + over + ' өдөр хэтэрсэн · −' + reqPenalty(r) + ' оноо'
                  : (showWho !== false ? esc(s.name || '') + ' дээр ' + at + ' өдөр' : at + ' өдөр болж байна')) + '</div>'
      : '') +
    '</div></div>' +
    '<div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:9px">' +
    (r.steps || []).map(function (x, i) { return reqStepChip(r, x, i); }).join('') + '</div>' +
    '</div>';
}

/* ══ АВАХ ШААРДЛАГАТАЙ ХХХ — эрсдэлийн үнэлгээнээс шууд ══
   Хүсэлтийн таб урьд нь ЗӨВХӨН гаргасан хүсэлтийг харуулдаг байсан тул
   шинэ хэрэглэгчид хоосон харагддаг байв. Одоо «юу авах ёстой»-г
   эрсдэлийн үнэлгээнээс өөрөө цуглуулж, нэг товчоор хүсэлт болгоно. */
function reqNeededPPE() {
  var rows = [];
  try {
    if (isAdmin() || isDeptHead() || riskDirScope()) rows = risksForView();
    else { var me = myEmp(); rows = me ? (riskSeenBy(me).rows || []) : []; }
  } catch (e) { rows = []; }
  var seen = {}, out = [];
  rows.forEach(function (r) {
    var dept = riskCanonDept(r.dept) || r.dept || '';
    var lst = [];
    try { lst = riskPPEList(r); } catch (e) { return; }
    lst.forEach(function (x) {
      if (!x.buy) return;                       // зөвхөн ХУДАЛДАН АВАХ шинжтэй
      var k = meaKeyOf(dept, x.text);
      if (seen[k]) { seen[k].n++; if (r.position && seen[k].pos.indexOf(r.position) < 0) seen[k].pos.push(r.position); return; }
      seen[k] = { key: k, text: x.text, kinds: x.kinds, dept: dept, risk: r, mi: x.i, n: 1,
        pos: r.position ? [r.position] : [], lvl: riskLevel(r), score: riskScore(r) };
      out.push(seen[k]);
    });
  });
  return out.sort(function (a, b) { return b.score - a.score; });
}

function reqNeedHTML() {
  var need = reqNeededPPE();
  if (!need.length) return '';
  var canReq = false;
  try { canReq = reqCanCreate(); } catch (e) {}
  var doneN = 0;
  var rowsH = need.slice(0, 60).map(function (x) {
    var ex = null;
    try { ex = riskReqForMeasure(x.risk, x.text); } catch (e) {}
    if (ex) doneN++;
    var S = ex ? (REQ_ST[ex.status] || REQ_ST.running) : null;
    return '<div style="display:flex;gap:11px;align-items:flex-start;padding:11px 12px;border:1px solid ' +
      (ex ? '#D1FAE5' : '#FDE68A') + ';border-radius:11px;margin-bottom:8px;background:' +
      (ex ? '#F0FDF4' : '#FFFBEB') + '">' +
      '<span style="flex:0 0 auto;font-size:16px;line-height:1.3">' + (ex ? '✅' : '🛒') + '</span>' +
      '<span style="flex:1;min-width:0">' +
      '<span style="display:block;font-size:13px;color:#1E293B;line-height:1.55">' + esc(x.text) + '</span>' +
      '<span style="display:block;font-size:11px;color:#94A3B8;margin-top:4px">' +
      x.kinds.map(function (k) {
        return '<span style="display:inline-block;background:#EEF2FF;color:#4338CA;border-radius:5px;' +
          'padding:1px 7px;margin-right:4px;font-weight:700">' + esc(k) + '</span>';
      }).join('') +
      '<span style="color:#B6BECC">' + esc(x.dept) +
      (x.pos.length ? ' · ' + esc(x.pos.slice(0, 2).join(', ')) : '') +
      (x.n > 1 ? ' · ' + x.n + ' эрсдэлд' : '') + '</span></span></span>' +
      (ex
        ? '<button data-req-open="' + esc(ex.id) + '" style="flex-shrink:0;cursor:pointer;font-family:inherit;' +
          'background:' + S.bg + ';border:1.5px solid ' + S.c + '3D;color:' + S.c + ';border-radius:9px;' +
          'padding:6px 11px;font-size:11.5px;font-weight:800">' + S.t + '</button>'
        : (canReq
          ? '<button class="btn btn-sm btn-primary" data-need-req="' + esc(x.risk.id) + '|' + x.mi + '" style="flex-shrink:0">' +
            '<i class="ti ti-send"></i> Хүсэлт гаргах</button>'
          : '')) +
      '</div>';
  }).join('');

  return '<div class="card" style="padding:15px 17px;margin-bottom:13px;border:1.5px solid #FDE68A">' +
    '<div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-bottom:3px">' +
    '<div style="font-size:14px;font-weight:800;color:#92400E">🛒 Авах шаардлагатай ХХХ</div>' +
    '<div style="background:#FEF3C7;color:#92400E;border-radius:20px;padding:2px 10px;font-size:12px;font-weight:800">' +
    doneN + ' / ' + need.length + '</div></div>' +
    '<div style="font-size:12px;color:#8A6D3B;margin-bottom:11px;line-height:1.6">' +
    'Эрсдэлийн үнэлгээнд <b>«хангах, олгох, авах»</b> гэж бичсэн ажлын хувцас, хамгаалах хэрэгсэл. ' +
    'Товч дарахад маршрут (ХАБЭА → Санхүү → Хангамж) урьдчилан бөглөгдөнө.</div>' +
    rowsH +
    (need.length > 60 ? '<div style="font-size:12px;color:#94A3B8;margin-top:6px">+' + (need.length - 60) + ' бусад</div>' : '') +
    '</div>';
}

function renderRequestPage(box) {
  if (!box) return;
  var me = reqMe();
  if (!REQ_OK) {
    if (!renderRequestPage._once) {
      renderRequestPage._once = true;          /* нэг удаа л */
      reqLoad().then(function () {
        try { reqSyncViolations(); } catch (e) {}
        renderHazards();
      }).catch(function (e) { console.error('[req]', e); });
    }
    box.innerHTML = '<div style="padding:34px;text-align:center;color:#94A3B8">' +
      '<i class="ti ti-loader-2" style="font-size:26px;display:block;margin-bottom:8px"></i>Хүсэлтүүдийг ачаалж байна…</div>';
    return;
  }

  var uid = me && me.uid;
  var inbox = uid ? reqWaitingFor(uid) : [];
  var mine = uid ? reqMine(uid) : [];
  var all = (REQ_ROWS || []).slice().sort(function (a, b) {
    var oa = reqOverdue(a), ob = reqOverdue(b);
    if (oa !== ob) return ob - oa;
    return String(b.at).localeCompare(String(a.at));
  });
  var admin = isAdmin() || isDeptHead();
  var stuck = all.filter(function (r) { return reqOverdue(r) > 0; });
  var run = all.filter(function (r) { return r.status === 'running'; });

  var card = function (n, label, color) {
    return '<div style="flex:1;min-width:104px;background:' + color + '0D;border:1.5px solid ' + color +
      '2E;border-radius:13px;padding:11px 13px">' +
      '<div style="font-size:24px;font-weight:900;color:' + color + ';line-height:1;font-family:\'Bricolage Grotesque\',sans-serif">' + n + '</div>' +
      '<div style="font-size:11.5px;font-weight:700;color:' + color + ';margin-top:3px">' + label + '</div></div>';
  };

  var H = '<div style="display:flex;align-items:center;gap:11px;flex-wrap:wrap;margin-bottom:13px">' +
    '<div><div style="font-size:15px;font-weight:800;color:#0F172A">Ажлын хувцас, хамгаалах хэрэгслийн хүсэлт</div>' +
    '<div style="font-size:12.5px;color:#8A94A6;margin-top:2px">Хүсэлт хаана, хэдэн өдөр болсныг бүгд хардаг. ' +
    'Хугацаа хэтэрвэл хоногт <b>1 оноо</b> (дээд тал ' + REQ_PEN_MAX + ') KPI-аас хасагдана.</div></div>' +
    (reqCanCreate()
      ? '<button class="btn btn-primary" data-req-new="1" style="margin-left:auto"><i class="ti ti-plus"></i> Шинэ хүсэлт</button>'
      : '') + '</div>';

  H += '<div style="display:flex;gap:9px;flex-wrap:wrap;margin-bottom:13px">' +
    card(inbox.length, 'миний шийдэх', inbox.length ? '#DC2626' : '#64748B') +
    card(run.length, 'явагдаж байна', '#2563EB') +
    card(stuck.length, 'хугацаа хэтэрсэн', stuck.length ? '#DC2626' : '#64748B') +
    card(all.filter(function (r) { return r.status === 'done'; }).length, 'батлагдсан', '#059669') +
    '</div>';

  /* ⭐ АВАХ ШААРДЛАГАТАЙ ХХХ — хүсэлт гараагүй байсан ч эндээс харагдана */
  try { H += reqNeedHTML(); } catch (e) { console.warn('[req] need', e && e.message); }

  /* ── Миний шийдэх (ирц) ── */
  if (inbox.length) {
    H += '<div class="card" style="padding:15px 17px;margin-bottom:13px;border:1.5px solid #FECACA;background:#FEF2F2">' +
      '<div style="font-size:14px;font-weight:800;color:#B91C1C;margin-bottom:3px">⚠ Таны шийдвэрийг хүлээж байна (' + inbox.length + ')</div>' +
      '<div style="font-size:12px;color:#B91C1C;margin-bottom:11px">Хугацаа хэтэрвэл таны KPI-аас хасагдана. Ажиллах боломжгүй бол <b>хугацаа сунгах</b> хүс.</div>' +
      inbox.map(function (r) { return reqRowHTML(r, false); }).join('') + '</div>';
  }

  /* ── Миний гаргасан ── */
  if (mine.length) {
    H += '<div class="card" style="padding:15px 17px;margin-bottom:13px">' +
      '<div style="font-size:14px;font-weight:800;color:#334155;margin-bottom:11px">Миний гаргасан хүсэлт (' + mine.length + ')</div>' +
      mine.slice(0, 25).map(function (r) { return reqRowHTML(r, true); }).join('') + '</div>';
  }

  /* ── Бүх хүсэлтийн самбар ── */
  if (admin || all.length) {
    var show = admin ? all : all.filter(function (r) {
      return r.byUid === uid || (r.steps || []).some(function (s) { return s.uid === uid; });
    });
    H += '<div class="card" style="padding:15px 17px">' +
      '<div style="font-size:14px;font-weight:800;color:#334155;margin-bottom:3px">' +
      (admin ? 'Бүх хүсэлт — самбар' : 'Холбогдох хүсэлтүүд') + ' (' + show.length + ')</div>' +
      '<div style="font-size:12px;color:#94A3B8;margin-bottom:11px">Хугацаа хэтэрсэн нь дээр гарна. Мөр дээр дарж дэлгэрэнгүйг үзнэ.</div>' +
      (show.length ? show.slice(0, 60).map(function (r) { return reqRowHTML(r, true); }).join('')
        : '<div class="empty-state" style="padding:26px"><i class="ti ti-inbox"></i><div>Хүсэлт бүртгэгдээгүй байна</div>' +
          (reqCanCreate() ? '<div style="font-size:12.5px;color:#94A3B8;margin-top:6px">«Шинэ хүсэлт» товчоор эхлүүлнэ үү.</div>' : '') +
          '</div>') +
      '</div>';
  }

  box.innerHTML = H;

  if (!box._reqWired) {
    box._reqWired = true;
    box.addEventListener('click', function (ev) {
      if (ev.target.closest('[data-req-new]')) { reqNewModal(); return; }
      var nb = ev.target.closest('[data-need-req]');
      if (nb) {
        var q = String(nb.getAttribute('data-need-req')).split('|');
        ppeOpenRequest(q[0], parseInt(q[1], 10));
        return;
      }
      var op = ev.target.closest('[data-req-open]');
      if (op) { reqDetailModal(op.getAttribute('data-req-open')); return; }
    });
  }
}

/* ── Шинэ хүсэлт гаргах цонх ── */
function reqNewModal(pre) {
  var me = reqMe();
  if (!me) { toast('Таны бүртгэл олдсонгүй', 'error'); return; }
  var sys = [];
  try { sys = deptList() || []; } catch (e) {}
  var route = reqDefaultRoute();

  var node = elc('div', 'modal-info');
  var stepRow = function (s, i) {
    var people = reqPersonOptions(s.dept);
    return '<div data-rq-row="' + i + '" style="display:flex;gap:8px;align-items:flex-end;flex-wrap:wrap;' +
      'padding:10px;border:1px solid #E2E8F0;border-radius:11px;margin-bottom:8px;background:#F8FAFC">' +
      '<div style="flex:0 0 22px;height:22px;border-radius:50%;background:#4F46E5;color:#fff;display:flex;' +
      'align-items:center;justify-content:center;font-size:11px;font-weight:900;margin-bottom:8px">' + (i + 1) + '</div>' +
      '<div style="flex:1;min-width:150px"><label style="font-size:11px;font-weight:700;color:#64748B;display:block;margin-bottom:3px">Алба</label>' +
      '<select data-rq-dept="' + i + '" class="rf-input" style="width:100%;padding:8px 10px;font-size:12.5px">' +
      '<option value="">— сонгох —</option>' +
      sys.map(function (d) { return '<option value="' + esc(d) + '"' + (d === s.dept ? ' selected' : '') + '>' + esc(d) + '</option>'; }).join('') +
      '</select></div>' +
      '<div style="flex:1;min-width:150px"><label style="font-size:11px;font-weight:700;color:#64748B;display:block;margin-bottom:3px">Албан тушаалтан</label>' +
      '<select data-rq-uid="' + i + '" class="rf-input" style="width:100%;padding:8px 10px;font-size:12.5px">' +
      '<option value="">— сонгох —</option>' +
      people.map(function (e) {
        return '<option value="' + esc(e.uid) + '"' + (e.uid === s.uid ? ' selected' : '') + '>' +
          esc(e.name || '') + (e.pos || e.role ? ' — ' + esc(e.pos || e.role) : '') + '</option>';
      }).join('') + '</select></div>' +
      '<div style="flex:0 0 92px"><label style="font-size:11px;font-weight:700;color:#64748B;display:block;margin-bottom:3px">Хоног</label>' +
      '<input type="number" data-rq-days="' + i + '" class="rf-input" min="' + REQ_MIN_DAYS + '" value="' +
      (s.days || REQ_MIN_DAYS) + '" style="width:100%;padding:8px 10px;font-size:12.5px"></div>' +
      '<button type="button" data-rq-del="' + i + '" class="btn btn-sm" style="flex-shrink:0;background:#FEE2E2;color:#991B1B;border-color:#FECACA;margin-bottom:1px"><i class="ti ti-trash"></i></button>' +
      '</div>';
  };

  var draw = function () {
    node.innerHTML =
      '<div class="rf-field"><label style="font-weight:700;font-size:13px">Юу авах вэ <span style="color:#DC2626">*</span></label>' +
      '<input type="text" id="rqTitle" class="rf-input" placeholder="Жишээ: Халуунд тэсвэртэй бээлий 40 ширхэг" value="' + esc((pre && pre.title) || '') + '"></div>' +
      '<div class="rf-field" style="margin-top:10px"><label style="font-weight:700;font-size:13px">Дэлгэрэнгүй (төрөл, хэмжээ, тоо ширхэг)</label>' +
      '<textarea id="rqItems" class="rf-input" rows="3" placeholder="Жишээ: 9 размер 20ш, 10 размер 20ш. Стандарт: EN388">' + esc((pre && pre.items) || '') + '</textarea></div>' +
      '<div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:10px">' +
      '<div class="rf-field" style="flex:1;min-width:150px"><label style="font-weight:700;font-size:13px">Хэнд зориулж</label>' +
      '<input type="text" id="rqFor" class="rf-input" placeholder="Жишээ: Пет шугамын 12 ажилтан" value="' + esc((pre && pre.forWho) || '') + '"></div>' +
      '<div class="rf-field" style="flex:0 0 150px"><label style="font-weight:700;font-size:13px">Нийт үнэ (₮)</label>' +
      '<input type="number" id="rqSum" class="rf-input" placeholder="0" min="0"></div></div>' +
      '<div class="rf-field" style="margin-top:10px"><label style="font-weight:700;font-size:13px">Үндэслэл</label>' +
      '<textarea id="rqReason" class="rf-input" rows="2" placeholder="Аль эрсдэлээс үүдэлтэй, яагаад яаралтай вэ">' + esc((pre && pre.reason) || '') + '</textarea></div>' +
      (pre && pre.riskHazard
        ? '<div style="background:#EEF2FF;border:1px solid #C7D2FE;border-radius:10px;padding:9px 12px;margin-top:9px;font-size:12px;color:#3730A3;line-height:1.55">' +
          '<b>Эрсдэлээс:</b> ' + esc(pre.riskHazard) + (pre.measure ? '<br><b>Арга хэмжээ:</b> ' + esc(pre.measure) : '') + '</div>'
        : '') +
      '<div style="margin-top:16px;padding-top:13px;border-top:1px solid #F1F5F9">' +
      '<div style="font-size:13.5px;font-weight:800;color:#334155;margin-bottom:3px">Батлах маршрут</div>' +
      '<div style="font-size:12px;color:#8A94A6;margin-bottom:10px">Шат бүрд <b>алба, албан тушаалтан, хугацааг</b> та өөрөө сонгоно. ' +
      'Доод хугацаа ' + REQ_MIN_DAYS + ' ажлын өдөр. Хэтэрвэл тухайн хүний KPI-аас хасагдана.</div>' +
      route.map(stepRow).join('') +
      '<button type="button" class="btn btn-secondary btn-sm" id="rqAdd"><i class="ti ti-plus"></i> Шат нэмэх</button></div>' +
      '<button class="btn btn-primary btn-block" id="rqSend" style="margin-top:15px"><i class="ti ti-send"></i> Хүсэлт илгээх</button>' +
      '<div id="rqSt" style="margin-top:9px;font-size:12.5px;line-height:1.6"></div>';

    /* Алба солиход хүний жагсаалт шинэчлэгдэнэ */
    node.querySelectorAll('[data-rq-dept]').forEach(function (sel) {
      sel.addEventListener('change', function () {
        var i = +sel.getAttribute('data-rq-dept');
        route[i].dept = sel.value; route[i].uid = '';
        sync(); draw();
      });
    });
    node.querySelectorAll('[data-rq-del]').forEach(function (b) {
      b.addEventListener('click', function () {
        var i = +b.getAttribute('data-rq-del');
        sync(); route.splice(i, 1); draw();
      });
    });
    var addBtn = node.querySelector('#rqAdd');
    if (addBtn) addBtn.addEventListener('click', function () { sync(); route.push({ dept: '', days: REQ_MIN_DAYS }); draw(); });
    var sendBtn = node.querySelector('#rqSend');
    if (sendBtn) sendBtn.addEventListener('click', send);
  };

  var form = { title: '', items: '', forWho: '', sum: '', reason: '' };
  var sync = function () {
    var g = function (id) { var el = node.querySelector('#' + id); return el ? el.value : ''; };
    form.title = g('rqTitle') || form.title; form.items = g('rqItems') || form.items;
    form.forWho = g('rqFor') || form.forWho; form.sum = g('rqSum') || form.sum;
    form.reason = g('rqReason') || form.reason;
    node.querySelectorAll('[data-rq-row]').forEach(function (row) {
      var i = +row.getAttribute('data-rq-row');
      if (!route[i]) return;
      var d = row.querySelector('[data-rq-uid]'), dd = row.querySelector('[data-rq-dept]'),
          dy = row.querySelector('[data-rq-days]');
      if (dd) route[i].dept = dd.value;
      if (d) {
        route[i].uid = d.value;
        var e = (DB.employees || []).filter(function (x) { return x.uid === d.value; })[0];
        route[i].name = e ? (e.name || '') : ''; route[i].pos = e ? (e.pos || e.role || '') : '';
      }
      if (dy) route[i].days = Math.max(REQ_MIN_DAYS, parseInt(dy.value, 10) || REQ_MIN_DAYS);
    });
  };

  var send = function () {
    sync();
    var st = node.querySelector('#rqSt');
    var say = function (h, c) { st.innerHTML = '<span style="color:' + (c || '#64748B') + '">' + h + '</span>'; };
    if (!form.title.trim()) { say('⚠️ «Юу авах вэ» талбарыг бөглөнө үү', '#B91C1C'); return; }
    var steps = route.filter(function (s) { return s.uid; });
    if (!steps.length) { say('⚠️ Дор хаяж нэг батлах албан тушаалтан сонгоно уу', '#B91C1C'); return; }
    var btn = node.querySelector('#rqSend');
    btn.disabled = true; btn.innerHTML = '<i class="ti ti-loader-2"></i> Илгээж байна…';
    reqCreate({
      title: form.title.trim(), items: form.items.trim(), forWho: form.forWho.trim(),
      sum: form.sum, reason: form.reason.trim(),
      riskId: (pre && pre.riskId) || '', riskHazard: (pre && pre.riskHazard) || '',
      measure: (pre && pre.measure) || '', steps: steps
    }).then(function () {
      closeModal();
      toast('Хүсэлт илгээгдлээ — ' + esc(steps[0].name) + ' дээр очлоо', 'success');
      renderHazards();
    }).catch(function (e) {
      btn.disabled = false; btn.innerHTML = '<i class="ti ti-send"></i> Хүсэлт илгээх';
      say('⚠️ ' + esc((e && e.message) || 'Алдаа'), '#B91C1C');
    });
  };

  draw();
  buildModal('Ажлын хувцас / хамгаалах хэрэгслийн хүсэлт', node, { width: 'min(760px, 96vw)' });
}

/* ── Хүсэлтийн дэлгэрэнгүй + үйлдэл ── */
function reqDetailModal(id) {
  var r = (REQ_ROWS || []).filter(function (x) { return x && x.id === id; })[0];
  if (!r) { toast('Хүсэлт олдсонгүй', 'error'); return; }
  var me = reqMe();
  var s = reqStep(r), over = reqOverdue(r);
  var mine = me && s && s.uid === me.uid && r.status === 'running';
  var S = REQ_ST[r.status] || REQ_ST.running;

  var node = elc('div', 'modal-info');
  var H = '<div style="background:' + S.bg + ';border:1.5px solid ' + S.c + '3D;border-radius:13px;padding:14px 16px;margin-bottom:13px">' +
    '<div style="font-size:16px;font-weight:800;color:#0F172A;line-height:1.4">' + esc(r.title || '—') + '</div>' +
    '<div style="font-size:12px;color:#64748B;margin-top:5px">' + esc(r.id) + ' · ' +
    esc(r.byName || '') + ' (' + esc(r.byDept || '') + ') · ' + ackDateMn(r.at) + '</div>' +
    '<div style="margin-top:9px"><span style="background:' + S.c + ';color:#fff;border-radius:7px;padding:3px 11px;font-size:12px;font-weight:800">' + S.t + '</span>' +
    (over > 0 ? '<span style="margin-left:8px;color:#B91C1C;font-size:12.5px;font-weight:800">⚠ ' + over +
      ' ажлын өдөр хэтэрсэн · ' + esc(s.name || '') + '-ийн KPI-аас −' + reqPenalty(r) + ' оноо</span>' : '') +
    '</div></div>';

  var fact = function (l, v) {
    if (!v) return '';
    return '<div style="display:flex;gap:11px;padding:9px 0;border-bottom:1px solid #F1F5F9">' +
      '<span style="flex:0 0 118px;font-size:11.5px;font-weight:800;color:#94A3B8;letter-spacing:.3px">' + l + '</span>' +
      '<span style="flex:1;min-width:0;font-size:13px;color:#1E293B;line-height:1.6;white-space:pre-wrap">' + esc(String(v)) + '</span></div>';
  };
  H += '<div class="card" style="padding:13px 16px;margin-bottom:13px">' +
    fact('ДЭЛГЭРЭНГҮЙ', r.items) + fact('ХЭНД ЗОРИУЛЖ', r.forWho) +
    fact('ҮНДЭСЛЭЛ', r.reason) + fact('ЭРСДЭЛ', r.riskHazard) + fact('АРГА ХЭМЖЭЭ', r.measure) +
    (r.sum ? fact('НИЙТ ҮНЭ', Number(r.sum).toLocaleString() + ' ₮') : '') + '</div>';

  /* Маршрутын мөр */
  H += '<div class="card" style="padding:13px 16px;margin-bottom:13px">' +
    '<div style="font-size:13px;font-weight:800;color:#334155;margin-bottom:10px">Батлалтын явц</div>' +
    (r.steps || []).map(function (x, i) {
      var cur = (i === r.step && r.status === 'running');
      var col = x.status === 'ok' ? '#059669' : x.status === 'back' ? '#DC2626'
        : cur ? (over > 0 ? '#DC2626' : '#2563EB') : '#CBD5E1';
      var late = x.status === 'ok' ? (x.lateDays || 0) : (cur ? over : 0);
      return '<div style="display:flex;gap:11px;padding:9px 0;' + (i ? 'border-top:1px solid #F8FAFC' : '') + '">' +
        '<span style="flex:0 0 24px;height:24px;border-radius:50%;background:' + col + ';color:#fff;display:flex;' +
        'align-items:center;justify-content:center;font-size:11px;font-weight:900">' +
        (x.status === 'ok' ? '✓' : x.status === 'back' ? '↩' : (i + 1)) + '</span>' +
        '<span style="flex:1;min-width:0">' +
        '<span style="display:block;font-size:13px;font-weight:700;color:#1E293B">' + esc(x.name || '—') +
        '<span style="font-weight:500;color:#94A3B8"> · ' + esc(x.pos || x.dept || '') + '</span></span>' +
        '<span style="display:block;font-size:11.5px;color:' + (late > 0 ? '#B91C1C' : '#94A3B8') + ';margin-top:2px">' +
        (x.status === 'ok' ? '✓ ' + ackDateMn(x.at) + ' баталсан' + (late > 0 ? ' (' + late + ' өдөр хоцорсон)' : '')
          : x.status === 'back' ? '↩ ' + ackDateMn(x.at) + ' буцаасан'
          : cur ? (over > 0 ? '⚠ ' + over + ' ажлын өдөр хэтэрсэн' : 'Хүлээгдэж байна · ' + x.days + ' хоногийн хугацаатай')
          : 'Ээлж хүлээж байна') +
        (x.ext ? ' · ' + x.ext + ' хоногоор сунгасан' : '') + '</span>' +
        (x.note ? '<span style="display:block;font-size:12px;color:#475569;margin-top:4px;background:#F8FAFC;' +
          'border-radius:8px;padding:6px 9px;line-height:1.55">' + esc(x.note) + '</span>' : '') +
        '</span></div>';
    }).join('') + '</div>';

  /* Үйлдлүүд */
  if (mine) {
    H += '<div class="card" style="padding:13px 16px;margin-bottom:13px;border:1.5px solid #DBEAFE">' +
      '<div style="font-size:13px;font-weight:800;color:#1E40AF;margin-bottom:8px">Таны шийдвэр</div>' +
      '<textarea id="rqNote" class="rf-input" rows="2" placeholder="Тайлбар (буцаах бол ЗААВАЛ бичнэ)"></textarea>' +
      '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px">' +
      '<button class="btn btn-primary" data-rq-act="ok" style="flex:1;min-width:130px"><i class="ti ti-check"></i> Батлах</button>' +
      '<button class="btn" data-rq-act="back" style="flex:1;min-width:130px;background:#FEE2E2;color:#991B1B;border-color:#FECACA"><i class="ti ti-arrow-back-up"></i> Буцаах</button>' +
      (s && !s.ext ? '<button class="btn btn-secondary" data-rq-act="ext" style="flex-shrink:0"><i class="ti ti-clock-plus"></i> Хугацаа сунгах</button>' : '') +
      '</div></div>';
  }
  if (r.status === 'returned' && me && r.byUid === me.uid) {
    H += '<div class="card" style="padding:13px 16px;margin-bottom:13px;border:1.5px solid #FECACA">' +
      '<div style="font-size:13px;color:#B91C1C;line-height:1.6;margin-bottom:9px">Хүсэлт буцаагдсан. Тайлбарыг уншаад засаад дахин илгээнэ үү.</div>' +
      '<button class="btn btn-primary" data-rq-act="resend"><i class="ti ti-send"></i> Дахин илгээх</button></div>';
  }
  if (reqCanCancel(r) && (r.status === 'running' || r.status === 'returned')) {
    H += '<button class="btn btn-secondary btn-sm" data-rq-act="cancel" style="width:100%;margin-bottom:12px">Хүсэлтийг цуцлах</button>';
  }

  /* Түүх */
  H += '<details class="card" style="padding:12px 15px">' +
    '<summary style="cursor:pointer;list-style:none;display:flex;align-items:center;gap:8px;font-size:12.5px;font-weight:700;color:#64748B">' +
    '<i class="ti ti-chevron-right" style="font-size:14px"></i>Түүх (' + ((r.log || []).length) + ')</summary>' +
    '<div style="margin-top:9px">' + (r.log || []).map(function (l) {
      return '<div style="font-size:12px;color:#64748B;padding:5px 0;border-top:1px solid #F8FAFC;line-height:1.5">' +
        '<b style="color:#334155">' + esc(l.name || '') + '</b> — ' + esc(l.what || '') +
        '<span style="color:#CBD5E1"> · ' + ackDateMn(l.at) + '</span>' +
        (l.note ? '<br><span style="color:#475569">' + esc(l.note) + '</span>' : '') + '</div>';
    }).join('') + '</div></details>';

  node.innerHTML = H;
  node.addEventListener('click', function (ev) {
    var b = ev.target.closest('[data-rq-act]');
    if (!b) return;
    var kind = b.getAttribute('data-rq-act');
    var nt = node.querySelector('#rqNote');
    var note = nt ? nt.value.trim() : '';
    if (kind === 'back' && !note) { toast('Буцаах шалтгаанаа бичнэ үү', 'warn'); return; }
    var ext = 0;
    if (kind === 'ext') {
      var v = prompt('Хэдэн ажлын өдрөөр сунгах вэ? (1–14)', '3');
      ext = Math.max(1, Math.min(14, parseInt(v, 10) || 0));
      if (!ext) return;
      if (!note) { toast('Сунгах шалтгаанаа тайлбар талбарт бичнэ үү', 'warn'); return; }
    }
    if (kind === 'cancel' && !confirm('Энэ хүсэлтийг цуцлах уу?')) return;
    var old = b.innerHTML; b.disabled = true; b.innerHTML = '<i class="ti ti-loader-2"></i>';
    reqAct(r.id, kind, note, ext).then(function () {
      closeModal();
      toast(kind === 'ok' ? 'Баталлаа ✓' : kind === 'back' ? 'Буцаалаа'
        : kind === 'ext' ? 'Хугацаа сунгагдлаа' : kind === 'resend' ? 'Дахин илгээлээ' : 'Цуцаллаа',
        kind === 'back' ? 'warn' : 'success');
      renderHazards();
    }).catch(function (e) {
      b.disabled = false; b.innerHTML = old;
      toast((e && e.message) || 'Алдаа гарлаа', 'error');
    });
  });
  buildModal('Хүсэлтийн дэлгэрэнгүй', node, { width: 'min(720px, 96vw)' });
}



/* ══════════════════════════════════════════════════════════════════════
   🔔 МЭДЭГДЭЛ — арга хэмжээ хэрэгжүүлмэгц УДИРДЛАГАД нь очно
   ----------------------------------------------------------------------
   Ажилтан арга хэмжээгээ баримтжуулмагц:
     · «Хэн хяналт тавих» баганын ХЯНАГЧ нарт
     · тухайн ажилтны МЕНЕЖЕР, АЛБАНЫ ХАРИУЦАГЧ-д
   мэдэгдэл очно. Хонхон дээр тоолуур гарч, дарвал жагсаалт нээгдэнэ.
   Push тохируулагдсан бол утсанд нь ч шууд очно.
   ══════════════════════════════════════════════════════════════════════ */
var NTF_FILE = 'notify/_all.json';
var NTF_ROWS = null, NTF_OK = false;

async function ntfLoad(force) {
  if (NTF_OK && !force) return NTF_ROWS;
  try {
    var j = await riskR2GetJson(NTF_FILE);
    NTF_ROWS = (j && Array.isArray(j.list)) ? j.list : [];
    NTF_OK = true;
  } catch (e) { NTF_ROWS = NTF_ROWS || []; }
  return NTF_ROWS;
}
async function ntfSaveMerge(mutate) {
  for (var k = 0; k < 3; k++) {
    var cur = [];
    try { var j = await riskR2GetJson(NTF_FILE); cur = (j && Array.isArray(j.list)) ? j.list : []; } catch (e) {}
    var next = mutate(cur.slice());
    if (!next) return true;
    /* Сүүлийн 400-г л хадгална — файл хэт томрохгүй */
    next = next.slice(-400);
    try { await riskR2PutJson(NTF_FILE, { updatedAt: new Date().toISOString(), list: next }); }
    catch (e) { if (k === 2) return false; continue; }
    NTF_ROWS = next; NTF_OK = true;
    return true;
  }
  return false;
}

/* Тухайн ажилтны ШУУД УДИРДЛАГА — менежер ба албаны хариуцагч.
   ⚠ Танилцалтын дараалалтай ЯГ ижил логик (ackSubordinates)-ыг ашиглана. */
function ackBossesOf(emp) {
  var out = [];
  if (!emp || !emp.uid) return out;
  try {
    (DB.employees || []).forEach(function (b) {
      if (!b.uid || b.uid === emp.uid) return;
      var role = ackRoleOf(b);
      if (role !== 'mgr' && role !== 'lead') return;
      if (!riskSameDept(b.dept, emp.dept)) return;
      if (ackSubordinates(b).some(function (x) { return x.uid === emp.uid; })) out.push(b);
    });
  } catch (e) {}
  return out;
}

/* Мэдэгдэл илгээх (R2-д бичих + боломжтой бол push) */
async function ntfSend(toList, info) {
  var uids = {}, names = [];
  (toList || []).forEach(function (e) {
    if (e && e.uid && !uids[e.uid]) { uids[e.uid] = 1; names.push(e.name || ''); }
  });
  var to = Object.keys(uids);
  if (!to.length) return false;
  var me = reqMe();
  var rec = {
    id: 'N-' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6),
    at: new Date().toISOString(), to: to,
    byUid: (me && me.uid) || '', byName: (me && me.name) || '',
    kind: info.kind || 'mea', title: info.title || '', body: info.body || '',
    url: info.url || '/kpi/?page=hazards', riskId: info.riskId || '', read: {}
  };
  var ok = await ntfSaveMerge(function (list) { return list.concat([rec]); });
  /* Push — тохируулагдсан бол шууд утсанд нь */
  try {
    if (typeof fauth !== 'undefined' && fauth && fauth.currentUser) {
      var idToken = await fauth.currentUser.getIdToken();
      fetch('/api/push-now/', {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ idToken: idToken, to: to, title: rec.title, body: rec.body, url: rec.url })
      }).catch(function () {});
    }
  } catch (e) {}
  return ok;
}

function ntfMine(uid) {
  return (NTF_ROWS || []).filter(function (x) { return x && (x.to || []).indexOf(uid) >= 0; })
    .sort(function (a, b) { return String(b.at).localeCompare(String(a.at)); });
}
function ntfUnread(uid) {
  return ntfMine(uid).filter(function (x) { return !(x.read || {})[uid]; }).length;
}
async function ntfMarkRead(uid) {
  return await ntfSaveMerge(function (list) {
    var ch = false;
    list.forEach(function (x) {
      if (x && (x.to || []).indexOf(uid) >= 0 && !(x.read || {})[uid]) {
        x.read = x.read || {}; x.read[uid] = new Date().toISOString(); ch = true;
      }
    });
    return ch ? list : null;
  });
}

/* Хонхны тоолуур */
function ntfBadgeRefresh() {
  try {
    var me = reqMe(); if (!me || !me.uid) return;
    var n = ntfUnread(me.uid);
    var dot = document.querySelector('.icon-btn.notif .notif-dot');
    if (dot) {
      dot.textContent = n > 9 ? '9+' : (n || '');
      dot.style.display = n ? 'flex' : 'none';
      dot.style.cssText += ';align-items:center;justify-content:center;font-size:9.5px;font-weight:900;color:#fff';
    }
  } catch (e) {}
}
function ntfWireOnce() {
  if (ntfWireOnce._done) return;
  ntfWireOnce._done = true;
  /* ⚠ Хонхны товчийг ХУУЧИН зохицуулагч (openNotifications) барьдаг —
     тэр нь stopPropagation дууддаг тул энд дахин холбохгүй. Оронд нь
     R2-ийн мэдэгдлийг ТЭР САМБАР дотор нэмж харуулна. */
  if (!NTF_OK && !ntfWireOnce._busy) {
    ntfWireOnce._busy = true;
    ntfLoad().then(function () {
      ntfWireOnce._busy = false;
      try { renderNotifBadge(); } catch (e) { ntfBadgeRefresh(); }
    }).catch(function () { ntfWireOnce._busy = false; });
  }
}

function ntfModal() {
  var me = reqMe();
  if (!me) { toast('Таны бүртгэл олдсонгүй', 'error'); return; }
  var list = ntfMine(me.uid);
  var node = elc('div', 'modal-info');
  node.innerHTML = list.length
    ? list.slice(0, 60).map(function (x) {
        var isNew = !(x.read || {})[me.uid];
        return '<div style="display:flex;gap:11px;padding:11px 12px;border:1px solid ' +
          (isNew ? '#C7D2FE' : '#F1F5F9') + ';border-radius:12px;margin-bottom:8px;background:' +
          (isNew ? '#EEF2FF' : '#fff') + '">' +
          '<span style="flex:0 0 24px;font-size:17px;line-height:1.3">' +
          (x.kind === 'mea' ? '✅' : x.kind === 'req' ? '📨' : '🔔') + '</span>' +
          '<span style="flex:1;min-width:0">' +
          '<span style="display:block;font-size:13px;font-weight:700;color:#1E293B;line-height:1.45">' +
          esc(x.title || '') + '</span>' +
          (x.body ? '<span style="display:block;font-size:12px;color:#64748B;margin-top:3px;line-height:1.5">' +
            esc(x.body) + '</span>' : '') +
          '<span style="display:block;font-size:11px;color:#94A3B8;margin-top:4px">' +
          ackDateMn(x.at) + (x.byName ? ' · ' + esc(x.byName) : '') + '</span></span>' +
          (isNew ? '<span style="flex:0 0 8px;height:8px;border-radius:50%;background:#4F46E5;margin-top:6px"></span>' : '') +
          '</div>';
      }).join('')
    : '<div class="empty-state" style="padding:32px"><i class="ti ti-bell-off"></i><div>Мэдэгдэл алга байна</div></div>';
  buildModal('Мэдэгдэл', node, { width: 'min(560px, 96vw)' });
  if (list.some(function (x) { return !(x.read || {})[me.uid]; })) {
    ntfMarkRead(me.uid).then(ntfBadgeRefresh).catch(function () {});
  }
}

/* ══════════════════════════════════════════════════════════════════════
   👥 «АЖИЛТНУУДЫН БАЙДАЛ» ТАБ — менежер, албаны хариуцагчид
   ----------------------------------------------------------------------
   Хариуцах хэсгийн ажилтан бүрийн эрсдэлийн үнэлгээний БҮХ дата:
   хэдэн эрсдэлтэй, түвшин нь ямар, танилцсан эсэх, ямар санал өгсөн,
   арга хэмжээ нь хаана байгаа — нэг дор, нэг бүрчлэн.
   ══════════════════════════════════════════════════════════════════════ */
var PPL_OPEN = {};        // задалсан ажилтнууд
var PPL_ALL = false;      // бүгдийг зурах уу (анхдагчаар эхний 60)
var PPL_ACK = null;       // тухайн албаны танилцалтын сан

/* ⚡ Эрсдлийн жагсаалт нь ажилтан бүрд 887 мөр шүүдэг тул КЭШЛЭНЭ */
var PPL_CACHE = {}, PPL_DEEP = {};
function pplRowsOf(e) {
  if (PPL_CACHE[e.uid]) return PPL_CACHE[e.uid];
  var seen = { rows: [] };
  try { seen = riskSeenBy(e); } catch (er) {}
  var rows = [];
  try { rows = riskEmpMerged(seen.rows || []); } catch (er) { rows = seen.rows || []; }
  PPL_CACHE[e.uid] = rows;
  return rows;
}
/* deep=true үед л арга хэмжээ, дүрэм, санал тооцно (хүнд).
   ⚠ meaMineStats нь эрсдэл бүрийн арга хэмжээг задалж, хариуцагчийг
   тооцдог тул 267 ажилтанд зэрэг ажиллуулбал хөтөч ХӨЛДӨНӨ. */
/* ⭐ МИНИЙ ХЯНАХ ХҮМҮҮС — таб ба хуудас ХОЁУЛАН үүнийг ашиглана.
   · менежер/хариуцагч → өөрийн ажилтнууд
   · Үйлдвэрлэл хариуцсан захирал → 5 албаны ХАРИУЦАГЧ нар
   · Гүйцэтгэх захирал → БҮХ хариуцагч нар
   · админ → бүх ажилтан */
function pplMyPeople() {
  var me = null; try { me = myEmp(); } catch (e) {}
  var dsc = '';
  try { dsc = riskDirScope(); } catch (e) {}
  if (dsc) {
    /* Захирал — хариуцагч нарыг хянана */
      var want = (dsc === 'prod') ? riskDirDepts() : null;
    var out = [];
    (DB.employees || []).forEach(function (x) {
      if (!x.uid || (me && x.uid === me.uid)) return;
      var r = ''; try { r = ackRoleOf(x); } catch (e) { return; }
      if (r !== 'lead') return;
      if (want && !want.some(function (d) { return riskSameDept(d, x.dept); })) return;
      out.push(x);
    });
    return out;
  }
  if (isAdmin() || isDeptHead()) {
    var d0 = (me && me.dept) || (SESSION && SESSION.dept) || '';
    var lst = [];
    try { lst = ackDueEmps(d0); } catch (e) {}
    if (!lst || !lst.length) { try { lst = (DB.employees || []).filter(function (x) { return x.uid; }); } catch (e) { lst = []; } }
    return lst;
  }
  try { return ackSubordinates(me) || []; } catch (e) { return []; }
}

function pplEmpStat(e, deep) {
  var seen = { rows: [] };
  try { seen = riskSeenBy(e); } catch (er) {}
  var rows = pplRowsOf(e);
  /* ⚠ Өмнө нь E түвшин байхгүй байсан тул 3 эрсдэл тоонд ОРОХГҮЙ,
     задаргаа нийт тоотой таарахгүй байв. */
  var lv = { A: 0, B: 0, C: 0, D: 0, E: 0, un: 0 }, top = 0;
  rows.forEach(function (r) {
    if (riskIsUnscored(r)) { lv.un++; return; }
    var c = riskLevel(r).code;
    if (lv[c] != null) lv[c]++; else lv.un++;
    var s = riskScore(r); if (s > top) top = s;
  });
  var ver = '';
  try { ver = ackVersionOf(riskCanonDept(e.dept) || e.dept || ''); } catch (er) {}
  var row = null, prev = null;
  try {
    row = ackSignedRow(PPL_ACK, e.uid, ver);
    prev = ackLatestRow(PPL_ACK, e.uid);
  } catch (er) {}
  var rd = { done: 0, total: rows.length, ok: false };
  try { if (e.uid === (myEmp() || {}).uid) rd = ackReadStat(rows, ver); } catch (er) {}
  /* ⚡ meaMineStats нь эрсдэл бүрийн арга хэмжээг задалж, хариуцагчийг 267
     ажилтнаас хайдаг тул МАШ ХҮНД. Хүн тус бүрээр нэг л удаа бодож кэшлэнэ —
     эс бөгөөс хуудас дахин зурагдах бүрд дахин бодож САЙТ ГАЦНА. */
  var mst = { total: 0, done: 0, late: 0, soon: 0 }, rules = 0;
  if (deep) {
    if (PPL_DEEP[e.uid]) { mst = PPL_DEEP[e.uid].mst; rules = PPL_DEEP[e.uid].rules; }
    else {
      try { mst = meaMineStats(e); rules = meaMyRules(e).length; } catch (er) {}
      PPL_DEEP[e.uid] = { mst: mst, rules: rules };
    }
  }
  /* БАГИЙН ЯВЦ — энэ хүн өөрөө хариуцагч/менежер бол баг нь хэдэн хувь зурсан бэ */
  var team = null;
  try {
    var rl = ackRoleOf(e);
    if (rl === 'lead' || rl === 'mgr') {
      var tm = ackSubordinates(e) || [];
      if (tm.length) {
        var tv = ackVersionOf(riskCanonDept(e.dept) || e.dept || '');
        var dn = 0;
        tm.forEach(function (t) { if (ackSignedRow(PPL_ACK, t.uid, tv)) dn++; });
        team = { n: tm.length, done: dn };
      }
    }
  } catch (er) {}

  return { e: e, rows: rows, lv: lv, top: top, ver: ver, row: row, prev: prev, rd: rd,
    mst: mst, rules: rules, deep: !!deep, scope: seen.scope || 'none', team: team,
    ideas: (row && row.ideas) || (prev && prev.ideas) || [] };
}

function pplRowHTML(st) {
  var e = st.e, L = riskLevel(st.top);
  var open = !!PPL_OPEN[e.uid];
  var sig = st.row ? 'ok' : (st.prev ? 'old' : 'no');
  var sigCol = sig === 'ok' ? '#059669' : sig === 'old' ? '#D97706' : '#94A3B8';
  var sigTxt = sig === 'ok' ? '✓ ' + ackDateMn(st.row.at)
    : sig === 'old' ? 'Хуучин хувилбарт зурсан' : 'Зураагүй';

  /* ⚠ Өмнө нь чипс хоорондоо наалдаж «91871» гэсэн утгагүй тоо болдог байв.
     Одоо түвшний ҮСЭГ + тоо, хооронд нь зайтай. */
  var chip = function (code, n, c, bg, t) {
    if (!n) return '';
    return '<span title="' + t + ': ' + n + '" style="display:inline-block;background:' + bg + ';color:' + c +
      ';border-radius:6px;padding:1px 6px;font-size:10.5px;font-weight:800;margin:0 3px 2px 0;' +
      'white-space:nowrap">' + code + '&#8201;' + n + '</span>';
  };

  var H = '<div style="border:1px solid ' + (open ? '#C7D2FE' : '#E2E8F0') + ';border-radius:12px;' +
    'margin-bottom:8px;background:#fff;overflow:hidden">' +
    '<div data-ppl-open="' + esc(e.uid) + '" style="display:flex;align-items:center;gap:11px;' +
    'padding:11px 13px;cursor:pointer">' +
    '<span style="flex:0 0 30px;height:30px;border-radius:50%;background:#EEF2FF;color:#4F46E5;' +
    'display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800">' +
    esc(String(e.name || '?').charAt(0)) + '</span>' +
    '<span style="flex:1;min-width:0">' +
    '<span style="display:block;font-size:13.5px;font-weight:700;color:#1E293B">' + esc(e.name || '—') + '</span>' +
    '<span style="display:block;font-size:11.5px;color:#94A3B8">' + esc(e.pos || e.role || '—') + '</span></span>' +
    '<span class="rk-hide-sm" style="flex:0 0 168px;text-align:left;line-height:1.5">' +
    /* ⚠ Энд «Онцгой/Өндөр/Ач холбогдол бага» гэсэн ГУРАВ ДАХЬ нэршил бичигдсэн
       байв. Нэрийг зөвхөн RISK_LEVELS-ээс авна — бүх дэлгэц дээр ижил болно. */
    RISK_LEVELS.slice().reverse().map(function (L) {
      return chip(L.code, st.lv[L.code], L.color, L.bg, L.name);
    }).join('') +
    chip('—', st.lv.un, RISK_LEVEL_NONE.color, RISK_LEVEL_NONE.bg, 'Үнэлгээгүй') + '</span>' +
    '<span style="flex:0 0 96px;text-align:center">' +
    '<span style="font-size:17px;font-weight:900;color:#334155;font-family:\'Bricolage Grotesque\',sans-serif">' +
    st.rows.length + '</span>' +
    '<span style="display:block;font-size:9.5px;color:' + (st.scope === 'pos' ? '#94A3B8' : '#B45309') +
    ';font-weight:' + (st.scope === 'pos' ? '600' : '800') + '">' +
    (st.scope === 'pos' ? 'ажлын байрных' : st.scope === 'none' ? 'эрсдэлгүй' : '⚠ албаных') +
    '</span></span>' +
    '<span style="flex:0 0 128px;text-align:right">' +
    '<span style="display:block;font-size:11.5px;font-weight:700;color:' + sigCol + '">' + sigTxt + '</span>' +
    (st.team
      ? '<span style="display:block;font-size:10.5px;font-weight:700;margin-top:2px;color:' +
        (st.team.done >= st.team.n ? '#059669' : '#B45309') + '">баг ' +
        st.team.done + '/' + st.team.n + '</span>'
      : '') + '</span>' +
    '<i class="ti ti-chevron-' + (open ? 'up' : 'down') + '" style="flex:0 0 18px;color:#CBD5E1"></i></div>';

  /* ⭐ ХЯНАГЧИЙН ҮЙЛДЭЛ — гүйцэтгээгүй хүнийг шахна.
     Хариуцагч эрсдэл тус бүр дээр ажиллахгүй — ХЯНАНА. */
  var need = [];
  if (!st.row) need.push('гарын үсэг зураагүй');
  if (st.deep && st.mst.late) need.push(st.mst.late + ' хугацаа хэтэрсэн');
  if (st.scope !== 'pos' && st.scope !== 'none') need.push('ажлын байрны үнэлгээгүй');
  if (need.length) {
    H += '<div style="display:flex;align-items:center;gap:9px;flex-wrap:wrap;padding:0 13px 11px">' +
      '<span style="font-size:11.5px;color:#B45309;font-weight:700">⚠ ' + need.join(' · ') + '</span>' +
      (!st.row
        ? '<button class="btn btn-sm" data-ppl-poke="' + esc(e.uid) + '" style="margin-left:auto;' +
          'background:#EEF2FF;color:#4338CA;border:1px solid #C7D2FE"><i class="ti ti-bell"></i> Сануулах</button>'
        : '') + '</div>';
  }

  if (!open) return H + '</div>';
  /* Задалсан үед л арга хэмжээ, дүрмийг тооцно (хурдны төлөө) */
  if (!st.deep) { try { st = pplEmpStat(e, true); } catch (er) {} }

  /* ── Задалсан: нарийвчилсан дата ── */
  var fact = function (l, v, c) {
    return '<div style="display:flex;gap:10px;padding:7px 0;border-bottom:1px solid #F8FAFC">' +
      '<span style="flex:0 0 148px;font-size:11.5px;font-weight:800;color:#94A3B8;letter-spacing:.3px">' + l + '</span>' +
      '<span style="flex:1;min-width:0;font-size:12.5px;color:' + (c || '#1E293B') + ';line-height:1.55">' + v + '</span></div>';
  };
  var mea = st.mst;
  H += '<div style="padding:2px 15px 14px;border-top:1px solid #F1F5F9;background:#FCFDFF">' +
    fact('ХАРЬЯА', esc(e.dept || '—') + (function () {
      var s = ''; try { s = ackSecOf(e); } catch (er) {}
      return s ? ' · <b>' + esc(s) + '</b>' : '';
    })()) +
    fact('ЭРСДЭЛ', st.rows.length + ' ширхэг · хамгийн өндөр <b style="color:' + L.color + '">' +
      (st.top || '—') + (st.top ? ' (' + L.code + ' · ' + L.name + ')' : '') + '</b>' +
      (st.scope === 'pos'
        ? '<br><span style="font-size:11.5px;color:#059669">✓ Энэ хүний ажлын байрны үнэлгээ хийгдсэн</span>'
        : st.scope === 'none'
          ? '<br><span style="font-size:11.5px;color:#94A3B8">Эрсдэл олдсонгүй</span>'
          : '<br><span style="font-size:11.5px;color:#B45309">⚠ Энэ ажлын байрны үнэлгээ ХИЙГДЭЭГҮЙ тул ' +
            'албаны эрсдлийг түр харуулж байна. Үнэлгээ хийгдмэгц зөвхөн өөрийнх нь эрсдэл гарна.</span>')) +
    fact('ТҮВШНЭЭР', ['A', 'B', 'C', 'D', 'E'].map(function (k) {
      return st.lv[k] ? '<b>' + k + '</b> ' + st.lv[k] : '';
    }).filter(Boolean).join(' &nbsp;·&nbsp; ') +
      (st.lv.un ? ' &nbsp;·&nbsp; <b>үнэлгээгүй</b> ' + st.lv.un : '') +
      ' &nbsp;=&nbsp; <b>' + st.rows.length + '</b>') +
    fact('ТАНИЛЦСАН', st.row
      ? '<b style="color:#059669">✓ ' + ackDateMn(st.row.at) + '</b> · ' + st.row.n + ' эрсдэл · гарын үсэг ' +
        '<b style="font-family:Consolas,monospace;letter-spacing:.12em">' + esc(st.row.code || '') + '</b>' +
        (st.row.read != null ? ' · нэг бүрчлэн уншсан ' + st.row.read + '/' + st.row.n : '')
      : (st.prev
        ? '<span style="color:#B45309">Хуучин хувилбарт зурсан (' + ackDateMn(st.prev.at) + ') — эрсдэл шинэчлэгдсэн тул дахин зурна</span>'
        : '<span style="color:#B91C1C">Хараахан зураагүй</span>'), '#334155') +
    fact('АРГА ХЭМЖЭЭ', mea.total
      ? mea.done + ' / ' + mea.total + ' баримтжуулсан' +
        (mea.late ? ' · <b style="color:#B91C1C">' + mea.late + ' хугацаа хэтэрсэн</b>' : '') +
        (mea.soon ? ' · ' + mea.soon + ' удахгүй дуусна' : '')
      : '<span style="color:#94A3B8">Оногдоогүй</span>') +
    fact('МӨРДӨХ ДҮРЭМ', st.rules ? st.rules + ' дүрэм (баримт шаардахгүй)' : '<span style="color:#94A3B8">—</span>') +
    (st.team
      ? fact('ТҮҮНИЙ БАГ', '<b style="color:' +
          (st.team.done >= st.team.n ? '#059669' : '#B45309') + '">' + st.team.done + ' / ' + st.team.n +
          '</b> ажилтан танилцсан' +
          (st.team.done < st.team.n
            ? ' · <span style="color:#B45309">' + (st.team.n - st.team.done) + ' хүн дээр гацаж байна</span>' : ''))
      : '');

  /* Санал */
  if ((st.ideas || []).length) {
    H += '<details style="margin-top:9px"><summary style="cursor:pointer;list-style:none;display:flex;' +
      'align-items:center;gap:7px;font-size:12px;font-weight:800;color:#4338CA">' +
      '<i class="ti ti-chevron-right" style="font-size:14px"></i>💡 Өгсөн санал (' + st.ideas.length + ')</summary>' +
      '<div style="margin-top:7px">' + st.ideas.slice(0, 40).map(function (i) {
        return '<div style="background:#EEF2FF;border:1px solid #E0E7FF;border-radius:10px;padding:8px 11px;margin-bottom:6px">' +
          '<div style="font-size:11.5px;color:#4338CA;font-weight:700">' + esc(String(i.hazard || '').slice(0, 90)) + '</div>' +
          '<div style="font-size:12.5px;color:#1E293B;margin-top:3px;line-height:1.55">' + esc(i.text || '') + '</div></div>';
      }).join('') + '</div></details>';
  }

  /* Эрсдэлийн жагсаалт */
  if (st.rows.length) {
    H += '<details style="margin-top:8px"><summary style="cursor:pointer;list-style:none;display:flex;' +
      'align-items:center;gap:7px;font-size:12px;font-weight:800;color:#475569">' +
      '<i class="ti ti-chevron-right" style="font-size:14px"></i>🛡 Эрсдэлүүд (' + st.rows.length + ')</summary>' +
      '<div style="margin-top:7px">' + riskCompactRowsHTML(st.rows.slice(0, 60)) +
      (st.rows.length > 60 ? '<div style="font-size:11.5px;color:#94A3B8;margin-top:6px">+' +
        (st.rows.length - 60) + ' эрсдэл</div>' : '') + '</div></details>';
  }
  return H + '</div></div>';
}

function renderPeoplePage(box) {
  if (!box) return;
  var me = reqMe();
  var admin = isAdmin() || isDeptHead();
  var subs = [];
  try { subs = pplMyPeople(); } catch (e) { subs = []; }

  var dept = riskCanonDept((me && me.dept) || (SESSION && SESSION.dept) || '') ||
    ((subs[0] && subs[0].dept) || '');
  /* ⚠ Хэсгийн зураглал ачаалагдаагүй бол ackSecOf() ХООСОН буцааж, хэсэг
     оноосон хүнд албаны бүх эрсдэл харагддаг байв. Заавал эхлээд татна. */
  /* ⚠⚠ ГАЦАЛТААС СЭРГИЙЛЭХ: өмнө нь ачаалалт бүтээгүй үед (сүлжээ)
     нөхцөл үргэлж үнэн байж, дахин зурах бүрд дахин ачаалах → МӨНХИЙН
     ДАВТАЛТ → САЙТ ГАЦДАГ байв. Одоо НЭГ УДАА л оролдоно. */
  if (!renderPeoplePage._once && dept) {
    renderPeoplePage._once = true;
    Promise.all([ackLoad(dept), ackSecLoad(true)])
      .then(function (res) {
        PPL_ACK = res[0] || { rows: [] };
        PPL_CACHE = {}; PPL_DEEP = {};
        var bx = document.querySelector('#riskTabPpl');
        if (bx) renderPeoplePage(bx);          /* зөвхөн энэ хайрцагыг */
      }).catch(function () { PPL_ACK = PPL_ACK || { rows: [] }; });
  }
  if (!PPL_ACK) PPL_ACK = { rows: [] };

  if (!subs.length) {
    box.innerHTML = '<div class="empty-state" style="padding:36px"><i class="ti ti-users"></i>' +
      '<div>Танд хариуцах ажилтан бүртгэгдээгүй байна</div>' +
      '<div style="font-size:12.5px;color:#94A3B8;margin-top:6px;line-height:1.6">' +
      'Хэсэг оноогоогүй байж магадгүй. ХАБЭА-н албанаас «Танилцсан байдал → Хэсгийн хуваарилалт»-аас тохируулна.</div></div>';
    return;
  }

  /* ⚡ Хэт олон ажилтантай үед (админ) хэсэгчлэн зурна */
  var LIMIT = 60;
  var stats = subs.map(function (e) { return pplEmpStat(e, false); })
    .sort(function (a, b) {
      if (!!a.row !== !!b.row) return a.row ? 1 : -1;    // зураагүй нь дээр
      return b.top - a.top;
    });
  var more = 0;
  if (stats.length > LIMIT && !PPL_ALL) { more = stats.length - LIMIT; stats = stats.slice(0, LIMIT); }
  var signed = stats.filter(function (s) { return s.row; }).length;
  var ideas = stats.reduce(function (a, s) { return a + (s.ideas || []).length; }, 0);
  /* Арга хэмжээний нийлбэрийг ЗӨВХӨН цөөн хүнтэй үед бодно (хүнд тооцоо) */
  var meaLate = 0, meaTot = 0, meaDoneN = 0, meaShow = stats.length <= 20;
  if (meaShow) {
    stats.forEach(function (s) {
      var d = s.deep ? s : pplEmpStat(s.e, true);
      meaLate += d.mst.late || 0; meaTot += d.mst.total || 0; meaDoneN += d.mst.done || 0;
    });
  }
  var pct = stats.length ? Math.round(signed * 100 / stats.length) : 0;

  var card = function (n, label, color) {
    return '<div style="flex:1;min-width:104px;background:' + color + '0D;border:1.5px solid ' + color +
      '2E;border-radius:13px;padding:11px 13px">' +
      '<div style="font-size:24px;font-weight:900;color:' + color + ';line-height:1;font-family:\'Bricolage Grotesque\',sans-serif">' + n + '</div>' +
      '<div style="font-size:11.5px;font-weight:700;color:' + color + ';margin-top:3px">' + label + '</div></div>';
  };

  box.innerHTML =
    '<div style="display:flex;align-items:center;gap:11px;flex-wrap:wrap;margin-bottom:12px">' +
    (function () {
      var d2 = ''; try { d2 = riskDirScope(); } catch (e) {}
      var ttl = d2 ? 'Албадын хариуцагч нарын байдал' : 'Миний хариуцах ажилтнууд';
      var sub = d2
        ? 'Таны танилцалт эдгээр хариуцагч нарыг хүлээдэг. Хэн дээр гацсан, баг нь хэдэн хувь гүйцэтгэсэн бэ.'
        : 'Ажилтан бүрийн эрсдэл, танилцалт, санал, арга хэмжээг нэг бүрчлэн. Мөр дээр дарж дэлгэрэнгүйг нээнэ.';
      return '<div><div style="font-size:15px;font-weight:800;color:#0F172A">' + ttl + '</div>' +
        '<div style="font-size:12.5px;color:#8A94A6;margin-top:2px">' + sub + '</div></div>';
    })() +
    '<button class="btn btn-primary btn-sm" data-ppl-pokeall="1" style="margin-left:auto">' +
    '<i class="ti ti-bell-ringing"></i> Зураагүй бүгдэд сануулах</button>' +
    '<button class="btn btn-secondary btn-sm" data-ppl-xl="1">' +
    '<i class="ti ti-file-spreadsheet"></i> Excel татах</button></div>' +
    '<div style="display:flex;gap:9px;flex-wrap:wrap;margin-bottom:13px">' +
    card(stats.length, 'ажилтан', '#4F46E5') +
    card(signed + ' / ' + stats.length, 'танилцсан', pct === 100 ? '#059669' : pct >= 50 ? '#D97706' : '#DC2626') +
    card(ideas, 'ирсэн санал', '#7C3AED') +
    (meaShow ? card(meaDoneN + ' / ' + meaTot, 'арга хэмжээ', '#0891B2') : '') +
    (meaShow ? card(meaLate, 'хугацаа хэтэрсэн', meaLate ? '#DC2626' : '#64748B') : '') +
    '</div>' +
    (function () {
      /* ⚠ АЖЛЫН БАЙРНЫ ҮНЭЛГЭЭ ХИЙГДЭЭГҮЙ — ХАБЭА-гаас
         шалтгаалах цоорхой. Хариуцагч үүнийг хараад шахах ёстой. */
      var gap = {};
      stats.forEach(function (x) {
        if (x.scope === 'pos' || x.scope === 'none') return;
        var p = x.e.pos || x.e.role || '—';
        gap[p] = (gap[p] || 0) + 1;
      });
      var ks = Object.keys(gap);
      if (!ks.length) return '';
      return '<div class="card" style="padding:13px 16px;margin-bottom:12px;border:1.5px solid #FDE68A;background:#FFFBEB">' +
        '<div style="font-size:13.5px;font-weight:800;color:#92400E;margin-bottom:3px">' +
        '⚠ Ажлын байрны үнэлгээ хийгдээгүй — ' + ks.length + ' ажлын байр</div>' +
        '<div style="font-size:12px;color:#8A6D3B;line-height:1.6;margin-bottom:8px">' +
        'Эдгээр хүмүүст албаны эрсдлийг ТҮР харуулж байна. Үнэлгээг ХАБЭА-н алба хийнэ.</div>' +
        '<div style="display:flex;gap:6px;flex-wrap:wrap">' +
        ks.sort(function (a, b) { return gap[b] - gap[a]; }).map(function (p) {
          return '<span style="background:#fff;border:1px solid #FDE68A;border-radius:8px;padding:4px 10px;' +
            'font-size:12px;color:#92400E;font-weight:700">' + esc(p) +
            ' <b style="color:#B45309">' + gap[p] + '</b></span>';
        }).join('') + '</div></div>';
    })() +
    (!PPL_ACK
      ? '<div style="font-size:12.5px;color:#94A3B8;margin-bottom:9px"><i class="ti ti-loader-2"></i> ' +
        'Танилцалтын мэдээллийг ачаалж байна…</div>'
      : '') +
    '<div class="card" style="padding:14px 16px">' +
    '<div style="display:flex;align-items:center;gap:10px;padding:0 13px 8px;font-size:10.5px;font-weight:800;' +
    'color:#94A3B8;letter-spacing:.4px;border-bottom:1px solid #F1F5F9;margin-bottom:9px">' +
    '<span style="flex:0 0 30px"></span><span style="flex:1">АЖИЛТАН</span>' +
    '<span class="rk-hide-sm" style="flex:0 0 168px">ТҮВШИН (A онцгой → E бага)</span>' +
    '<span style="flex:0 0 96px;text-align:center">ЭРСДЭЛ</span>' +
    '<span style="flex:0 0 128px;text-align:right">ТАНИЛЦСАН</span><span style="flex:0 0 18px"></span></div>' +
    stats.map(pplRowHTML).join('') +
    (more ? '<button class="btn" data-ppl-all="1" style="width:100%;margin-top:6px;padding:11px;' +
      'background:#F8FAFC;color:#475569;border:1.5px dashed #CBD5E1;border-radius:12px;font-weight:700">' +
      '<i class="ti ti-chevron-down"></i> Үлдсэн ' + more + ' ажилтныг үзэх</button>' : '') +
    '</div>';

  if (!box._pplWired) {
    box._pplWired = true;
    box.addEventListener('click', function (ev) {
      var o = ev.target.closest('[data-ppl-open]');
      if (o) {
        var uid = o.getAttribute('data-ppl-open');
        PPL_OPEN[uid] = !PPL_OPEN[uid];
        renderHazards();
        return;
      }
      if (ev.target.closest('[data-ppl-all]')) { PPL_ALL = true; renderHazards(); return; }
      var pk = ev.target.closest('[data-ppl-poke]');
      if (pk) { pplPoke([pk.getAttribute('data-ppl-poke')], stats, pk); return; }
      var pka = ev.target.closest('[data-ppl-pokeall]');
      if (pka) {
        var ids = stats.filter(function (x) { return !x.row; }).map(function (x) { return x.e.uid; });
        pplPoke(ids, stats, pka); return;
      }
      if (ev.target.closest('[data-ppl-xl]')) {
        /* Excel-д БҮГДИЙГ гүнзгий тооцоод оруулна */
        var full = subs.map(function (e) { return pplEmpStat(e, true); })
          .sort(function (a, b) { return (!!a.row !== !!b.row) ? (a.row ? 1 : -1) : (b.top - a.top); });
        pplExport(full); return;
      }
    });
  }
}

/* Хянагч ажилтанд САНУУЛНА — хонх + push.
   Энэ нь хариуцагчийн ГОЛ хэрэгсэл. */
function pplPoke(uids, stats, btn) {
  uids = (uids || []).filter(Boolean);
  if (!uids.length) { toast('Бүгд гарын үсгээ зурсан байна', 'info'); return; }
  var emps = (stats || []).filter(function (x) { return uids.indexOf(x.e.uid) >= 0; })
    .map(function (x) { return x.e; });
  if (!emps.length) return;
  var old = btn ? btn.innerHTML : '';
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="ti ti-loader-2"></i>'; }
  var me = reqMe();
  ntfSend(emps, {
    kind: 'ack',
    title: 'Эрсдэлтэй танилцаж гарын үсгээ зурна уу',
    body: ((me && me.name) || 'Хариуцагч') + ' танаас хүлээж байна. Эрсдэлүүдээ нэг бүрчлэн уншаад гарын үсгээ зурна уу.',
    url: '/kpi/?page=hazards'
  }).then(function () {
    if (btn) { btn.disabled = false; btn.innerHTML = old; }
    toast('✓ ' + emps.length + ' ажилтанд сануулга илгээлээ', 'success');
  }).catch(function (er) {
    if (btn) { btn.disabled = false; btn.innerHTML = old; }
    toast('Илгээж чадсангүй', 'error');
  });
}

/* Excel — ажилтан бүрийн бүрэн дата + саналууд тусдаа хуудсаар */
function pplExport(stats) {
  var me = reqMe();
  var aoa = [
    ['МОНОС ХҮНС ХХК'],
    ['ХАРИУЦАХ АЖИЛТНУУДЫН ЭРСДЭЛИЙН БАЙДАЛ'],
    [(me ? (me.name || '') + ' · ' + (me.pos || me.role || '') : '') +
     '   ·   Хэвлэсэн: ' + ackDateMn(new Date().toISOString())],
    [],
    ['д/д', 'Овог нэр', 'Албан тушаал', 'Алба', 'Хэсэг', 'Эрсдэл',
     'A онцгой', 'B өндөр', 'C дундаж', 'D бага', 'E ач бага', 'Үнэлгээгүй',
     'Хамгийн өндөр оноо', 'Эрсдэл хаанаас',
     'Танилцсан', 'Огноо', 'Гарын үсэг', 'Нэг бүрчлэн уншсан', 'Санал',
     'Арга хэмжээ', 'Баримтжуулсан', 'Хугацаа хэтэрсэн', 'Мөрдөх дүрэм']
  ];
  var ideas = [['д/д', 'Овог нэр', 'Албан тушаал', 'Эрсдэл', 'Өгсөн санал']];
  var k = 0;
  stats.forEach(function (s, i) {
    var sec = ''; try { sec = ackSecOf(s.e); } catch (e) {}
    aoa.push([i + 1, s.e.name || '', s.e.pos || s.e.role || '', s.e.dept || '', sec,
      s.rows.length, s.lv.A, s.lv.B, s.lv.C, s.lv.D, s.lv.E, s.lv.un, s.top || '',
      s.scope === 'pos' ? 'Ажлын байрных' : s.scope === 'none' ? 'Эрсдэлгүй' : 'Албаных (үнэлгээгүй)',
      s.row ? 'Тийм' : (s.prev ? 'Хуучин хувилбарт' : 'Үгүй'),
      s.row ? String(s.row.at).slice(0, 10) : '',
      s.row ? (s.row.code || '') : '',
      (s.row && s.row.read != null) ? s.row.read + '/' + s.row.n : '',
      (s.ideas || []).length, s.mst.total, s.mst.done, s.mst.late, s.rules]);
    (s.ideas || []).forEach(function (d) {
      ideas.push([++k, s.e.name || '', s.e.pos || s.e.role || '',
        String(d.hazard || '').slice(0, 140), d.text || '']);
    });
  });
  if (k === 0) ideas.push(['', '', '', 'Санал ирээгүй байна', '']);
  try {
    ackWriteBook([
      { name: 'Ажилтнууд', aoa: aoa,
        cols: [{ wch: 5 }, { wch: 24 }, { wch: 26 }, { wch: 24 }, { wch: 16 }, { wch: 9 },
               { wch: 9 }, { wch: 9 }, { wch: 10 }, { wch: 8 }, { wch: 10 }, { wch: 11 },
               { wch: 15 }, { wch: 20 },
               { wch: 12 }, { wch: 12 }, { wch: 12 }, { wch: 17 }, { wch: 8 },
               { wch: 12 }, { wch: 14 }, { wch: 16 }, { wch: 13 }] },
      { name: 'Санал', aoa: ideas,
        cols: [{ wch: 5 }, { wch: 24 }, { wch: 26 }, { wch: 46 }, { wch: 70 }] }
    ], 'Ажилтнуудын-эрсдэлийн-байдал-' + _ymd(new Date()) + '.xlsx');
  } catch (e) { toast('Excel үүсгэж чадсангүй: ' + ((e && e.message) || e), 'error'); }
}


function renderTasks() {
  var sec = pageEl('tasks'); if (!sec) return;
  sec.style.padding = '';
  /* ⚠ «Даалгавар» бол ТУСДАА цэс — эрсдэлээс гарсан арга хэмжээтэй хольж
     болохгүй. Арга хэмжээ нь ЭРСДЭЛИЙН ҮНЭЛГЭЭ цэсэн дээрээ (таб болж) ба
     эрсдэл бүрийн дэлгэрэнгүй дотроо гүйцэтгэгддэг. Энэ цэс нь удирдлага
     ажилтанд гараар даалгавар өгч, хянаж, үнэлдэг өөр үйл ажиллагаа. */
  DB.tasks = DB.tasks || [];
  var admin = isAdmin(), dh = isDeptHead(), emp = isEmp();
  var me = emp ? myEmp() : null;

  /* Role-д тохирсон даалгаврыг шүүх */
  var tasks = DB.tasks.filter(function (t) {
    if (admin) return true;
    if (dh && SESSION) {
      if (t.createdByEmail && t.createdByEmail === SESSION.email) return true;
      return SESSION.dept ? (t.dept === SESSION.dept || t.dept === 'all') : false;
    }
    if (emp) return me && (t.empId === me.id || (t.empIds && t.empIds.indexOf(me.id) > -1) || t.dept === me.dept || t.dept === 'all');
    return false;
  }).sort(taskSortFn);

  var review = tasks.filter(function (x) { return x.status === 'submitted'; });
  var open   = tasks.filter(function (x) { return x.status !== 'submitted' && !taskIsClosed(x); });
  var closed = tasks.filter(taskIsClosed);
  var myReview = review.filter(canReviewTask);
  var overdue = tasks.filter(function (x) { return taskOverdueDays(x) > 0; });

  /* Badge — хянагчид "хянах", ажилтанд "хийх" тоо */
  var badge = document.getElementById('taskBadge');
  var bn = (admin || dh) ? (myReview.length || open.length) : open.length;
  if (badge) { badge.textContent = bn; badge.style.display = bn ? 'inline-block' : 'none'; }

  var html = '<div class="page-header"><div><h1>Даалгавар</h1>' +
    '<p class="page-subtitle">Даалгавар өгөх → ажилтан гүйцэтгэх → хянагч үнэлгээ өгч баталгаажуулах</p></div>' +
    (admin || dh ? '<div class="page-actions"><button class="btn btn-primary" id="taskAdd"><i class="ti ti-plus"></i> Даалгавар нэмэх</button></div>' : '') +
    '</div>';

  html += '<div style="display:flex;gap:14px;flex-wrap:wrap;margin-bottom:18px">' +
    statCard('Нийт даалгавар', tasks.length, 'ti-checkbox', '#3730A3') +
    statCard('Хийгдэх', open.length, 'ti-clock', '#D97706') +
    statCard('Хянагдаж буй', review.length, 'ti-eye-search', '#7C3AED') +
    statCard('Хугацаа хэтэрсэн', overdue.length, 'ti-alarm', '#DC2626') +
    statCard('Баталгаажсан', closed.length, 'ti-circle-check', '#16A34A') +
    '</div>';

  function statusPill(x) {
    if (x.status === 'approved') {
      var s = taskScoreOf(x);
      var c = s >= 85 ? '#16A34A' : (s >= 70 ? '#0891B2' : (s >= 50 ? '#D97706' : '#DC2626'));
      return '<span style="background:' + c + '18;color:' + c + ';border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">✓ Баталгаажсан · ' + s + '%</span>';
    }
    if (x.status === 'done')      return '<span style="background:#16A34A18;color:#16A34A;border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">✓ Биелсэн</span>';
    if (x.status === 'submitted') return '<span style="background:#7C3AED18;color:#7C3AED;border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">⏳ Хянагдаж байна</span>';
    if (x.status === 'returned')  return '<span style="background:#DC262618;color:#DC2626;border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">↩ Буцаагдсан</span>';
    return '<span style="background:#64748B18;color:#64748B;border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">Хийгдэх</span>';
  }

  function taskCard(x) {
    var closedT = taskIsClosed(x);
    var od = taskOverdueDays(x), soon = taskDueSoon(x), late = taskLateDays(x);
    var pr = taskPrio(x);
    var deptLabel = x.dept === 'all' ? 'Бүх алба' : esc(x.dept || '');
    var ids = (x.empIds && x.empIds.length) ? x.empIds : (x.empId ? [x.empId] : []);
    var empLabel = ids.map(function (eid) { return esc(((DB.employees || []).filter(function (e) { return e.id === eid; })[0] || {}).name || eid); }).join(', ');
    var targetLabel = empLabel ? (deptLabel + ' · ' + empLabel) : deptLabel;

    /* Ажилтан өөрт нь оногдсон, хийгдээгүй даалгаврыг ИЛГЭЭНЭ */
    var mine = me && ids.indexOf(me.id) > -1;
    var canSubmit = !closedT && x.status !== 'submitted' && (mine || (emp && !ids.length));
    var canReview = x.status === 'submitted' && canReviewTask(x);
    var canRegrade = x.status === 'approved' && canReviewTask(x);

    var side = '#EEF1F4', ic = '#EFF6FF', icc = '#1D4ED8', icn = 'checkbox';
    if (x.status === 'submitted') { side = '#DDD6FE'; ic = '#F5F3FF'; icc = '#7C3AED'; icn = 'eye-search'; }
    else if (closedT)             { side = '#D1FAE5'; ic = '#D1FAE5'; icc = '#065F46'; icn = 'circle-check'; }
    else if (x.status === 'returned') { side = '#FECACA'; ic = '#FEF2F2'; icc = '#DC2626'; icn = 'arrow-back-up'; }

    return '<div style="background:#fff;border:1px solid ' + side + ';border-radius:12px;padding:14px 16px;margin-bottom:10px;display:flex;align-items:flex-start;gap:12px">' +
      '<div style="width:36px;height:36px;border-radius:9px;background:' + ic + ';color:' + icc + ';display:flex;align-items:center;justify-content:center;flex-shrink:0;font-size:18px"><i class="ti ti-' + icn + '"></i></div>' +
      '<div style="flex:1;min-width:0">' +
        '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap">' +
        '<span style="font-weight:600;font-size:14px' + (closedT ? ';color:#94A3B8' : '') + '">' + esc(x.title) + '</span>' +
        (!closedT && x.priority && x.priority !== 'normal' ? '<span style="background:' + pr.color + '18;color:' + pr.color + ';border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">' + esc(pr.label) + '</span>' : '') +
        (od ? '<span style="background:#DC262618;color:#DC2626;border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">⏰ ' + od + ' хоног хэтэрсэн</span>' : '') +
        (!od && soon ? '<span style="background:#D9770618;color:#D97706;border-radius:100px;padding:3px 10px;font-size:11.5px;font-weight:800">Хугацаа ойртсон</span>' : '') +
        statusPill(x) + '</div>' +
        taskBodyHTML(x) +
        '<div style="font-size:11px;color:#94A3B8;margin-top:6px;display:flex;gap:10px;flex-wrap:wrap">' +
        '<span><i class="ti ti-building"></i> ' + targetLabel + '</span>' +
        (x.category && TASK_CAT[x.category] ? '<span><i class="ti ti-tag"></i> ' + esc(TASK_CAT[x.category]) + '</span>' : '') +
        (x.startDate ? '<span style="color:#0891B2"><i class="ti ti-player-play"></i> Эхлэх: ' + esc(x.startDate) + '</span>' : '') +
        (x.dueDate ? '<span' + (od ? ' style="color:#DC2626;font-weight:700"' : (soon ? ' style="color:#D97706;font-weight:700"' : '')) + '><i class="ti ti-calendar"></i> Дуусах: ' + esc(x.dueDate) + '</span>' : '') +
        (x.repeat && TASK_REPEAT[x.repeat] ? '<span style="color:#7C3AED"><i class="ti ti-repeat"></i> ' + esc(TASK_REPEAT[x.repeat]) + '</span>' : '') +
        '<span><i class="ti ti-user"></i> ' + esc(x.createdBy || 'Админ') + '</span>' +
        (x.submittedAt ? '<span style="color:#7C3AED"><i class="ti ti-send"></i> ' + esc((x.submittedAt || '').slice(0, 10)) + (late ? ' (' + late + ' хоног хоцорсон)' : '') + '</span>' : '') +
        '</div>' +
        (x.refUrl ? '<div style="margin-top:8px"><a href="' + esc(x.refUrl) + '" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:#4F46E5;text-decoration:none;background:#EEF2FF;border-radius:8px;padding:6px 11px"><i class="ti ti-paperclip"></i> Заавар файл' + (x.refUrlName ? ': ' + esc(x.refUrlName) : '') + '</a></div>' : '') +
        (x.submitNote ? '<div style="margin-top:8px;background:#F8FAFC;border-radius:9px;padding:8px 11px;font-size:12.5px;color:#475569"><b>Ажилтны тайлбар:</b> ' + esc(x.submitNote) + '</div>' : '') +
        (x.proofUrl ? '<div style="margin-top:6px"><a href="' + esc(x.proofUrl) + '" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:6px;font-size:12.5px;color:#047857;text-decoration:none;background:#ECFDF5;border-radius:8px;padding:6px 11px"><i class="ti ti-photo-check"></i> Гүйцэтгэлийн нотолгоо' + (x.proofName ? ': ' + esc(x.proofName) : '') + '</a></div>' : '') +
        (x.reviewComment ? '<div style="margin-top:6px;background:#FFFBEB;border:1px solid #FDE68A;border-radius:9px;padding:8px 11px;font-size:12.5px;color:#92400E"><b>Хянагчийн тайлбар' + (x.reviewedBy ? ' (' + esc(x.reviewedBy) + ')' : '') + ':</b> ' + esc(x.reviewComment) + '</div>' : '') +
      '</div>' +
      '<div style="display:flex;gap:6px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end">' +
      (canSubmit ? '<button class="btn btn-sm" style="background:#EDE9FE;color:#5B21B6;border-color:#DDD6FE" data-task-submit="' + esc(x.id) + '"><i class="ti ti-send"></i> Гүйцэтгэсэн</button>' : '') +
      (canReview ? '<button class="btn btn-sm btn-primary" data-task-review="' + esc(x.id) + '"><i class="ti ti-eye-check"></i> Хянах</button>' : '') +
      (canRegrade ? '<button class="btn btn-sm" style="background:#F1F5F9;color:#475569;border-color:#E2E8F0" data-task-review="' + esc(x.id) + '"><i class="ti ti-pencil"></i> Дүн засах</button>' : '') +
      (admin ? '<button class="btn btn-sm" style="background:#FEE2E2;color:#991B1B;border-color:#FECACA" data-task-del="' + esc(x.id) + '"><i class="ti ti-trash"></i></button>' : '') +
      '</div></div>';
  }

  if (myReview.length) {
    html += '<div style="background:#F5F3FF;border:1.5px solid #DDD6FE;border-radius:14px;padding:14px 16px;margin-bottom:16px">' +
      '<div style="font-size:14px;font-weight:800;color:#5B21B6;margin-bottom:4px">⏳ Таны хянах ёстой ' + myReview.length + ' даалгавар</div>' +
      '<div style="font-size:12.5px;color:#6D28D9">Гүйцэтгэлийг нь үзээд үнэлгээ өгнө үү. Үнэлгээ нь ажилтны KPI оноонд шууд нөлөөлнө.</div></div>';
  }

  html += (review.length ? '<h3 style="margin:0 0 10px;font-size:15px;color:#7C3AED">Хянагдаж буй ' + review.length + '</h3>' + review.map(taskCard).join('') : '') +
    '<h3 style="margin:' + (review.length ? '18px' : '0') + ' 0 10px;font-size:15px">Хийгдэх ' + open.length + '</h3>' +
    (open.length ? open.map(taskCard).join('') : emptyBox('Хийгдэх даалгавар алга')) +
    (closed.length ? '<h3 style="margin:18px 0 10px;font-size:15px;color:#94A3B8">Баталгаажсан ' + closed.length + '</h3>' + closed.map(taskCard).join('') : '');

  sec.innerHTML = html;

  if (!sec._taskWired) {
    sec._taskWired = true;
    sec.addEventListener('click', function (ev) {
      if (ev.target.closest('#taskAdd')) { actionAddTask(); return; }

      /* Даалгавар доторх «Эрсдэлийн дэлгэрэнгүй» */
      var ro = ev.target.closest('[data-risk-open]');
      if (ro) { riskOpenDetail(ro.getAttribute('data-risk-open')); return; }

      var sb = ev.target.closest('[data-task-submit]');
      if (sb) { actionSubmitTask(sb.getAttribute('data-task-submit')); return; }

      var rv = ev.target.closest('[data-task-review]');
      if (rv) { actionReviewTask(rv.getAttribute('data-task-review')); return; }

      var dl = ev.target.closest('[data-task-del]');
      if (dl) {
        var tid2 = dl.getAttribute('data-task-del');
        if (!confirm('Энэ даалгаврыг устгах уу?')) return;
        DB.tasks = DB.tasks.filter(function (x) { return x.id !== tid2; });
        saveDB(); renderTasks(); renderDashboard();
        toast('Даалгавар устгагдлаа', 'warn');
      }
    });
  }
}

/* ── Ажилтан гүйцэтгээд хянуулахаар илгээх ── */
function actionSubmitTask(tid) {
  var x = (DB.tasks || []).filter(function (y) { return y.id === tid; })[0];
  if (!x) return;
  formModal({
    title: 'Даалгавар гүйцэтгэсэн — ' + (x.title || ''),
    width: '480px',
    fields: [
      { name: 'note', label: 'Юу хийснээ товч бичнэ үү (заавал биш)', type: 'textarea', rows: 4,
        placeholder: 'Жишээ: Цехийн гал унтраагуурыг бүрэн шалгаж, 2 ширхгийг сольсон.' },
      { name: 'proof', label: '📷 Гүйцэтгэлийн нотолгоо — зураг эсвэл файл (заавал биш)', type: 'file',
        accept: 'image/*,.pdf,.doc,.docx,.xls,.xlsx' }
    ],
    submitLabel: 'Хянуулахаар илгээх',
    onSubmit: function (v) {
      x.status = 'submitted';
      x.submitNote = (v.note || '').trim();
      x.proofUrl = v.proof || '';
      x.proofName = v.proofName || '';
      x.submittedBy = USER.name;
      x.submittedAt = new Date().toISOString();
      x.reviewComment = '';
      saveDB(); renderTasks(); renderDashboard();
      toast('Хянуулахаар илгээгдлээ. Хянагч үнэлгээ өгнө.', 'success');
    }
  });
}

/* ── Хянагч үнэлгээ өгч баталгаажуулах ── */
function actionReviewTask(tid) {
  var x = (DB.tasks || []).filter(function (y) { return y.id === tid; })[0];
  if (!x) return;
  if (!canReviewTask(x)) { toast('Танд энэ даалгаврыг хянах эрх байхгүй', 'warn'); return; }
  var ids = (x.empIds && x.empIds.length) ? x.empIds : (x.empId ? [x.empId] : []);
  var who = ids.map(function (id) { return ((DB.employees || []).filter(function (e) { return e.id === id; })[0] || {}).name || id; }).join(', ');

  var lateN = taskLateDays(x);
  var lateTxt = lateN ? ' ⏰ ХУГАЦАА ' + lateN + ' ХОНОГ ХОЦОРСОН' : '';
  var proofTxt = x.proofUrl ? ' 📎 Нотолгоо хавсаргасан' : ' ⚠ Нотолгоо хавсаргаагүй';

  formModal({
    title: 'Гүйцэтгэл хянах — ' + (x.title || ''),
    width: '540px',
    fields: [
      { name: 'score', label: 'Гүйцэтгэлийн үнэлгээ' + (who ? ' · ' + who : '') + lateTxt + ' ·' + proofTxt, type: 'select',
        value: String(x.score != null ? x.score : 100),
        options: [
          { value: '100', label: '100% — Маш сайн, бүрэн гүйцэт' },
          { value: '85',  label: '85% — Сайн, бага зэрэг дутуу' },
          { value: '70',  label: '70% — Дунд, засах зүйлтэй' },
          { value: '50',  label: '50% — Хангалтгүй' },
          { value: '30',  label: '30% — Маш муу' },
          { value: '0',   label: '0% — Огт хийгээгүйтэй адил' }
        ] },
      { name: 'comment', label: 'Тайлбар (ажилтан харна)', type: 'textarea', rows: 3,
        value: x.reviewComment || '', placeholder: 'Юуг сайжруулах ёстойг бичвэл ажилтанд тустай.' },
      { name: 'decision', label: 'Шийдвэр', type: 'select', value: 'approve',
        options: [
          { value: 'approve', label: '✅ Баталгаажуулах (үнэлгээ хүчинтэй болно)' },
          { value: 'return',  label: '↩ Буцаах — дахин хийлгэх' }
        ] }
    ],
    submitLabel: 'Хадгалах',
    onSubmit: function (v) {
      x.reviewComment = (v.comment || '').trim();
      x.reviewedBy = USER.name;
      x.reviewedAt = new Date().toISOString();
      if (v.decision === 'return') {
        x.status = 'returned';
        x.score = null;
        saveDB(); renderTasks(); renderDashboard();
        toast('Даалгавар буцаагдлаа. Ажилтан дахин гүйцэтгэнэ.', 'warn');
        return;
      }
      var s = clamp(parseInt(v.score, 10) || 0, 0, 100);
      x.status = 'approved';
      x.score = s;
      x.completedBy = x.submittedBy || USER.name;
      x.completedAt = x.submittedAt || new Date().toISOString();
      try { taskRepeatNext(x); } catch (err) { console.error('[task repeat]', err); }
      saveDB(); renderTasks(); renderDashboard();
      toast('Баталгаажлаа · үнэлгээ ' + s + '%' + (x.repeat ? ' · дараагийнх автоматаар үүслээ' : '') + ' — KPI-д тооцогдлоо', 'success');
    }
  });
}
