    add('.nav-item[data-page="dashboard"]', 'Хяналтын самбар',
      'Компанийн ерөнхий үзүүлэлт, албадын харьцуулалт.');
    add('[data-batch-training]', 'Бүлэг сургалт нэмэх',
      'Олон ажилтанд нэг дор сургалт оноох.');
